  const response = await api(`/v1/bank-imports/${pendingBankImport.id}/commit`, {
    ...jsonRequest({ version: pendingBankImport.version }),
    headers: {
      "content-type": "application/json",
      "idempotency-key": globalThis.crypto.randomUUID()
    }
  });
