function localCalendarDate() {
  const date = new Date();
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function normalizeHomeAsOf(value) {
  const candidate = String(value ?? "");
  if (!/^\d{4}-\d{2}-\d{2}$/.test(candidate)) return null;
  const [year, month, day] = candidate.split("-").map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  return date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
    ? candidate
    : null;
}

function homeAsOfStorageKey() {
  const email = identity?.email?.trim().toLowerCase();
  const organizationId = identity?.activeOrganizationId;
  if (!email || !organizationId) return null;
  return `clearledger_home_as_of:v${homeAsOfPreferenceVersion}:${encodeURIComponent(email)}:${encodeURIComponent(organizationId)}`;
}

function homeAsOfDate() {
  const stored = normalizeHomeAsOf(readBrowserPreference(homeAsOfStorageKey() ?? ""));
  return stored ?? localCalendarDate();
}

function saveHomeAsOf(asOf) {
  const key = homeAsOfStorageKey();
  if (key) writeBrowserPreference(key, asOf);
}

function setHomeDataState(state, message, { action = false } = {}) {
  const status = elements["home-data-status"];
  status.dataset.state = state;
  status.hidden = !message;
  elements["home-data-status-message"].textContent = message ?? "";
  elements["home-data-status-action"].hidden = !action;
  elements["home-data-status-action"].disabled = false;
  elements["overview-workspace"].setAttribute("aria-busy", String(state === "loading"));
}

function initializeHomeAsOfControl() {
  const asOf = homeAsOfDate();
  elements["home-as-of-input"].value = asOf;
  return asOf;
}

async function loadHomeDashboard({ announce = false } = {}) {
  if (!identity?.activeOrganizationId) return;
  const requestVersion = ++homeDashboardRequestVersion;
  const asOf = initializeHomeAsOfControl();
  const hadData = elements["overview-workspace"].dataset.dashboardLoaded === "true";
  // A new blank company has no control accounts yet. Do not ask the accounting
  // dashboard to calculate balances and then surface its expected 422 in the
  // browser console; render the existing setup-safe state instead. The setup
  // workflow is the source of truth here because the membership summary can
  // briefly remain stale after an account preset is applied.
  const industryPresetStatus = setup?.steps?.find(
    (step) => step.step === "INDUSTRY_PRESET"
  )?.status;
  const dashboardRequiresSetup =
    Boolean(industryPresetStatus) && !["COMPLETED", "SKIPPED"].includes(industryPresetStatus);
  setHomeDataState(
    "loading",
    hadData || announce ? `Refreshing dashboard as of ${asOf}…` : "Loading your dashboard…"
  );
  const [response, booksHealthResponse] = await Promise.all([
    dashboardRequiresSetup
      ? Promise.resolve(null)
      : api(`/v1/dashboard?asOf=${encodeURIComponent(asOf)}`, {}, true),
    dashboardRequiresSetup
      ? Promise.resolve(null)
      : api(`/v1/books-health?asOf=${encodeURIComponent(asOf)}`, {}, true)
  ]);
  if (requestVersion !== homeDashboardRequestVersion) return;
  if (booksHealthResponse?.ok) {
    try {
      renderBooksHealth((await booksHealthResponse.json()).booksHealth);
    } catch {
      renderBooksHealthUnavailable("Books Health returned an unreadable response.");
    }
  } else if (booksHealthResponse) {
    renderBooksHealthUnavailable(
      booksHealthResponse.status === 401 || booksHealthResponse.status === 403
        ? "Books Health is not available for your current role."
        : undefined
    );
  } else {
    renderBooksHealthUnavailable(
      "Complete company setup to begin the read-only Books Health check."
    );
  }
  if (dashboardRequiresSetup) {
    renderHomeDashboardUnavailable(422, asOf);
    return;
  }
  if (!response?.ok) {
    renderHomeDashboardUnavailable(response?.status ?? 503, asOf);
    return;
  }
  try {
    renderHomeDashboard((await response.json()).dashboard);
  } catch {
    renderHomeDashboardUnavailable(500, asOf);
  }
}

async function refreshHomeDashboard() {
  const button = elements["refresh-home-dashboard"];
  button.disabled = true;
  button.textContent = "Refreshing…";
  try {
    await loadHomeDashboard();
  } finally {
    button.disabled = false;
    button.textContent = "Refresh";
  }
}

async function loadBooksHealth() {
  if (!identity?.activeOrganizationId) return;
  const button = elements["refresh-books-health"];
  button.disabled = true;
  elements["books-health-summary"].textContent = "Refreshing five read-only checks…";
  try {
    const asOf = initializeHomeAsOfControl();
    const response = await api(`/v1/books-health?asOf=${encodeURIComponent(asOf)}`, {}, true);
    if (!response.ok) {
      renderBooksHealthUnavailable(
        response.status === 401 || response.status === 403
          ? "Books Health is not available for your current role."
          : undefined
      );
      return;
    }
    renderBooksHealth((await response.json()).booksHealth);
    trackProductEvent("CLOSE_READINESS_VIEWED");
  } finally {
    button.disabled = false;
  }
}

function renderBooksHealth(booksHealth) {
  if (booksHealth?.mode !== "READ_ONLY" || booksHealth?.accountingEntriesCreated !== 0) {
    renderBooksHealthUnavailable(
      "Books Health returned an unexpected safety response, so its findings are hidden."
    );
    return;
  }
  booksHealthSnapshot = booksHealth;
  const summary = booksHealth.summary ?? {};
  elements["books-health-card"].dataset.status = booksHealth.status;
  elements["books-health-summary"].textContent =
    booksHealth.status === "NO_FINDINGS"
      ? `Good · ${summary.checkedAreas ?? 5} areas checked`
      : `${countLabel(summary.blockerCount, "blocker", "blockers")} · ${countLabel(summary.warningCount, "warning", "warnings")} · ${countLabel(summary.noticeCount, "notice", "notices")}`;
  elements["books-health-disclaimer"].textContent = booksHealth.disclaimer;

  const areaLabels = new Map((booksHealth.areas ?? []).map((area) => [area.category, area.label]));
  const severityFilter = elements["books-health-severity-filter"].value;
  const findings = (booksHealth.findings ?? []).filter(
    (finding) => severityFilter === "ALL" || finding.severity === severityFilter
  );
  if (!booksHealth.findings?.length || !findings.length) {
    elements["toggle-books-health"].hidden = true;
    elements["books-health-card"].dataset.collapsible = "false";
    setBooksHealthExpanded(false);
    const empty = document.createElement("p");
    empty.className = "empty-state books-health-clear";
    empty.textContent = booksHealth.findings?.length
      ? "No checks match this severity filter. Choose All checks to see the complete review list."
      : "No automated exceptions were found in commerce, banking, imports, tax settings, or period close.";
    elements["books-health-findings"].replaceChildren(empty);
    return;
  }

  // The one-line clamp on a finding exists to keep a long list compact. When
  // there are too few findings to warrant the "View all checks" expander, the
  // clamp had nothing to expand it with and simply cut the text off mid-sentence,
  // so the collapsible state drives both the button and the clamp.
  const collapsible = findings.length > 2;
  elements["toggle-books-health"].hidden = !collapsible;
  elements["books-health-card"].dataset.collapsible = String(collapsible);
  setBooksHealthExpanded(false);

  elements["books-health-findings"].replaceChildren(
    ...findings.map((finding) => {
      const row = document.createElement("article");
      row.className = "books-health-finding";
      row.dataset.severity = finding.severity;
      const copy = document.createElement("div");
      copy.className = "books-health-finding-copy";
      const meta = document.createElement("p");
      meta.className = "books-health-finding-meta";
      const severity = document.createElement("span");
      severity.className = "books-health-severity";
      severity.textContent =
        finding.severity === "BLOCKER"
          ? "Action needed"
          : finding.severity === "WARNING"
            ? "Review"
            : "Notice";
      const category = document.createElement("span");
      category.textContent = `${areaLabels.get(finding.category) ?? finding.category} · ${countLabel(finding.count, "item", "items")}`;
      meta.append(severity, category);
      const title = document.createElement("h3");
      title.textContent = finding.title;
      const reason = document.createElement("p");
      reason.textContent = finding.reason;
      copy.append(meta, title, reason);
      const action = document.createElement("button");
      action.type = "button";
      action.className = "secondary-command books-health-action";
      action.textContent = finding.target.label;
      action.addEventListener("click", () => openBooksHealthTarget(finding.target));
      row.append(copy, action);
      return row;
    })
  );
}

function renderBooksHealthUnavailable(
  message = "Books Health could not be refreshed. Other Home information remains available."
) {
  booksHealthSnapshot = null;
  elements["books-health-card"].dataset.status = "UNAVAILABLE";
  elements["toggle-books-health"].hidden = true;
  setBooksHealthExpanded(false);
  elements["books-health-summary"].textContent = message;
  const empty = document.createElement("p");
  empty.className = "empty-state";
  empty.textContent =
    "Try Refresh checks. PennyWise Accounting will not treat an unavailable check as all clear.";
  elements["books-health-findings"].replaceChildren(empty);
  elements["books-health-disclaimer"].textContent =
    "Books Health is read-only and never posts accounting entries. An unavailable check is not professional approval.";
}

function toggleBooksHealth() {
  setBooksHealthExpanded(elements["books-health-card"].dataset.expanded !== "true");
}

function setBooksHealthExpanded(expanded) {
  elements["books-health-card"].dataset.expanded = String(expanded);
  elements["toggle-books-health"].setAttribute("aria-expanded", String(expanded));
  elements["toggle-books-health"].textContent = expanded ? "Show fewer checks" : "View all checks";
}

function openBooksHealthTarget(target) {
  if (!target || !workspaceIds.includes(target.workspaceId)) return;
  activateWorkspace(target.workspaceId);
  if (target.setupStep && setup?.steps?.some((step) => step.step === target.setupStep)) {
    showSetupStep(target.setupStep);
  }
  globalThis.setTimeout(() => {
    const destination = document.getElementById(target.anchorId);
    destination?.scrollIntoView({ behavior: preferredScrollBehavior(), block: "start" });
    if (destination) {
      destination.setAttribute("tabindex", "-1");
      destination.focus({ preventScroll: true });
    }
  }, 120);
}

function countLabel(value, singular, plural) {
  const count = Number(value ?? 0);
  return `${count} ${count === 1 ? singular : plural}`;
}

function renderHomeDashboard(dashboard) {
  currentReportState = { ...(currentReportState ?? {}), dashboard };
  elements["overview-workspace"].dataset.dashboardLoaded = "true";
  elements["home-as-of-label"].textContent = `As of ${dashboard.asOf}`;
  setHomeDataState("ready", `Dashboard updated for ${dashboard.asOf}.`);
  const bankItems = Number(dashboard.unreconciledBankItems ?? 0);
  const lowStock = Array.isArray(dashboard.lowStock) ? dashboard.lowStock : [];
  const attentionItems = [];
  if (bankItems > 0) {
    attentionItems.push({
      title: `${bankItems} bank item${bankItems === 1 ? "" : "s"} to review`,
      detail: "Match, categorize, transfer, or exclude each item before reconciling.",
      action: "Review banking",
      workspaceId: "banking-workspace",
      tone: "attention"
    });
  }
  if (minorIsNonZero(dashboard.overdueInvoicesMinor)) {
    const overdue = dashboardMoney(dashboard.overdueInvoicesMinor, dashboard.currency, "Overdue");
    attentionItems.push({
      title: `${overdue.text} overdue`,
      detail: "Receivables are past due and may need customer follow-up.",
      action: "View invoices",
      workspaceId: "sales-workspace",
      tone: "overdue"
    });
  }
  if (minorIsNonZero(dashboard.upcomingBillsMinor)) {
    const dueSoon = dashboardMoney(
      dashboard.upcomingBillsMinor,
      dashboard.currency,
      "Bills due soon"
    );
    attentionItems.push({
      title: `${dueSoon.text} in bills due soon`,
      detail: "Review payment timing against available cash.",
      action: "Review bills",
      workspaceId: "purchases-workspace",
      tone: "attention"
    });
  }
  if (lowStock.length > 0) {
    attentionItems.push({
      title: `${lowStock.length} product${lowStock.length === 1 ? "" : "s"} at or below reorder point`,
      detail: "Review quantities before the next sale or purchase.",
      action: "Review inventory",
      workspaceId: "inventory-workspace",
      tone: "attention"
    });
  }
  if (!attentionItems.length) {
    attentionItems.push({
      title: "No immediate dashboard exceptions",
      detail:
        "No overdue receivables, bank items, bills due soon, or low-stock alerts were found. Books Health may list other checks.",
      action: null,
      workspaceId: null,
      tone: "complete"
    });
  }
  elements["home-attention-list"].replaceChildren(
    ...attentionItems.map((item) => {
      const row = document.createElement("article");
      row.className = "attention-row";
      row.dataset.tone = item.tone;
      const marker = document.createElement("span");
      marker.className = "attention-marker";
      marker.setAttribute("aria-hidden", "true");
      marker.textContent = item.tone === "complete" ? "✓" : "!";
      const copy = document.createElement("div");
      const title = document.createElement("h3");
      const detail = document.createElement("p");
      title.textContent = item.title;
      detail.textContent = item.detail;
      copy.append(title, detail);
      row.append(marker, copy);
      if (item.action && item.workspaceId) {
        const action = document.createElement("button");
        action.type = "button";
        action.className = "text-command";
        action.textContent = item.action;
        action.addEventListener("click", () => activateWorkspace(item.workspaceId));
        row.append(action);
      }
      return row;
    })
  );
  // "Cash balance" is the first tile of the business summary band directly above
  // this panel; repeating it here said the same number twice and cost a row that
  // Cash & tax could use for something the operator cannot already see.
  const positionMetrics = [
    ["Estimated tax position", dashboard.estimatedTaxPositionMinor],
    ["Bank items to review", String(bankItems), "count"]
  ];
  elements["home-cash-overview"].replaceChildren(
    ...positionMetrics.map(([label, value, kind]) => {
      const group = document.createElement("div");
      const term = document.createElement("dt");
      const detail = document.createElement("dd");
      term.textContent = label;
      detail.textContent =
        kind === "count" ? value : dashboardMoney(value, dashboard.currency, label).text;
      group.append(term, detail);
      return group;
    })
  );
  const summary = [
    ["Cash balance", dashboard.cashMinor, "banking", "cash"],
    ["Receivables", dashboard.unpaidInvoicesMinor, "receivables", "receivables"],
    ["Upcoming bills", dashboard.upcomingBillsMinor, "payables", "payables"],
    ["Sales this month", dashboard.salesThisMonthMinor, "sales", "profit"],
    ["Expenses this month", dashboard.expensesThisMonthMinor, "expenses", "profit"],
    ["Estimated profit", dashboard.estimatedProfitMinor, "profit-and-loss", "profit"]
  ];
  delete elements["home-business-summary"].dataset.state;
  delete elements["overview-workspace"].dataset.dashboardData;
  const summaryNodes = summary.map(([label, value, reportName, linkKey]) => {
    const group = document.createElement("div");
    const term = document.createElement("dt");
    const detail = document.createElement("dd");
    const action = document.createElement("button");
    term.textContent = label;
    action.type = "button";
    action.className = "summary-value";
    const money = dashboardMoney(value, dashboard.currency, label);
    action.textContent = money.text;
    action.setAttribute("aria-label", money.aria);
    action.title = money.aria;
    action.addEventListener("click", () =>
      openHomeReport(reportName, dashboard.links?.[linkKey], dashboard.asOf)
    );
    detail.append(action);
    group.append(term, detail);
    return group;
  });
  if (
    multiCurrencyState?.enabled &&
    Array.isArray(dashboard.foreignExposure) &&
    dashboard.foreignExposure.length
  ) {
    const group = document.createElement("div");
    const term = document.createElement("dt");
    const detail = document.createElement("dd");
    const action = document.createElement("button");
    term.textContent = "Foreign exposure";
    action.type = "button";
    action.className = "summary-value";
    const exposure = dashboard.foreignExposure
      .map((item) => `${item.currency} ${reportMoneyText(item.amountMinor, dashboard.currency)}`)
      .join(", ");
    action.textContent = dashboardAmountsHidden() ? "••••" : exposure;
    action.setAttribute(
      "aria-label",
      dashboardAmountsHidden() ? "Foreign exposure: amount hidden" : `Foreign exposure: ${exposure}`
    );
    action.addEventListener("click", () =>
      openHomeReport("receivables", dashboard.links?.receivables, dashboard.asOf)
    );
    detail.append(action);
    group.append(term, detail);
    summaryNodes.push(group);
  }
  elements["home-business-summary"].replaceChildren(...summaryNodes);
}

function openHomeReport(reportName, link, asOf) {
  const form = elements["report-filter-form"];
  const reportUrl = link ? new URL(`/api${link}`, window.location.origin) : null;
  const query = reportUrl ? reportUrl.searchParams : new URLSearchParams();
  const selectedAsOf = normalizeHomeAsOf(query.get("asOf") ?? asOf) ?? homeAsOfDate();
  const selectedFrom = normalizeHomeAsOf(query.get("from"));
  const selectedTo = normalizeHomeAsOf(query.get("to"));
  form.elements.reportName.value = reportName;
  form.elements.asOf.value = selectedAsOf;
  form.elements.from.value = selectedFrom ?? `${selectedAsOf.slice(0, 8)}01`;
  form.elements.to.value = selectedTo ?? selectedAsOf;
  activateWorkspace("reports-workspace", true, false);
  void runSelectedReport();
}

function buildDashboardUnavailableNotice(setupRequired, permissionDenied) {
  const notice = document.createElement("div");
  notice.className = "home-summary-unavailable";
  const heading = document.createElement("p");
  heading.className = "home-summary-unavailable-title";
  heading.textContent = permissionDenied
    ? "Financial indicators are not available for your role"
    : setupRequired
      ? "Financial indicators appear once company setup is complete"
      : "Financial indicators are unavailable right now";
  const detail = document.createElement("p");
  detail.className = "home-summary-unavailable-detail";
  detail.textContent = permissionDenied
    ? "Ask an owner or administrator if you need access to balances and review counts."
    : setupRequired
      ? "Add your business profile, fiscal year, and starting accounts. PennyWise Accounting will not replace missing accounting configuration with zeroes."
      : "No zero values were assumed. Refresh before relying on balances or review counts.";
  // No action button here on purpose: "Needs attention" directly below is the
  // established place for a task and its action, and rendering "Open company
  // setup" in both panels put the same button on screen twice. This panel
  // explains why the figures are absent; that one carries the task.
  notice.append(heading, detail);
  return notice;
}

function renderHomeDashboardUnavailable(statusCode, asOf) {
  const hasPreviousData = elements["overview-workspace"].dataset.dashboardLoaded === "true";
  const permissionDenied = statusCode === 401 || statusCode === 403;
  const setupRequired = statusCode === 422;
  const message = permissionDenied
    ? "Dashboard access is not available for your current role."
    : setupRequired
      ? "Complete company setup to activate your dashboard."
      : statusCode === 503
        ? "The dashboard service is unavailable."
        : "The dashboard could not be refreshed.";
  elements["home-as-of-label"].textContent = hasPreviousData
    ? `Showing the last successful dashboard · as of ${elements["home-as-of-label"].textContent.replace(/^As of /, "")}`
    : "Current data unavailable";
  // Incomplete setup is an expected state for a new company, not a failure: it
  // gets its own neutral treatment rather than the danger colour, and no
  // "Try again" — retrying cannot succeed until the operator finishes setup.
  setHomeDataState(
    permissionDenied ? "permission" : setupRequired ? "setup" : "error",
    hasPreviousData ? `${message} Previous values remain visible.` : message,
    { action: !permissionDenied && !setupRequired }
  );
  if (hasPreviousData) return;
  if (!permissionDenied) elements["home-as-of-label"].textContent = `As of ${asOf} · unavailable`;
  // Nine consecutive "Unavailable" cells (six here, three in Cash & tax) said one
  // thing nine times and buried the only sentence that helped. Say it once, in
  // the band's own space, and keep the guarantee that no zeroes were assumed.
  elements["home-business-summary"].dataset.state = "unavailable";
  elements["home-business-summary"].replaceChildren(
    buildDashboardUnavailableNotice(setupRequired, permissionDenied)
  );
  // Not `.hidden` — that property is owned by the tile-preference system, and
  // writing it here would silently override the user's own show/hide choice.
  elements["overview-workspace"].dataset.dashboardData = "unavailable";
  const row = document.createElement("article");
  row.className = "attention-row";
  row.dataset.tone = "unavailable";
  const marker = document.createElement("span");
  marker.className = "attention-marker";
  marker.setAttribute("aria-hidden", "true");
  marker.textContent = "—";
  const copy = document.createElement("div");
  const title = document.createElement("h3");
  title.textContent = setupRequired
    ? "Finish setup before relying on financial values"
    : "Dashboard values are unavailable";
  const detail = document.createElement("p");
  detail.textContent = setupRequired
    ? "Add your business profile, fiscal year, and starting accounts. PennyWise Accounting will not replace missing accounting configuration with zeroes."
    : "Refresh before relying on balances or review counts. No zero values were assumed.";
  copy.append(title, detail);
  row.append(marker, copy);
  // "Try again" is only honest when retrying can succeed. Incomplete setup is not
  // a failed request; retrying it will never work until the operator finishes setup.
  if (!permissionDenied && !setupRequired) {
    const retry = document.createElement("button");
    retry.type = "button";
    retry.className = "text-command";
    retry.textContent = "Try again";
    retry.addEventListener("click", refreshHomeDashboard);
    row.append(retry);
  } else if (setupRequired) {
    const openSetup = document.createElement("button");
    openSetup.type = "button";
    openSetup.className = "text-command";
    openSetup.textContent = "Open company setup";
    openSetup.addEventListener("click", () => activateWorkspace("setup-workspace"));
    row.append(openSetup);
  }
  elements["home-attention-list"].replaceChildren(row);
  elements["home-cash-overview"].replaceChildren(
    ...["Cash balance", "Estimated tax position", "Bank items to review"].map((label) =>
      unavailableMetric(label)
    )
  );
}

function unavailableMetric(label) {
  const group = document.createElement("div");
  const term = document.createElement("dt");
  const detail = document.createElement("dd");
  term.textContent = label;
  detail.textContent = "Unavailable";
  group.append(term, detail);
  return group;
}

function dashboardAmountsHidden() {
  return readScopedDashboardPreference("clearledger_dashboard_hide_amounts") === "true";
}

function initializeDashboardAmountPrivacy() {
  elements["hide-dashboard-amounts"].checked = dashboardAmountsHidden();
}

function handleDashboardAmountPrivacyChange(event) {
  const hidden = event.currentTarget.checked;
  writeScopedDashboardPreference("clearledger_dashboard_hide_amounts", String(hidden));
  renderDashboard(currentReportState?.dashboard ?? null);
  if (elements["overview-workspace"].dataset.dashboardLoaded === "true") void loadHomeDashboard();
  elements["dashboard-editor-status"].textContent = hidden
    ? "Dashboard amounts are hidden in this browser for this business."
    : "Dashboard amounts are visible in this browser for this business.";
}

function dashboardMoney(value, currency, label) {
  if (dashboardAmountsHidden()) return { text: "••••", aria: `${label}: amount hidden` };
  const text = formatMinor(value, currency);
  return { text, aria: `${label}: ${text}` };
}

function reportBaseCurrency() {
  return multiCurrencyState?.baseCurrency ?? setup?.settings?.baseCurrency ?? "CAD";
}

function updateReportHeaderLine() {
  const selected = elements["report-currency-filter"]?.value;
  const currency = !selected || selected === "base" ? reportBaseCurrency() : selected;
  elements["report-header-line"].textContent =
    currency === reportBaseCurrency()
      ? `Amounts in ${currency} (base currency)`
      : `Amounts shown in ${currency}`;
}

function refreshReportCurrencyOptions() {
  const select = elements["report-currency-filter"];
  const selected = select.value || "base";
  const currencies = [
    { value: "base", label: `${reportBaseCurrency()} (base currency)` },
    ...(multiCurrencyState?.enabled
      ? (multiCurrencyState.currencies ?? [])
          .filter((currency) => currency.enabled && currency.currencyCode !== reportBaseCurrency())
          .map((currency) => ({ value: currency.currencyCode, label: currency.currencyCode }))
      : [])
  ];
  select.replaceChildren(...currencies.map(({ value, label }) => option(value, label)));
  select.value = currencies.some((currency) => currency.value === selected) ? selected : "base";
  updateReportHeaderLine();
}

function isoDate(date) {
  return date.toISOString().slice(0, 10);
}

function applyReportPeriodPreset() {
  const preset = elements["report-period-preset"].value;
  if (preset === "custom") return;
  const anchor = new Date(
    `${elements["report-filter-form"].elements.asOf.value || isoDate(new Date())}T00:00:00Z`
  );
  if (!Number.isFinite(anchor.getTime())) return;
  const year = anchor.getUTCFullYear();
  const month = anchor.getUTCMonth();
  let from;
  let to;
  if (preset === "this-month") {
    from = new Date(Date.UTC(year, month, 1));
    to = new Date(Date.UTC(year, month + 1, 0));
  } else if (preset === "last-month") {
    from = new Date(Date.UTC(year, month - 1, 1));
    to = new Date(Date.UTC(year, month, 0));
  } else if (preset === "this-quarter") {
    const quarterStart = Math.floor(month / 3) * 3;
    from = new Date(Date.UTC(year, quarterStart, 1));
    to = new Date(Date.UTC(year, quarterStart + 3, 0));
  } else if (preset === "this-year") {
    from = new Date(Date.UTC(year, 0, 1));
    to = new Date(Date.UTC(year, 11, 31));
  } else {
    from = new Date(Date.UTC(year - 1, 0, 1));
    to = new Date(Date.UTC(year - 1, 11, 31));
  }
  const form = elements["report-filter-form"];
  form.elements.from.value = isoDate(from);
  form.elements.to.value = isoDate(to);
  form.elements.asOf.value = isoDate(to);
}

function reportViewConfiguration() {
  const form = elements["report-filter-form"];
  return {
    reportName: form.elements.reportName.value,
    preset: form.elements.preset.value,
    from: form.elements.from.value,
    to: form.elements.to.value,
    asOf: form.elements.asOf.value,
    basis: form.elements.basis.value,
    currency: form.elements.currency.value,
    comparisonEnabled: elements["report-compare-enabled"].checked,
    comparisonMode: elements["report-comparison-mode"].value,
    hideZero: elements["report-hide-zero"].checked,
    collapsedGroups: [...(currentReportState?.collapsedGroups ?? [])],
    columns: currentReportState?.columns ?? []
  };
}

async function loadReportViews(reportName) {
  const response = await api(
    `/v1/report-views?reportName=${encodeURIComponent(reportName)}`,
    {},
    true
  );
  if (!response.ok) return;
  savedReportViews = (await response.json()).views ?? [];
  const current = elements["report-view-select"].value;
  elements["report-view-select"].replaceChildren(
    option("", "Current filters"),
    ...savedReportViews.map((view) =>
      option(view.id, `${view.name}${view.shared ? " · shared" : ""}`)
    )
  );
  elements["report-view-select"].value = savedReportViews.some((view) => view.id === current)
    ? current
    : "";
  elements["delete-report-view"].disabled = !elements["report-view-select"].value;
}

async function applySelectedReportView() {
  const id = elements["report-view-select"].value;
  const view = savedReportViews.find((candidate) => candidate.id === id);
  elements["delete-report-view"].disabled = !view;
  if (!view) return;
  const config = view.configuration ?? {};
  const form = elements["report-filter-form"];
  for (const field of ["from", "to", "asOf", "basis", "currency", "preset"]) {
    if (config[field] !== undefined && form.elements[field])
      form.elements[field].value = config[field];
  }
  elements["report-compare-enabled"].checked = config.comparisonEnabled === true;
  if (config.comparisonMode) elements["report-comparison-mode"].value = config.comparisonMode;
  elements["report-hide-zero"].checked = config.hideZero !== false;
  elements["report-view-name"].value = view.name;
  elements["report-view-shared"].checked = view.shared === true;
  elements["report-view-default"].checked = view.isDefault === true;
  updateReportHeaderLine();
  await runSelectedReport();
}

async function saveCurrentReportView() {
  const name = elements["report-view-name"].value.trim();
  if (!name) {
    elements["report-view-status"].textContent = "Enter a name for this saved view.";
    elements["report-view-name"].focus();
    return;
  }
  const selectedId = elements["report-view-select"].value;
  const request = jsonRequest(
    {
      reportName: elements["report-filter-form"].elements.reportName.value,
      name,
      configuration: reportViewConfiguration(),
      shared: elements["report-view-shared"].checked,
      isDefault: elements["report-view-default"].checked
    },
    selectedId ? "PATCH" : "POST"
  );
  const response = await api(
    selectedId ? `/v1/report-views/${encodeURIComponent(selectedId)}` : "/v1/report-views",
    request
  );
  if (!response.ok) return showError(response);
  const view = (await response.json()).view;
  elements["report-view-status"].textContent = `Saved view “${view.name}”.`;
  await loadReportViews(view.reportName);
  elements["report-view-select"].value = view.id;
  elements["delete-report-view"].disabled = false;
}

async function deleteSelectedReportView() {
  const id = elements["report-view-select"].value;
  if (!id) return;
  const view = savedReportViews.find((candidate) => candidate.id === id);
  if (!view || !window.confirm(`Delete saved view “${view.name}”?`)) return;
  const response = await api(`/v1/report-views/${encodeURIComponent(id)}`, { method: "DELETE" });
  if (!response.ok) return showError(response);
  elements["report-view-status"].textContent = `Deleted view “${view.name}”.`;
  elements["report-view-name"].value = "";
  await loadReportViews(elements["report-filter-form"].elements.reportName.value);
}

function reportMoneyText(value, currency) {
  const numericValue = (() => {
    try {
      return BigInt(String(value ?? "0"));
    } catch {
      return null;
    }
  })();
  if (numericValue === null) return String(value ?? "");
  const negative = numericValue < 0n;
  const absolute = negative ? (-numericValue).toString() : numericValue.toString();
  const formatted = formatMinor(absolute, currency);
  return negative ? `(${formatted})` : formatted;
}

function reportMoneyCell(value, currency) {
  const wrapper = document.createElement("span");
  wrapper.className = "report-money";
  const formatted = reportMoneyText(value, currency);
  const numericValue = (() => {
    try {
      return BigInt(String(value ?? "0"));
    } catch {
      return null;
    }
  })();
  const negative = numericValue !== null && numericValue < 0n;
  if (negative) {
    const visible = document.createElement("span");
    visible.setAttribute("aria-hidden", "true");
    visible.textContent = formatted;
    const accessible = document.createElement("span");
    accessible.className = "sr-only";
    accessible.textContent = `negative ${formatMinor((-numericValue).toString(), currency)}`;
    wrapper.append(visible, accessible);
  } else {
    wrapper.textContent = formatted;
  }
  return wrapper;
}

function reportValueIsZero(value) {
  try {
    return BigInt(String(value ?? "0")) === 0n;
  } catch {
    return false;
  }
}

async function openReportDrilldown(item, reportName, label) {
  const url =
    item.drillDownUrl ??
    item.drilldownUrl ??
    (reportName === "journals" && item.id
      ? `/v1/accountant/journals/${encodeURIComponent(item.id)}/trace`
      : null);
  if (!url) return;
  const tableWrap = elements["report-table"].closest(".table-wrap");
  reportDrilldownState = {
    scrollTop: tableWrap?.scrollTop ?? 0,
    scrollLeft: tableWrap?.scrollLeft ?? 0,
    focusId: document.activeElement?.getAttribute("data-report-row-id") ?? null
  };
  elements["report-drilldown-panel"].hidden = false;
  elements["report-drilldown-breadcrumb"].textContent =
    `${formatRole(reportName)} › ${label || "selected amount"}`;
  elements["report-drilldown-content"].replaceChildren(
    Object.assign(document.createElement("p"), { textContent: "Loading transaction details…" })
  );
  const response = await api(url.replace(/^\/api/, ""), {}, true);
  if (!response.ok) {
    elements["report-drilldown-content"].textContent =
      "The transaction detail could not be loaded. The report remains unchanged.";
    return;
  }
  const payload = await response.json();
  const pre = document.createElement("pre");
  pre.className = "report-drilldown-json";
  pre.textContent = JSON.stringify(payload, null, 2);
  elements["report-drilldown-content"].replaceChildren(pre);
  elements["close-report-drilldown"].focus();
}

function closeReportDrilldown() {
  elements["report-drilldown-panel"].hidden = true;
  const tableWrap = elements["report-table"].closest(".table-wrap");
  if (tableWrap && reportDrilldownState) {
    tableWrap.scrollTop = reportDrilldownState.scrollTop;
    tableWrap.scrollLeft = reportDrilldownState.scrollLeft;
  }
  reportDrilldownState = null;
}

function minorIsNonZero(value) {
  try {
    return BigInt(String(value ?? "0")) !== 0n;
  } catch {
    return false;
  }
}

async function loadReports() {
  if (reportsLoading) return;
  reportsLoading = true;
  try {
    const form = elements["report-filter-form"];
    const today = new Date().toISOString().slice(0, 10);
    if (!form.elements.asOf.value) form.elements.asOf.value = today;
    if (!form.elements.to.value) form.elements.to.value = today;
    if (!form.elements.from.value) form.elements.from.value = `${today.slice(0, 8)}01`;
    refreshReportCurrencyOptions();
    updateReportHeaderLine();
    elements["report-status"].textContent = "Loading dashboard...";
    const response = await api(
      `/v1/dashboard?asOf=${encodeURIComponent(form.elements.asOf.value)}`
    );
    if (!response.ok) {
      elements["report-status"].textContent = "";
      return showError(response);
    }
    const dashboard = (await response.json()).dashboard;
    if (currentReportState) currentReportState.dashboard = dashboard;
    else currentReportState = { dashboard };
    renderDashboard(dashboard);
    await runSelectedReport();
  } finally {
    reportsLoading = false;
  }
}

function renderDashboard(dashboard) {
  if (!dashboard) return;
  refreshReportCurrencyOptions();
  const metrics = [
    ["Cash", dashboard.cashMinor, dashboard.links.cash],
    ["Accounts receivable", dashboard.unpaidInvoicesMinor, dashboard.links.receivables],
    ["Overdue invoices", dashboard.overdueInvoicesMinor, dashboard.links.receivables],
    ["Upcoming bills", dashboard.upcomingBillsMinor, dashboard.links.payables],
    ["Sales this month", dashboard.salesThisMonthMinor, "/v1/reports/sales"],
    ["Expenses this month", dashboard.expensesThisMonthMinor, dashboard.links.profit],
    ["Estimated profit", dashboard.estimatedProfitMinor, dashboard.links.profit],
    ["Estimated tax position", dashboard.estimatedTaxPositionMinor, dashboard.links.tax]
  ];
  elements["dashboard-summary"].replaceChildren(
    ...metrics.map(([label, value, link]) => {
      const group = document.createElement("div");
      const term = document.createElement("dt");
      const detail = document.createElement("dd");
      const anchor = document.createElement("a");
      term.textContent = label;
      anchor.href = `/api${link}`;
      const money = dashboardMoney(value, dashboard.currency, label);
      anchor.textContent = money.text;
      anchor.setAttribute("aria-label", money.aria);
      detail.append(anchor);
      group.append(term, detail);
      return group;
    })
  );
}

async function runSelectedReport(event) {
  event?.preventDefault();
  const form = elements["report-filter-form"];
  const data = new FormData(form);
  const reportName = data.get("reportName");
  refreshReportCurrencyOptions();
  updateReportHeaderLine();
  const query = reportQuery(reportName, data);
  elements["report-status"].textContent = "Loading report...";
  elements["export-report"].disabled = !exportableReports.has(reportName);
  const response = await api(`${reportEndpoints[reportName].path}?${query}`);
  if (!response.ok) {
    elements["report-status"].textContent = "";
    return showError(response);
  }
  const payload = await response.json();
  const report = payload.report ?? payload.trialBalance ?? payload.generalLedger;
  currentReportState = {
    ...(currentReportState ?? {}),
    reportName,
    report,
    query,
    collapsedGroups: currentReportState?.collapsedGroups ?? new Set(),
    columns: currentReportState?.columns ?? []
  };
  renderReport(reportName, report);
  await loadReportViews(reportName);
  if (!elements["report-compare-enabled"].checked) {
    clearReportComparison();
    return;
  }
  const comparison = reportComparisonPeriod(reportName, data);
  if (!comparison) {
    renderReportComparisonUnavailable("Choose a valid report period before comparing.");
    return;
  }
  elements["report-comparison"].hidden = false;
  elements["report-comparison"].textContent = `Loading comparison for ${comparison.label}…`;
  const comparisonResponse = await api(`${reportEndpoints[reportName].path}?${comparison.query}`);
  if (!comparisonResponse.ok) {
    renderReportComparisonUnavailable(
      "The previous period could not be loaded. The current report remains available."
    );
    return;
  }
  const comparisonPayload = await comparisonResponse.json();
  const previousReport =
    comparisonPayload.report ?? comparisonPayload.trialBalance ?? comparisonPayload.generalLedger;
  renderReportComparison(reportName, report, previousReport, comparison.label);
}

function reportQuery(reportName, data) {
  const mode = reportEndpoints[reportName].mode;
  const query = new URLSearchParams();
  if (mode === "range" || mode === "rangeAsOf") {
    query.set("from", data.get("from"));
    query.set("to", data.get("to"));
  }
  if (mode === "asOf" || mode === "rangeAsOf") query.set("asOf", data.get("asOf"));
  if (reportName === "profit-and-loss") query.set("basis", data.get("basis"));
  return query;
}

function shiftReportDate(value, days) {
  const date = new Date(`${String(value)}T00:00:00Z`);
  if (!Number.isFinite(date.getTime())) return null;
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}

function reportComparisonPeriod(reportName, data) {
  const mode = reportEndpoints[reportName].mode;
  const query = new URLSearchParams();
  if (mode === "asOf") {
    const previousAsOf = shiftReportDate(data.get("asOf"), -1);
    if (!previousAsOf) return null;
    query.set("asOf", previousAsOf);
    return { query, label: `as of ${previousAsOf}` };
  }
  const from = String(data.get("from") ?? "");
  const to = String(data.get("to") ?? "");
  const fromDate = new Date(`${from}T00:00:00Z`);
  const toDate = new Date(`${to}T00:00:00Z`);
  if (!Number.isFinite(fromDate.getTime()) || !Number.isFinite(toDate.getTime())) return null;
  const duration = Math.floor((toDate.getTime() - fromDate.getTime()) / 86_400_000) + 1;
  if (duration < 1) return null;
  const previousTo = shiftReportDate(from, -1);
  const previousFrom = previousTo && shiftReportDate(previousTo, -(duration - 1));
  if (!previousFrom || !previousTo) return null;
  query.set("from", previousFrom);
  query.set("to", previousTo);
  if (mode === "rangeAsOf") {
    const previousAsOf = shiftReportDate(data.get("asOf"), -duration);
    if (!previousAsOf) return null;
    query.set("asOf", previousAsOf);
  }
  if (reportName === "profit-and-loss") query.set("basis", data.get("basis"));
  return { query, label: `${previousFrom} to ${previousTo}` };
}

function clearReportComparison() {
  const output = elements["report-comparison"];
  output.hidden = true;
  output.replaceChildren();
}

function renderReportComparisonUnavailable(message) {
  const output = elements["report-comparison"];
  output.hidden = false;
  output.textContent = message;
}

const reportComparisonMetrics = {
  "profit-and-loss": [
    ["Revenue", "totalRevenueMinor"],
    ["Expenses", "totalExpenseMinor"],
    ["Net income", "netIncomeMinor"]
  ],
  "balance-sheet": [
    ["Assets", "totalAssetsMinor"],
    ["Liabilities", "totalLiabilitiesMinor"],
    ["Equity", "totalEquityMinor"]
  ],
  "cash-flow": [
    ["Operating cash", "operatingMinor"],
    ["Investing cash", "investingMinor"],
    ["Net cash change", "netCashChangeMinor"]
  ],
  receivables: [["Receivables subledger", "subledgerBalanceMinor"]],
  payables: [["Payables subledger", "subledgerBalanceMinor"]],
  tax: [
    ["Collected", "collectedMinor"],
    ["Recoverable", "recoverableMinor"],
    ["Net tax position", "netTaxPositionMinor"]
  ],
  banking: [
    ["Cash balance", "paymentClearingBalanceMinor"],
    ["Unmatched items", "unmatchedCount"]
  ],
  sales: [
    ["Net sales", "netSalesMinor"],
    ["Gross margin", "grossMarginMinor"]
  ],
  expenses: [
    ["Expenses", "totalExpenseMinor"],
    ["Processing fees", "paymentProcessingFeesMinor"]
  ]
};

function renderReportComparison(reportName, current, previous, label) {
  const output = elements["report-comparison"];
  output.hidden = false;
  const heading = document.createElement("strong");
  heading.textContent = `Compared with ${label}`;
  const detail = document.createElement("span");
  const metrics = reportComparisonMetrics[reportName] ?? [];
  const lines = metrics
    .filter(([, key]) => current?.[key] !== undefined || previous?.[key] !== undefined)
    .map(([metric, key]) => {
      const currentValue = current?.[key] ?? "0";
      const previousValue = previous?.[key] ?? "0";
      const isCount = !key.endsWith("Minor");
      let delta;
      try {
        delta = BigInt(String(currentValue)) - BigInt(String(previousValue));
      } catch {
        delta = null;
      }
      const currentLabel = isCount
        ? String(currentValue)
        : reportMoneyText(currentValue, reportBaseCurrency());
      const deltaLabel =
        delta === null
          ? ""
          : isCount
            ? String(delta)
            : reportMoneyText(delta, reportBaseCurrency());
      return `${metric}: ${currentLabel} (change ${deltaLabel})`;
    });
  detail.textContent = lines.length
    ? lines.join(" · ")
    : "The selected report has no comparable summary metrics; compare its detail rows below.";
  output.replaceChildren(heading, detail);
}

function renderTaxJurisdictions(reportName, report) {
  const section = elements["report-tax-jurisdictions"];
  if (!section) return;
  const groups =
    reportName === "tax" && Array.isArray(report?.jurisdictions) ? report.jurisdictions : [];
  section.hidden = groups.length === 0;
  if (groups.length === 0) return;
  elements["report-tax-jurisdictions-head"].replaceChildren(
    headerRow([
      "Authority",
      "Payable account",
      "Collected",
      "Recoverable",
      "Net",
      "Account balance",
      "Agrees"
    ])
  );
  // A return is prepared from these figures, so they are shown as money rather
  // than as the minor units the rest of the generic report table displays.
  const money = (value) => (value === null || value === undefined ? "—" : formatMinor(value));
  elements["report-tax-jurisdictions-body"].replaceChildren(
    ...groups.map((group) =>
      row([
        group.jurisdiction,
        group.payableAccountCode
          ? `${group.payableAccountCode} ${group.payableAccountName ?? ""}`.trim()
          : "No payable account",
        money(group.collectedMinor),
        money(group.recoverableMinor),
        money(group.netTaxPositionMinor),
        money(group.accountBalanceMinor),
        group.isReconciled === null ? "—" : group.isReconciled ? "Yes" : "No"
      ])
    )
  );
}

function renderReport(reportName, report) {
  renderTaxJurisdictions(reportName, report);
  const allRows = reportRows(reportName, report);
  const hideZero = elements["report-hide-zero"]?.checked !== false;
  const rows = hideZero
    ? allRows.filter((item) => {
        const moneyFields = Object.entries(item).filter(([key]) => key.endsWith("Minor"));
        return !moneyFields.length || moneyFields.some(([, value]) => !reportValueIsZero(value));
      })
    : allRows;
  const hiddenColumns = new Set([
    "id",
    "accountId",
    "organizationId",
    "journalId",
    "drilldownUrl",
    "drillDownUrl"
  ]);
  const columns = rows.length
    ? Object.keys(rows[0])
        .filter((column) => !hiddenColumns.has(column))
        .slice(0, 10)
    : [];
  const hasDetails = rows.some(
    (item) =>
      (typeof (item.drillDownUrl ?? item.drilldownUrl) === "string" &&
        (item.drillDownUrl ?? item.drilldownUrl)) ||
      (reportName === "journals" && typeof item.id === "string" && item.id)
  );
  const displayColumns = hasDetails ? [...columns, "drillDownUrl"] : columns;
  elements["report-head"].replaceChildren(
    headerRow(displayColumns.map((column) => reportColumnLabel(column)))
  );
  const collapsed = currentReportState?.collapsedGroups ?? new Set();
  const renderedRows = [];
  for (const item of rows) {
    const groupKey = String(item.section ?? item.type ?? "details");
    if (collapsed.has(groupKey)) continue;
    const detailRow = row(
      displayColumns.map((column, columnIndex) => {
        if (column === "drillDownUrl") {
          const drilldownUrl =
            item.drillDownUrl ??
            item.drilldownUrl ??
            (reportName === "journals" && item.id
              ? `/v1/accountant/journals/${encodeURIComponent(item.id)}/trace`
              : null);
          if (!drilldownUrl) return "";
          const link = document.createElement("a");
          link.className = "report-detail-link";
          link.href = drilldownUrl.startsWith("/api/") ? drilldownUrl : `/api${drilldownUrl}`;
          link.textContent = "View details";
          link.setAttribute("data-report-row-id", item.id ?? item.accountId ?? "");
          link.addEventListener("click", (event) => {
            event.preventDefault();
            void openReportDrilldown(
              item,
              reportName,
              item.accountName ?? item.description ?? item.id
            );
          });
          return link;
        }
        const rowCurrency =
          item.currency ?? report.currency ?? multiCurrencyState?.baseCurrency ?? "CAD";
        if (column.endsWith("Minor")) {
          const money = reportMoneyCell(item[column], rowCurrency);
          money.parentElement?.classList.add("report-numeric-cell");
          return money;
        }
        if (columnIndex === 0 && (item.section || item.type)) {
          const groupButton = document.createElement("button");
          groupButton.type = "button";
          groupButton.className = "report-group-toggle";
          groupButton.textContent = reportCell(item[column]);
          groupButton.setAttribute("aria-expanded", String(!collapsed.has(groupKey)));
          groupButton.title = `Collapse ${groupKey} group`;
          groupButton.addEventListener("click", () => {
            if (collapsed.has(groupKey)) collapsed.delete(groupKey);
            else collapsed.add(groupKey);
            currentReportState.collapsedGroups = collapsed;
            renderReport(reportName, report);
          });
          return groupButton;
        }
        return reportCell(item[column]);
      })
    );
    detailRow.dataset.reportGroup = groupKey;
    detailRow.querySelectorAll(".report-money").forEach((money) => {
      money.parentElement?.classList.add("report-numeric-cell");
    });
    renderedRows.push(detailRow);
  }
  elements["report-body"].replaceChildren(...renderedRows);
  elements["report-status"].textContent =
    `${formatRole(reportName)}: ${rows.length} detail row${rows.length === 1 ? "" : "s"}${hideZero && rows.length !== allRows.length ? ` (${allRows.length - rows.length} zero rows hidden)` : ""}.`;
}

function reportColumnLabel(column) {
  const labels = {
    accountCode: "Code",
    accountName: "Account",
    amountMinor: "Amount",
    balanceMinor: "Balance",
    debitMinor: "Debit",
    creditMinor: "Credit",
    drillDownUrl: "Details",
    effectiveDate: "Date",
    invoiceNumber: "Invoice",
    vendorInvoiceNumber: "Vendor invoice"
  };
  return labels[column] ?? formatRole(column.replace(/Minor$/, ""));
}

function reportRows(reportName, report) {
  if (Array.isArray(report.rows)) return report.rows;
  if (Array.isArray(report.lines)) return report.lines;
  if (Array.isArray(report.journals)) return report.journals;
  if (Array.isArray(report.invoices)) return report.invoices;
  if (Array.isArray(report.bills)) return report.bills;
  if (Array.isArray(report.detail)) return report.detail;
  if (reportName === "cash-flow" && report.categories)
    return Object.entries(report.categories).map(([category, amountMinor]) => ({
      category,
      amountMinor
    }));
  return Object.entries(report)
    .filter(([, value]) => typeof value !== "object")
    .map(([field, value]) => ({ field, value }));
}

function reportCell(value) {
  if (value === null || value === undefined) return "";
  if (typeof value === "object") return JSON.stringify(value);
  return String(value);
}

// A sales tax return is prepared per authority, so this exports the grouped
// figures rather than the line detail the generic export produces.
function exportTaxByAuthority() {
  const data = new FormData(elements["report-filter-form"]);
  const query = new URLSearchParams({
    from: data.get("from") ?? "",
    to: data.get("to") ?? "",
    asOf: data.get("asOf") ?? "",
    basis: data.get("basis") ?? "ACCRUAL"
  });
  window.location.assign(`/api/v1/reports/exports/tax-by-authority.csv?${query}`);
}

function exportSelectedReport() {
  const data = new FormData(elements["report-filter-form"]);
  const reportName = data.get("reportName");
  if (!exportableReports.has(reportName)) return;
  const query = new URLSearchParams({
    from: data.get("from"),
    to: data.get("to"),
    asOf: data.get("asOf"),
    basis: data.get("basis")
  });
  window.location.assign(`/api/v1/reports/exports/${reportName}.csv?${query}`);
}

async function previewFxRevaluation(event) {
  event.preventDefault();
  const data = new FormData(event.currentTarget);
  const valuationDate = data.get("valuationDate");
  const rateSnapshotId = data.get("rateSnapshotId");
  if (!valuationDate) return showNotice("Choose a valuation date.", true);
  if (!rateSnapshotId)
    return showNotice("Choose a closing rate recorded for the valuation date.", true);
  const response = await api(
    "/v1/accounting/fx-revaluation/preview",
    jsonRequest({ valuationDate, rateSnapshotIds: [rateSnapshotId], post: false }, "POST")
  );
  if (!response.ok) return showError(response);
  fxRevaluationPreview = (await response.json()).preview;
  elements["fx-revaluation-result"].textContent = fxRevaluationPreview.positions.length
    ? `${fxRevaluationPreview.positions.length} position(s): gains ${formatMinor(fxRevaluationPreview.totalUnrealizedGainMinor, fxRevaluationPreview.baseCurrency)}, losses ${formatMinor(fxRevaluationPreview.totalUnrealizedLossMinor, fxRevaluationPreview.baseCurrency)}. ${fxRevaluationPreview.readyToPost ? "Ready to post." : `Missing: ${[...fxRevaluationPreview.missingAccounts, ...fxRevaluationPreview.missingRates].join(", ")}.`}`
    : "No active foreign monetary positions require revaluation.";
  elements["fx-revaluation-rows"].replaceChildren(
    ...fxRevaluationPreview.positions.map((position) =>
      row([
        position.currency,
        formatMinor(position.carryingBaseMinor, fxRevaluationPreview.baseCurrency),
        formatMinor(position.deltaBaseMinor, fxRevaluationPreview.baseCurrency),
        position.gainLoss
      ])
    )
  );
  elements["post-fx-revaluation"].disabled = !fxRevaluationPreview.readyToPost;
}

async function postFxRevaluation() {
  if (!fxRevaluationPreview) return;
  const response = await api(
    "/v1/accounting/fx-revaluation/post",
    jsonRequest(
      {
        valuationDate: fxRevaluationPreview.valuationDate,
        rateSnapshotIds: [
          ...new Set(fxRevaluationPreview.positions.map((position) => position.rateSnapshotId))
        ],
        post: true
      },
      "POST"
    )
  );
  if (!response.ok) return showError(response);
  elements["post-fx-revaluation"].disabled = true;
  await Promise.all([loadAccountant(), loadReports()]);
  showNotice("FX revaluation posted with an automatic next-period reversal.");
}

function renderFxOverview(fx) {
  const baseCurrency = multiCurrencyState?.baseCurrency ?? "CAD";
  elements["fx-position-rows"].replaceChildren(
    ...fx.positions
      .filter((position) => position.active)
      .map((position) =>
        row([
          formatRole(position.kind),
          position.currency,
          formatMinor(position.outstandingTransactionMinor, position.currency),
          formatMinor(position.carryingBaseMinor, baseCurrency),
          position.asOfDate
        ])
      )
  );
}

async function loadAccountant() {
  const asOf =
    elements["report-filter-form"].elements.asOf.value || new Date().toISOString().slice(0, 10);
  const [draftsResponse, periodsResponse, queueResponse, fxResponse] = await Promise.all([
    api("/v1/accountant/manual-journals"),
    api("/v1/fiscal-periods"),
    api(`/v1/accountant/review-queue?asOf=${encodeURIComponent(asOf)}`),
    api("/v1/accounting/fx-overview")
  ]);
  if (draftsResponse.status === 403) {
    elements["accountant-workspace"].hidden = true;
    return;
  }
  if (!draftsResponse.ok) return showError(draftsResponse);
  if (!periodsResponse.ok) return showError(periodsResponse);
  if (!queueResponse.ok) return showError(queueResponse);
  const drafts = (await draftsResponse.json()).drafts;
  manualJournalDrafts = drafts;
  const periods = (await periodsResponse.json()).periods;
  const queue = (await queueResponse.json()).queue;
  if (fxResponse.ok) renderFxOverview((await fxResponse.json()).fx);
  if (!accounts.length) await loadAccounts();
  refreshManualJournalAccountOptions();
  if (!elements["manual-journal-form"].elements.effectiveDate.value)
    elements["manual-journal-form"].elements.effectiveDate.value = asOf;
  elements["manual-journal-drafts"].replaceChildren(
    ...drafts.map((draft) => {
      const actions = document.createElement("div");
      actions.className = "table-command-group";
      if (draft.accountingBoundary?.editable) {
        actions.append(commandButton("Edit", () => editManualJournalDraft(draft)));
        actions.append(commandButton("Cancel", () => cancelManualJournalDraft(draft)));
      }
      const post = document.createElement("button");
      post.type = "button";
      post.textContent = "Post to ledger";
      post.title = "Create one authoritative journal from this reviewed workpaper";
      post.disabled = draft.status !== "DRAFT";
      post.addEventListener("click", () => postManualJournalDraft(draft, post));
      actions.append(post);
      return row([
        draft.effectiveDate.slice(0, 10),
        draft.description,
        draft.accountingBoundary?.authoritative
          ? `${formatRole(draft.status)} · Authoritative`
          : `${formatRole(draft.status)} · Non-posting workpaper`,
        actions
      ]);
    })
  );
  elements["accountant-periods"].replaceChildren(
    ...(await Promise.all(
      periods.map(async (period) => {
        const previewResponse = await api(`/v1/fiscal-periods/${period.id}/close-preview`);
        const checklist = previewResponse.ok ? (await previewResponse.json()).checklist : null;
        const action = document.createElement("button");
        action.type = "button";
        action.textContent = period.status === "CLOSED" ? "Reopen" : "Close";
        action.addEventListener("click", () => changePeriodStatus(period, checklist));
        return row([
          `${period.name} (${period.startDate.slice(0, 10)} to ${period.endDate.slice(0, 10)})`,
          formatRole(period.status),
          checklist
            ? checklist.clean
              ? "Clean"
              : `${checklist.warnings.length} warning(s)`
            : "Unavailable",
          action
        ]);
      })
    ))
  );
  elements["accountant-review-items"].replaceChildren(
    ...queue.items.map((item) => {
      const action = document.createElement("button");
      action.type = "button";
      action.textContent = "Dismiss";
      action.addEventListener("click", () => dismissReviewItem(item));
      return row([
        formatRole(item.category),
        item.explanation,
        `${item.targetType} ${item.targetId ?? ""}`,
        action
      ]);
    })
  );
  await loadAuditEvents();
  applySavedTableFilters();
}

async function createManualJournalDraft(event) {
  event.preventDefault();
  const data = new FormData(event.currentTarget);
  const lines = manualJournalLinesFromEditor();
  if (!lines) return;
  const draftId = String(data.get("draftId") ?? "");
  const versionValue = String(data.get("version") ?? "");
  const payload = {
    description: data.get("description"),
    effectiveDate: data.get("effectiveDate"),
    reason: data.get("reason"),
    allowControlAccountPosting: data.get("allowControlAccountPosting") === "on",
    lines,
    ...(draftId ? { version: Number(versionValue) } : {})
  };
  const response = await api(
    draftId ? `/v1/accountant/manual-journals/${draftId}` : "/v1/accountant/manual-journals",
    jsonRequest(payload, draftId ? "PATCH" : "POST")
  );
  if (!response.ok) {
    if (response.status === 409) {
      await loadAccountant();
      const latest = manualJournalDrafts.find((draft) => draft.id === draftId);
      if (latest?.accountingBoundary?.editable) editManualJournalDraft(latest, false);
      return showNotice(
        "This workpaper changed in another session. The latest version has been reloaded; review it before saving.",
        true
      );
    }
    return showError(response);
  }
  resetManualJournalForm();
  await loadAccountant();
  showNotice(
    draftId
      ? "Workpaper updated in place. No ledger entry was created."
      : "Non-posting workpaper created for review."
  );
}

function manualJournalEditorValues() {
  return [...elements["manual-journal-lines"].querySelectorAll(".manual-journal-line")].map(
    (line) => ({
      accountId: line.querySelector('[data-manual-journal-field="accountId"]').value,
      description: line.querySelector('[data-manual-journal-field="description"]').value,
      debitValue: line.querySelector('[data-manual-journal-field="debitMinor"]').value,
      creditValue: line.querySelector('[data-manual-journal-field="creditMinor"]').value
    })
  );
}

function manualJournalAccountOptions(selectedAccountId = "") {
  const available = accounts.filter((account) => !account.isArchived);
  const selected = accounts.find((account) => account.id === selectedAccountId);
  const selectedIsAvailable = available.some((account) => account.id === selectedAccountId);
  return [
    option("", "Choose account"),
    ...available.map((account) => option(account.id, `${account.code} ${account.name}`)),
    ...(selectedAccountId && !selectedIsAvailable
      ? [
          option(
            selectedAccountId,
            selected
              ? `${selected.code} ${selected.name} (archived - choose another)`
              : "Unavailable account (choose another)"
          )
        ]
      : [])
  ];
}

function renderManualJournalLine(line, index) {
  const wrapper = document.createElement("div");
  wrapper.className = "manual-journal-line";
  wrapper.setAttribute("role", "listitem");
  wrapper.setAttribute("aria-label", `Journal line ${index + 1}`);

  const lineNumber = document.createElement("strong");
  lineNumber.className = "manual-journal-line-number";
  lineNumber.textContent = String(index + 1);
  lineNumber.setAttribute("aria-hidden", "true");

  const accountLabel = document.createElement("label");
  accountLabel.className = "manual-journal-line-account";
  const accountLabelText = document.createElement("span");
  accountLabelText.textContent = "Account";
  const account = document.createElement("select");
  account.required = true;
  account.dataset.manualJournalField = "accountId";
  account.setAttribute("aria-label", `Account for journal line ${index + 1}`);
  account.replaceChildren(...manualJournalAccountOptions(line.accountId));
  account.value = line.accountId || "";
  accountLabel.append(accountLabelText, account);

  const descriptionLabel = document.createElement("label");
  descriptionLabel.className = "manual-journal-line-description";
  const descriptionLabelText = document.createElement("span");
  descriptionLabelText.textContent = "Line description";
  const description = document.createElement("input");
  description.maxLength = 500;
  description.value = line.description || "";
  description.dataset.manualJournalField = "description";
  description.setAttribute("aria-label", `Description for journal line ${index + 1}`);
  descriptionLabel.append(descriptionLabelText, description);

  const debitLabel = document.createElement("label");
  debitLabel.className = "manual-journal-line-debit";
  const debitLabelText = document.createElement("span");
  debitLabelText.textContent = "Debit";
  const debit = document.createElement("input");
  debit.inputMode = "decimal";
  debit.placeholder = "0.00";
  debit.value = line.debitValue || "";
  debit.dataset.manualJournalField = "debitMinor";
  debit.setAttribute("aria-label", `Debit for journal line ${index + 1}`);
  debitLabel.append(debitLabelText, debit);

  const creditLabel = document.createElement("label");
  creditLabel.className = "manual-journal-line-credit";
  const creditLabelText = document.createElement("span");
  creditLabelText.textContent = "Credit";
  const credit = document.createElement("input");
  credit.inputMode = "decimal";
  credit.placeholder = "0.00";
  credit.value = line.creditValue || "";
  credit.dataset.manualJournalField = "creditMinor";
  credit.setAttribute("aria-label", `Credit for journal line ${index + 1}`);
  creditLabel.append(creditLabelText, credit);

  const remove = document.createElement("button");
  remove.type = "button";
  remove.className = "text-command manual-journal-line-remove";
  remove.dataset.manualJournalAction = "remove";
  remove.textContent = "Remove";
  remove.setAttribute("aria-label", `Remove journal line ${index + 1}`);

  wrapper.append(lineNumber, accountLabel, descriptionLabel, debitLabel, creditLabel, remove);
  return wrapper;
}

function renderManualJournalLines(
  lines = [
    { accountId: "", description: "", debitValue: "", creditValue: "" },
    { accountId: "", description: "", debitValue: "", creditValue: "" }
  ]
) {
  const normalized =
    lines.length >= 2 ? lines : [...lines, ...Array.from({ length: 2 - lines.length }, () => ({}))];
  elements["manual-journal-lines"].replaceChildren(
    ...normalized.map((line, index) => renderManualJournalLine(line, index))
  );
  const canRemove = normalized.length > 2;
  for (const button of elements["manual-journal-lines"].querySelectorAll(
    '[data-manual-journal-action="remove"]'
  ))
    button.disabled = !canRemove;
  elements["add-manual-journal-line"].disabled = normalized.length >= MANUAL_JOURNAL_MAX_LINES;
  updateManualJournalTotals();
}

function appendManualJournalLine(line = {}) {
  const lines = manualJournalEditorValues();
  if (lines.length >= MANUAL_JOURNAL_MAX_LINES)
    return showNotice(
      `A manual journal workpaper can contain at most ${MANUAL_JOURNAL_MAX_LINES} lines.`,
      true
    );
  renderManualJournalLines([...lines, line]);
  const added = elements["manual-journal-lines"].lastElementChild;
  added?.querySelector("select")?.focus();
}

function removeManualJournalLine(event) {
  const button = event.target.closest('[data-manual-journal-action="remove"]');
  if (!button) return;
  const lines = manualJournalEditorValues();
  if (lines.length <= 2)
    return showNotice("A manual journal workpaper requires at least two lines.", true);
  const index = [...elements["manual-journal-lines"].children].indexOf(
    button.closest(".manual-journal-line")
  );
  if (index < 0) return;
  lines.splice(index, 1);
  renderManualJournalLines(lines);
}

function refreshManualJournalAccountOptions() {
  for (const select of elements["manual-journal-lines"].querySelectorAll(
    '[data-manual-journal-field="accountId"]'
  )) {
    const selected = select.value;
    select.replaceChildren(...manualJournalAccountOptions(selected));
    select.value = selected;
  }
}

function updateManualJournalTotals() {
  let debits = 0n;
  let credits = 0n;
  let valid = true;
  let lineSidesValid = true;
  for (const line of manualJournalEditorValues()) {
    try {
      const debit = BigInt(parseMoneyInput(line.debitValue || "0"));
      const credit = BigInt(parseMoneyInput(line.creditValue || "0"));
      debits += debit;
      credits += credit;
      if ((debit === 0n && credit === 0n) || (debit > 0n && credit > 0n)) lineSidesValid = false;
    } catch {
      valid = false;
    }
  }
  const currency = multiCurrencyState?.baseCurrency ?? "CAD";
  elements["manual-journal-debit-total"].textContent = valid
    ? formatMinor(debits.toString(), currency)
    : "Check amounts";
  elements["manual-journal-credit-total"].textContent = valid
    ? formatMinor(credits.toString(), currency)
    : "Check amounts";
  elements["manual-journal-difference"].textContent = valid
    ? formatMinor((debits >= credits ? debits - credits : credits - debits).toString(), currency)
    : "Check amounts";
  const fieldset = elements["manual-journal-lines"].closest("fieldset");
  const balanced = valid && lineSidesValid && debits > 0n && debits === credits;
  fieldset?.classList.toggle("is-balanced", balanced);
  fieldset?.classList.toggle("is-unbalanced", !balanced);
  const status = elements["manual-journal-balance-status"];
  if (!valid) status.textContent = "Enter amounts with no more than two decimal places.";
  else if (!lineSidesValid)
    status.textContent = "Each line needs either one debit or one credit amount.";
  else if (debits > credits)
    status.textContent = `${formatMinor(debits - credits, currency)} more credits are needed.`;
  else if (credits > debits)
    status.textContent = `${formatMinor(credits - debits, currency)} more debits are needed.`;
  else if (balanced)
    status.textContent = `Balanced at ${formatMinor(debits, currency)}. Still non-posting.`;
  else status.textContent = "Add at least two balanced lines.";
}

function manualJournalLinesFromEditor() {
  const values = manualJournalEditorValues();
  if (values.length < 2) {
    showNotice("A manual journal workpaper requires at least two lines.", true);
    return null;
  }
  if (values.length > MANUAL_JOURNAL_MAX_LINES) {
    showNotice(
      `A manual journal workpaper can contain at most ${MANUAL_JOURNAL_MAX_LINES} lines.`,
      true
    );
    return null;
  }
  const lines = [];
  let totalDebits = 0n;
  let totalCredits = 0n;
  for (const [index, line] of values.entries()) {
    if (!line.accountId) {
      showNotice(`Choose an account for journal line ${index + 1}.`, true);
      elements["manual-journal-lines"].children[index]
        ?.querySelector('[data-manual-journal-field="accountId"]')
        ?.focus();
      return null;
    }
    let debitMinor;
    let creditMinor;
    try {
      debitMinor = parseMoneyInput(line.debitValue || "0");
      creditMinor = parseMoneyInput(line.creditValue || "0");
    } catch (error) {
      showNotice(
        `Journal line ${index + 1}: ${error instanceof Error ? error.message : "Enter a valid amount."}`,
        true
      );
      elements["manual-journal-lines"].children[index]
        ?.querySelector('[data-manual-journal-field="debitMinor"]')
        ?.focus();
      return null;
    }
    const debit = BigInt(debitMinor);
    const credit = BigInt(creditMinor);
    if ((debit === 0n && credit === 0n) || (debit > 0n && credit > 0n)) {
      showNotice(`Journal line ${index + 1} must contain either one debit or one credit.`, true);
      return null;
    }
    totalDebits += debit;
    totalCredits += credit;
    lines.push({
      accountId: line.accountId,
      ...(line.description.trim() ? { description: line.description.trim() } : {}),
      debitMinor,
      creditMinor
    });
  }
  if (totalDebits !== totalCredits) {
    const currency = multiCurrencyState?.baseCurrency ?? "CAD";
    showNotice(
      `Debits (${formatMinor(totalDebits, currency)}) must equal credits (${formatMinor(totalCredits, currency)}) before saving.`,
      true
    );
    return null;
  }
  return lines;
}

function editManualJournalDraft(draft, scroll = true) {
  const form = elements["manual-journal-form"];
  activeManualJournalDraftId = draft.id;
  form.elements.draftId.value = draft.id;
  form.elements.version.value = String(draft.version);
  form.elements.description.value = draft.description;
  form.elements.effectiveDate.value = draft.effectiveDate.slice(0, 10);
  form.elements.reason.value = draft.reason;
  form.elements.allowControlAccountPosting.checked = draft.allowControlAccountPosting;
  renderManualJournalLines(
    draft.lines.map((line) => ({
      accountId: line.accountId,
      description: line.description ?? "",
      debitValue: BigInt(line.debitMinor) === 0n ? "" : minorToInput(line.debitMinor),
      creditValue: BigInt(line.creditMinor) === 0n ? "" : minorToInput(line.creditMinor)
    }))
  );
  elements["manual-journal-form-heading"].textContent = "Edit manual journal workpaper";
  elements["save-manual-journal-draft"].textContent = "Save workpaper";
  elements["cancel-manual-journal-edit"].hidden = false;
  if (scroll)
    elements["manual-journal-form-heading"].scrollIntoView({
      behavior: preferredScrollBehavior(),
      block: "start"
    });
}

function resetManualJournalForm() {
  const form = elements["manual-journal-form"];
  form.reset();
  activeManualJournalDraftId = null;
  form.elements.draftId.value = "";
  form.elements.version.value = "";
  form.elements.effectiveDate.value =
    elements["report-filter-form"].elements.asOf.value || new Date().toISOString().slice(0, 10);
  renderManualJournalLines();
  elements["manual-journal-form-heading"].textContent = "Manual journal workpaper";
  elements["save-manual-journal-draft"].textContent = "Create workpaper";
  elements["cancel-manual-journal-edit"].hidden = true;
}

async function cancelManualJournalDraft(draft) {
  if (
    !window.confirm(
      `Cancel the non-posting workpaper “${draft.description}”? Its audit history will be retained.`
    )
  )
    return;
  const response = await api(
    `/v1/accountant/manual-journals/${draft.id}/cancel`,
    jsonRequest({ version: draft.version })
  );
  if (!response.ok) {
    if (response.status === 409) {
      await loadAccountant();
      return showNotice(
        "This workpaper changed in another session. The latest version is shown.",
        true
      );
    }
    return showError(response);
  }
  if (activeManualJournalDraftId === draft.id) resetManualJournalForm();
  await loadAccountant();
  showNotice("Workpaper cancelled without creating a ledger entry.");
}

async function postManualJournalDraft(draft, button) {
  if (
    !window.confirm(
      `Post “${draft.description}” once? This creates an authoritative journal that cannot be edited or cancelled.`
    )
  )
    return;
  button.disabled = true;
  button.textContent = "Posting…";
  const response = await api(`/v1/accountant/manual-journals/${draft.id}/post`, {
    ...jsonRequest({ version: draft.version }),
    headers: {
      "content-type": "application/json",
      "idempotency-key": globalThis.crypto.randomUUID()
    }
  });
  if (!response.ok) {
    button.disabled = false;
    button.textContent = "Post to ledger";
    if (response.status === 409) {
      await loadAccountant();
      return showNotice(
        "This workpaper changed in another session. The latest version is shown; review it before posting.",
        true
      );
    }
    return showError(response);
  }
  if (activeManualJournalDraftId === draft.id) resetManualJournalForm();
  await Promise.all([loadAccountant(), loadReports()]);
  showNotice("Manual journal posted once. The workpaper is now authoritative and read-only.");
}

async function changePeriodStatus(period, checklist) {
  const reason = window.prompt(
    `Reason to ${period.status === "CLOSED" ? "reopen" : "close"} this period:`
  );
  if (!reason?.trim()) return;
  const closing = period.status !== "CLOSED";
  const acknowledgeWarnings =
    closing && checklist && !checklist.clean
      ? window.confirm("This period has review warnings. Close after acknowledging them?")
      : false;
  if (closing && checklist && !checklist.clean && !acknowledgeWarnings) return;
  const response = await api(
    `/v1/fiscal-periods/${period.id}/${closing ? "close" : "reopen"}`,
    jsonRequest({ reason, ...(closing ? { acknowledgeWarnings } : {}) })
  );
  if (!response.ok) return showError(response);
  await loadAccountant();
  showNotice(`Fiscal period ${closing ? "closed" : "reopened"}.`);
}

async function dismissReviewItem(item) {
  const reason = window.prompt("Reason for dismissing this review item:");
  if (!reason?.trim()) return;
  const response = await api(
    "/v1/accountant/review-queue/dismiss",
    jsonRequest({
      fingerprint: item.fingerprint,
      category: item.category,
      reason,
      asOf:
        elements["report-filter-form"].elements.asOf.value || new Date().toISOString().slice(0, 10)
    })
  );
  if (!response.ok) return showError(response);
  await loadAccountant();
  showNotice("Review item dismissed with audit evidence.");
}

async function traceJournal(event) {
  event.preventDefault();
  const journalId = new FormData(event.currentTarget).get("journalId");
  const [traceResponse, guideResponse] = await Promise.all([
    api(`/v1/accountant/journals/${encodeURIComponent(journalId)}/trace`),
    api(`/v1/accountant/journals/${encodeURIComponent(journalId)}/correction-guide`)
  ]);
  if (!traceResponse.ok) return showError(traceResponse);
  if (!guideResponse.ok) return showError(guideResponse);
  const trace = (await traceResponse.json()).trace;
  const guidance = (await guideResponse.json()).guidance;
  elements["journal-trace-result"].textContent =
    `Source: ${trace.source.type} ${trace.source.id}. ${guidance.strategy}`;
}

async function loadAuditEvents(event) {
  event?.preventDefault();
  const action = elements["audit-filter-form"].elements.action.value;
  const query = new URLSearchParams({ page: "1", pageSize: "50" });
  if (action) query.set("action", action);
  const response = await api(`/v1/accountant/audit-events?${query}`);
  if (!response.ok) return;
  const audit = (await response.json()).audit;
  elements["audit-events"].replaceChildren(
    ...audit.events.map((entry) =>
      row([
        entry.createdAt,
        entry.actor?.displayName ?? entry.actor?.email ?? "System",
        entry.action,
        `${entry.targetType} ${entry.targetId ?? ""}`
      ])
    )
  );
}

function exportAudit() {
  const action = elements["audit-filter-form"].elements.action.value;
  const query = new URLSearchParams({ page: "1", pageSize: "100" });
  if (action) query.set("action", action);
  window.location.assign(`/api/v1/accountant/audit-events.csv?${query}`);
}

async function loadPortability() {
  elements["portability-workspace"].hidden = !identity?.activeOrganizationId;
  if (identity?.activeOrganizationId) await loadRecentImportBatches();
}

async function loadRecentImportBatches() {
  if (!identity?.activeOrganizationId || !identity?.activeCompanyId) return;
  const importType = elements["data-import-form"].elements.importType.value;
  elements["import-history-status"].textContent = "Loading recent imports...";
  const response = await api(`/v1/imports?importType=${encodeURIComponent(importType)}&limit=10`);
  if (!response.ok) {
    recentImportBatches = [];
    renderRecentImportBatches();
    elements["import-history-status"].textContent =
      response.status === 403
        ? "Your role cannot review import history for this data type."
        : "Recent import history is temporarily unavailable.";
    return;
  }
  recentImportBatches = (await response.json()).batches ?? [];
  renderRecentImportBatches();
  elements["import-history-status"].textContent = recentImportBatches.length
    ? `${recentImportBatches.length} recent batch${recentImportBatches.length === 1 ? "" : "es"} available.`
    : "No prior imports for this data type.";
}

function renderRecentImportBatches() {
  elements["recent-import-batches"].replaceChildren(
    ...recentImportBatches.map((batch) => {
      const action = document.createElement("button");
      action.type = "button";
      action.className = "secondary-command";
      action.dataset.importBatchId = batch.id;
      action.textContent = currentImportBatch?.id === batch.id ? "Open" : "Resume";
      action.setAttribute(
        "aria-label",
        `Resume ${batch.sourceFilename ?? "import batch"} in the Switching centre`
      );
      return row([
        batch.sourceFilename ?? "Uploaded source",
        formatImportSource(batch.sourceSystem),
        String(batch.rowCount ?? 0),
        formatImportStatus(batch.status),
        formatConnectorTime(batch.updatedAt),
        action
      ]);
    })
  );
}

async function handleRecentImportAction(event) {
  const button = event.target.closest("[data-import-batch-id]");
  if (!button) return;
  button.disabled = true;
  const response = await api(`/v1/imports/${encodeURIComponent(button.dataset.importBatchId)}`);
  button.disabled = false;
  if (!response.ok) return showError(response);
  currentImportBatch = (await response.json()).batch;
  importOutcomePage = 0;
  const form = elements["data-import-form"];
  form.elements.importType.value = currentImportBatch.importType;
  form.elements.sourceSystem.value = currentImportBatch.sourceSystem;
  form.elements.file.value = "";
  renderImportSourceGuide();
  renderImportTemplateGuidance();
  hydrateImportPreviewFromBatch(currentImportBatch);
  renderDataImport();
  renderRecentImportBatches();
  elements["data-import-status"].scrollIntoView({
    behavior: preferredScrollBehavior(),
    block: "center"
  });
  showNotice("Import batch reopened at its saved stage. No records were changed.");
}

async function uploadDataImport(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const data = new FormData(form);
  const file = data.get("file");
  if (!(file instanceof globalThis.File) || !file.size)
    return showNotice("Select a CSV or XLSX file.");
  const mediaType = importMediaType(file);
  if (!mediaType)
    return showNotice(
      "Choose a .csv file or an .xlsx workbook. Excel 97-2003 and macro-enabled workbooks are not accepted."
    );
  let mapping;
  try {
    mapping = JSON.parse(data.get("mapping") || "{}");
    if (!mapping || Array.isArray(mapping) || typeof mapping !== "object")
      throw new Error("Mapping must be an object.");
  } catch {
    return showNotice("Column mapping must be a JSON object.");
  }
  const upload = await api(
    `/v1/imports/upload?importType=${encodeURIComponent(data.get("importType"))}&sourceSystem=${encodeURIComponent(data.get("sourceSystem"))}`,
    {
      method: "POST",
      headers: { "content-type": mediaType, "x-file-name": file.name },
      body: await file.arrayBuffer()
    }
  );
  if (!upload.ok) return showError(upload);
  importOutcomePage = 0;
  currentImportBatch = (await upload.json()).batch;
  const preview = await api(
    `/v1/imports/${currentImportBatch.id}/preview`,
    jsonRequest({ mapping })
  );
  if (!preview.ok) return showError(preview);
  currentImportBatch = (await preview.json()).batch;
  hydrateImportPreviewFromBatch(currentImportBatch);
  renderDataImport();
  await loadRecentImportBatches();
  trackProductEvent("MIGRATION_PREVIEW_COMPLETED");
}

function importMediaType(file) {
  const name = file.name.toLowerCase();
  if (name.endsWith(".csv")) return "text/csv";
  if (name.endsWith(".xlsx"))
    return "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
  return null;
}

async function inspectDataImportFile() {
  const file = elements["data-import-form"].elements.file.files?.[0];
  resetImportItemMatchReview();
  if (!file?.size) return;
  if (!importMediaType(file)) {
    importFilePreview = null;
    elements["import-mapping-workspace"].hidden = true;
    elements["data-import-file-summary"].textContent =
      "Choose a .csv file or an .xlsx workbook; .xls and macro-enabled files cannot be reviewed.";
    return;
  }
  setMigrationStep(1);
  elements["data-import-file-summary"].textContent =
    `Inspecting ${file.name} without uploading it…`;
  try {
    importFilePreview = file.name.toLowerCase().endsWith(".csv")
      ? parseLocalImportCsv(await file.text(), file)
      : workbookSelectionPreview(file);
    seedImportColumnMapping();
    elements["import-mapping-workspace"].hidden = false;
    setImportMappingTab("preview");
  } catch (error) {
    importFilePreview = null;
    elements["import-mapping-workspace"].hidden = true;
    elements["data-import-file-summary"].textContent =
      error instanceof Error ? error.message : "The selected file could not be inspected.";
  }
}

function parseLocalImportCsv(text, file) {
  const records = parseImportCsvRecords(text.replace(/^\uFEFF/, ""));
  if (records.length < 2)
    throw new Error("CSV needs one header row and at least one representative data row.");
  const headers = records[0].map(normalizeImportHeader);
  if (headers.some((header) => !header) || new Set(headers).size !== headers.length)
    throw new Error("CSV headings must be non-empty and unique before they can be mapped.");
  return {
    format: "CSV",
    fileName: file.name,
    byteSize: file.size,
    sheet: "Not applicable",
    headers,
    rows: records.slice(1, 6).map((record) => headers.map((_, index) => record[index] ?? "")),
    warnings: [],
    sourceHint: detectImportSource(headers)
  };
}

function workbookSelectionPreview(file) {
  return {
    format: "XLSX",
    fileName: file.name,
    byteSize: file.size,
    sheet: "Selected safely during upload review",
    headers: [],
    rows: [],
    warnings: [
      "The workbook sheet and values are inspected by PennyWise Accounting after upload; no workbook contents are read in this browser preview.",
      "Only an .xlsx workbook is accepted. Macro, external-link, and unsafe archive content will be rejected before mapping."
    ],
    sourceHint: null
  };
}

function detectImportSource(headers) {
  const sourceHeaders = new Set(headers);
  const signals = [
    {
      source: "QUICKBOOKS_DESKTOP",
      name: "QuickBooks Desktop",
      fields: ["invoice_number", "item", "qty", "rate", "line_amount"]
    },
    {
      source: "QUICKBOOKS_ONLINE",
      name: "QuickBooks Online",
      fields: ["customer", "transaction_date", "amount", "tax_amount", "balance"]
    }
  ]
    .map((candidate) => ({
      ...candidate,
      matched: candidate.fields.filter((field) => sourceHeaders.has(field)).length
    }))
    .filter((candidate) => candidate.matched >= 2)
    .sort((left, right) => right.matched - left.matched);
  if (!signals.length) return null;
  const [best, runnerUp] = signals;
  if (runnerUp && runnerUp.matched === best.matched) return null;
  return {
    source: best.source,
    name: best.name,
    matched: best.matched
  };
}

function parseImportCsvRecords(text) {
  const records = [];
  let record = [];
  let field = "";
  let quoted = false;
  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];
    if (quoted) {
      if (character === '"' && text[index + 1] === '"') {
        field += '"';
        index += 1;
      } else if (character === '"') quoted = false;
      else field += character;
    } else if (character === '"') quoted = true;
    else if (character === ",") {
      record.push(field);
      field = "";
    } else if (character === "\n") {
      record.push(field.replace(/\r$/, ""));
      if (record.some((value) => value.trim())) records.push(record);
      record = [];
      field = "";
    } else if (character !== "\r") field += character;
  }
  if (quoted) throw new Error("CSV has an unfinished quoted value.");
  record.push(field);
  if (record.some((value) => value.trim())) records.push(record);
  return records;
}

function normalizeImportHeader(value) {
  return String(value)
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_|_$/g, "");
}

function seedImportColumnMapping() {
  const fields = importFieldsForType(elements["data-import-form"].elements.importType.value);
  const headers = importFilePreview?.headers ?? [];
  importColumnMapping = Object.fromEntries(
    fields.map((field) => {
      const match = [field.name, ...(importFieldAliases[field.name] ?? [])].find((candidate) =>
        headers.includes(candidate)
      );
      return [field.name, match ?? ""];
    })
  );
  syncImportMappingJson();
  renderImportFileReview();
}

function importFieldsForType(type) {
  const template = dataImportTemplates[type];
  if (!template) return [];
  const requiredCount = requiredImportFieldCount[type] ?? template.headers.length;
  return template.headers.map((name, index) => ({ name, required: index < requiredCount }));
}

const requiredImportFieldCount = {
  CHART_OF_ACCOUNTS: 3,
  CUSTOMERS: 2,
  VENDORS: 3,
  PRODUCTS: 4,
  OPENING_BALANCES: 4,
  OUTSTANDING_INVOICES: 4,
  OUTSTANDING_BILLS: 7,
  CUSTOMER_CREDITS: 3,
  VENDOR_CREDITS: 3,
  INVENTORY_OPENING: 4,
  HISTORICAL_ARCHIVE: 2
};

function renderImportFileReview() {
  if (!importFilePreview) return;
  const preview = importFilePreview;
  elements["data-import-file-summary"].textContent =
    `${preview.fileName} · ${preview.format} · ${formatFileSize(preview.byteSize)} · ${preview.headers.length ? `${preview.headers.length} columns ready to map` : "workbook ready for secure sheet review"}`;
  elements["import-workbook-metadata"].replaceChildren(
    ...[
      ["File", preview.fileName],
      ["Format", preview.format],
      ["Size", formatFileSize(preview.byteSize)],
      ["Sheet", preview.sheet],
      [
        "Preview",
        preview.rows.length
          ? `${preview.rows.length} representative rows; leading zeroes are displayed as text.`
          : "Available after secure upload review"
      ]
    ].flatMap(([term, description]) => [definitionTerm(term), definitionDescription(description)])
  );
  const warnings = elements["import-workbook-warnings"];
  warnings.hidden = !preview.warnings.length;
  warnings.replaceChildren(...preview.warnings.map((warning) => importWarningItem(warning)));
  renderImportPreviewTable(preview);
  renderImportColumnMapper();
  renderImportSourceDetection();
}

function renderImportPreviewTable(preview) {
  const table = elements["import-preview-table"];
  const hasRows = preview.headers.length && preview.rows.length;
  table.closest(".table-wrap").hidden = !hasRows;
  if (!hasRows) return;
  table
    .querySelector("thead")
    .replaceChildren(headerRow(preview.headers.map((header) => header.replaceAll("_", " "))));
  table
    .querySelector("tbody")
    .replaceChildren(...preview.rows.map((values) => row(values.map((value) => value || "—"))));
}

function renderImportColumnMapper() {
  const fields = importFieldsForType(elements["data-import-form"].elements.importType.value);
  const headers = importFilePreview?.headers ?? [];
  const mapped = Object.entries(importColumnMapping).filter(([, source]) => source);
  const sourceCounts = mapped.reduce((counts, [, source]) => {
    counts[source] = (counts[source] ?? 0) + 1;
    return counts;
  }, {});
  const missing = fields.filter((field) => field.required && !importColumnMapping[field.name]);
  const duplicates = Object.entries(sourceCounts).filter(([, count]) => count > 1);
  const mappedCount = mapped.length;
  elements["import-mapping-completeness"].textContent = missing.length
    ? `${mappedCount} of ${fields.length} fields mapped; ${missing.length} required field${missing.length === 1 ? "" : "s"} still need attention.`
    : `${mappedCount} of ${fields.length} fields mapped; required fields are complete. Review duplicate mappings before testing.`;
  elements["import-mapping-issues"].textContent = [
    missing.length
      ? `Required: ${missing.map((field) => importFieldLabel(field.name)).join(", ")}.`
      : "Required fields are mapped.",
    duplicates.length
      ? `Duplicate source column: ${duplicates.map(([source]) => source).join(", ")}. Choose each source column once unless it intentionally supplies both fields.`
      : "No duplicate source columns."
  ].join(" ");
  elements["import-column-mapper"].replaceChildren(
    ...fields.map((field) => {
      const wrapper = document.createElement("label");
      wrapper.className = `import-mapping-row${field.required && !importColumnMapping[field.name] ? " has-error" : ""}`;
      const confidence = importMappingConfidence(field.name, importColumnMapping[field.name]);
      wrapper.innerHTML = `<span class="import-target-field"><strong>${escapeHtml(importFieldLabel(field.name))}</strong><small>${field.required ? "Required" : "Optional"}${minorUnitGuidance(field.name)}</small></span>`;
      const select = document.createElement("select");
      select.name = `mapping-${field.name}`;
      select.setAttribute("aria-label", `Map ${importFieldLabel(field.name)} to a source column`);
      select.append(
        option("", "Choose source column"),
        ...headers.map((header) => option(header, header))
      );
      select.value = importColumnMapping[field.name] ?? "";
      select.addEventListener("change", () => {
        importColumnMapping[field.name] = select.value;
        syncImportMappingJson();
        renderImportColumnMapper();
      });
      const reasoning = document.createElement("span");
      reasoning.className = `mapping-confidence ${confidence.kind}`;
      reasoning.textContent = confidence.text;
      wrapper.append(select, reasoning);
      return wrapper;
    })
  );
  const ignored = headers.filter((header) => !Object.values(importColumnMapping).includes(header));
  elements["ignored-import-columns"].textContent = ignored.length
    ? ignored.join(", ")
    : headers.length
      ? "None. Every source column is currently mapped."
      : "Workbook headings will be available after secure upload review.";
}

function importMappingConfidence(field, source) {
  if (!source) return { kind: "needs-attention", text: "Needs a source column" };
  if (source === field) return { kind: "high", text: "High confidence: exact heading" };
  if ((importFieldAliases[field] ?? []).includes(source))
    return { kind: "medium", text: "Suggested: recognized source heading" };
  return { kind: "review", text: "Manual choice: review values" };
}

function minorUnitGuidance(field) {
  return /(?:_minor|debit_minor|credit_minor)$/.test(field)
    ? " · API value is minor units: 12500 represents $125.00"
    : "";
}

function importFieldLabel(field) {
  return importFieldLabels[field] ?? field.replaceAll("_", " ");
}

function syncImportMappingJson() {
  elements["data-import-form"].elements.mapping.value = JSON.stringify(
    Object.fromEntries(Object.entries(importColumnMapping).filter(([, source]) => source)),
    null,
    2
  );
}

function setImportMappingTab(tab) {
  const preview = tab === "preview";
  elements["import-preview-tab"].setAttribute("aria-selected", String(preview));
  elements["import-preview-tab"].tabIndex = preview ? 0 : -1;
  elements["import-preview-panel"].hidden = !preview;
  elements["import-mapper-tab"].setAttribute("aria-selected", String(!preview));
  elements["import-mapper-tab"].tabIndex = preview ? -1 : 0;
  elements["import-mapper-panel"].hidden = preview;
}

function resetImportWizard(clearFile) {
  currentImportBatch = null;
  resetImportItemMatchReview();
  if (clearFile) {
    const fileInput = elements["data-import-form"].elements.file;
    fileInput.value = "";
    importFilePreview = null;
    importColumnMapping = {};
    elements["import-mapping-workspace"].hidden = true;
    elements["data-import-file-summary"].textContent =
      "Choose an unchanged source export to inspect columns before upload.";
  }
  renderDataImport();
}

function hydrateImportPreviewFromBatch(batch) {
  currentImportItemMatches = batch?.itemMatchSuggestions ?? null;
  if (!batch?.rows?.length) return;
  const headers = Object.keys(batch.rows[0].rawData ?? {});
  if (!headers.length) return;
  importFilePreview = {
    format: batch.sourceFilename?.toLowerCase().endsWith(".xlsx") ? "XLSX" : "CSV",
    fileName: batch.sourceFilename ?? "Uploaded import",
    byteSize: Number(batch.byteSize ?? 0),
    sheet:
      batch.sourceMetadata?.sheet?.name ??
      (batch.sourceFilename?.toLowerCase().endsWith(".xlsx")
        ? "Selected safely during upload review"
        : "Not applicable"),
    headers,
    rows: batch.rows
      .slice(0, 5)
      .map((source) => headers.map((header) => String(source.rawData?.[header] ?? ""))),
    warnings: Array.isArray(batch.sourceMetadata?.warnings) ? batch.sourceMetadata.warnings : []
  };
  importColumnMapping = batch.mapping ?? importColumnMapping;
  elements["import-mapping-workspace"].hidden = false;
  renderImportFileReview();
}

function formatFileSize(value) {
  if (value < 1024) return `${value} bytes`;
  return `${(value / 1024).toFixed(1)} KiB`;
}

function definitionTerm(value) {
  const term = document.createElement("dt");
  term.textContent = value;
  return term;
}

function definitionDescription(value) {
  const description = document.createElement("dd");
  description.textContent = value;
  return description;
}

function importWarningItem(value) {
  const item = document.createElement("li");
  item.textContent = value;
  return item;
}

function escapeHtml(value) {
  return String(value).replace(
    /[&<>'"]/g,
    (character) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" })[character]
  );
}

async function dryRunDataImport() {
  if (!currentImportBatch) return;
  const response = await api(`/v1/imports/${currentImportBatch.id}/dry-run`, jsonRequest({}));
  if (!response.ok) return showError(response);
  currentImportBatch = (await response.json()).batch;
  renderDataImport();
  await loadRecentImportBatches();
  trackProductEvent("MIGRATION_DRY_RUN_COMPLETED");
  trackProductEvent("MIGRATION_REVIEW_COMPLETED");
}

async function commitDataImport() {
  const resuming = currentImportBatch?.status === "RETRYABLE";
  if (
    !currentImportBatch ||
    !window.confirm(
      resuming
        ? "Resume this import? PennyWise will continue only unfinished commit units and reuse the original idempotency keys."
        : "Complete this tested import? PennyWise Accounting will add the reviewed records to this business."
    )
  )
    return;
  const response = await api(
    `/v1/imports/${currentImportBatch.id}/${resuming ? "resume" : "commit"}`,
    jsonRequest({})
  );
  if (!response.ok) return showError(response);
  currentImportBatch = (await response.json()).batch;
  renderDataImport();
  await Promise.all([
    loadSales(),
    loadPurchases(),
    loadInventory(),
    loadReports(),
    loadRecentImportBatches()
  ]);
}

async function acknowledgeDataImport() {
  if (!currentImportBatch) return;
  const response = await api(`/v1/imports/${currentImportBatch.id}/acknowledge`, jsonRequest({}));
  if (!response.ok) return showError(response);
  currentImportBatch = (await response.json()).batch;
  renderDataImport();
  await loadRecentImportBatches();
  trackProductEvent("MIGRATION_RECONCILIATION_ACKNOWLEDGED");
}

async function saveImportSourceControls(event) {
  event.preventDefault();
  if (!currentImportBatch) return;
  const form = event.currentTarget;
  const data = new FormData(form);
  const openingBalances = currentImportBatch.importType === "OPENING_BALANCES";
  const body = {
    sourceReportName: String(data.get("sourceReportName") ?? "").trim(),
    sourceReportDate: String(data.get("sourceReportDate") ?? "").trim(),
    sourceReportChecksum: String(data.get("sourceReportChecksum") ?? "").trim() || undefined,
    sourceDebitMinor: openingBalances
      ? String(data.get("sourceDebitMinor") ?? "").trim()
      : undefined,
    sourceCreditMinor: openingBalances
      ? String(data.get("sourceCreditMinor") ?? "").trim()
      : undefined,
    sourceBalanceMinor: openingBalances
      ? undefined
      : String(data.get("sourceBalanceMinor") ?? "").trim()
  };
  elements["save-import-source-controls"].disabled = true;
  elements["import-source-controls-status"].textContent = "Comparing source totals...";
  const response = await api(
    `/v1/imports/${currentImportBatch.id}/source-controls`,
    jsonRequest(body, "PUT")
  );
  elements["save-import-source-controls"].disabled = false;
  if (!response.ok) {
    elements["import-source-controls-status"].textContent =
      "The source totals could not be saved. Review the highlighted values and try again.";
    return showError(response);
  }
  currentImportBatch = (await response.json()).batch;
  const status = currentImportBatch.reconciliation?.sourceControlStatus;
  elements["import-source-controls-status"].textContent =
    status === "MATCH"
      ? "Source and PennyWise totals agree. The migration can now be confirmed."
      : currentImportBatch.status === "COMMITTED"
        ? "A difference remains. Keep the source system read-only and investigate before confirming."
        : "Source totals saved. PennyWise will compare them after the import is committed.";
  renderDataImport();
  await loadRecentImportBatches();
}

function renderDataImport() {
  if (!currentImportBatch) {
    elements["data-import-status"].textContent = importFilePreview
      ? "File inspected locally. Review the suggested mapping, then upload to create an immutable import batch."
      : "No import uploaded yet. Choose a source and file to begin the guided migration.";
    renderImportOutcomeReview(null);
    elements["dry-run-data-import"].disabled = true;
    elements["commit-data-import"].disabled = true;
    elements["acknowledge-data-import"].disabled = true;
    elements["download-import-errors"].disabled = true;
    setMigrationStep(importFilePreview ? 1 : 0);
    return;
  }
  const rows = currentImportBatch?.rows ?? [];
  const valid = rows.filter((row) => row.status === "VALID").length;
  const invalid = rows.filter((row) => row.status === "INVALID").length;
  const skipped = rows.filter((row) => row.status === "SKIPPED").length;
  elements["data-import-status"].textContent = [
    `Source: ${formatImportSource(currentImportBatch.sourceSystem)}`,
    `File: ${currentImportBatch.sourceFilename ?? "uploaded source"}`,
    currentImportBatch.checksum ? `Source SHA-256: ${currentImportBatch.checksum}` : "",
    `Batch ${currentImportBatch.id} | ${formatImportStatus(currentImportBatch.status)}`,
    `${valid} ready | ${invalid} need attention | ${skipped} skipped`
  ]
    .filter(Boolean)
    .join("\n");
  renderImportOutcomeReview(currentImportBatch);
  elements["dry-run-data-import"].disabled =
    currentImportBatch.status !== "PREVIEWED" || invalid > 0;
  elements["commit-data-import"].disabled = !["DRY_RUN", "RETRYABLE"].includes(
    currentImportBatch.status
  );
  elements["commit-data-import"].textContent =
    currentImportBatch.status === "RETRYABLE" ? "Resume import" : "Complete import";
  elements["acknowledge-data-import"].disabled =
    currentImportBatch.status !== "COMMITTED" ||
    (sourceControlRequiredImportTypes.has(currentImportBatch.importType) &&
      currentImportBatch.reconciliation?.sourceControlStatus !== "MATCH");
  elements["download-import-errors"].disabled = invalid === 0 && !currentImportBatch.errorReport;
  renderImportItemMatchReview();
  setMigrationStep(
    {
      PREVIEWED: 2,
      DRY_RUN: 3,
      RETRYABLE: 4,
      COMMITTED: 4,
      RECONCILED: 5
    }[currentImportBatch.status] ?? 1
  );
}

function renderImportOutcomeReview(batch) {
  const panel = elements["import-outcome-review"];
  if (!panel) return;
  if (!batch) {
    panel.hidden = true;
    elements["import-outcome-metrics"].replaceChildren();
    elements["import-outcome-table"].querySelector("tbody").replaceChildren();
    elements["import-outcome-page-status"].textContent = "";
    elements["previous-import-outcome-page"].disabled = true;
    elements["next-import-outcome-page"].disabled = true;
    elements["import-reconciliation-card"].hidden = true;
    return;
  }
  panel.hidden = false;
  const rows = Array.isArray(batch.rows) ? batch.rows : [];
  const counts = {
    total: rows.length,
    ready: rows.filter((row) => row.status === "VALID").length,
    imported: rows.filter((row) => row.status === "IMPORTED").length,
    staged: rows.filter((row) => row.status === "STAGED").length,
    flagged: rows.filter((row) => row.status === "INVALID" || row.status === "FAILED").length,
    skipped: rows.filter((row) => row.status === "SKIPPED").length
  };
  const tested = ["DRY_RUN", "COMMITTING", "RETRYABLE", "COMMITTED", "RECONCILED"].includes(
    batch.status
  );
  const reconciled = ["COMMITTED", "RECONCILED"].includes(batch.status);
  elements["import-outcome-boundary"].textContent = reconciled
    ? batch.status === "RECONCILED"
      ? "Acknowledged"
      : "Reconciliation required"
    : batch.status === "RETRYABLE"
      ? "Safe resume available"
      : tested
        ? "Dry run passed"
        : counts.flagged
          ? "Needs attention"
          : "Review first";
  elements["import-outcome-summary"].textContent = reconciled
    ? "The committed records are shown with their source identifiers. Compare the control totals below before acknowledging the migration."
    : batch.status === "RETRYABLE"
      ? "A commit unit failed. Completed units are preserved; use Resume import to continue only unfinished units with the original idempotency keys."
      : tested
        ? "The non-posting test passed. PennyWise Accounting will only create records after the explicit commit action."
        : counts.flagged
          ? "Rows with errors cannot be tested or committed. Fix the mapping or source data, then upload and preview again."
          : "Review each source row and mapping before running the non-posting test.";
  const metricValues = [
    ["Source rows", counts.total],
    ["Ready", counts.ready],
    ["Imported", counts.imported],
    ["Staged", counts.staged],
    ["Flagged", counts.flagged],
    ["Skipped", counts.skipped]
  ];
  elements["import-outcome-metrics"].replaceChildren(
    ...metricValues.flatMap(([term, value]) => [definitionTerm(term), definitionDescription(value)])
  );
  const pageCount = Math.max(1, Math.ceil(rows.length / importOutcomePageSize));
  const page = Math.min(Math.max(importOutcomePage, 0), pageCount - 1);
  importOutcomePage = page;
  const pageStart = page * importOutcomePageSize;
  const reviewedRows = rows.slice(pageStart, pageStart + importOutcomePageSize);
  const body = elements["import-outcome-table"].querySelector("tbody");
  body.replaceChildren(
    ...reviewedRows.map((rowValue) => {
      const errors = Array.isArray(rowValue.errors)
        ? rowValue.errors
            .map((error) => (error && typeof error.message === "string" ? error.message : ""))
            .filter(Boolean)
        : [];
      const sourceIdentifier = importOutcomeIdentifier(rowValue);
      const note = errors.length
        ? errors.join("; ")
        : rowValue.status === "IMPORTED"
          ? "Created through the existing accounting service."
          : rowValue.status === "STAGED"
            ? "A recoverable commit unit is staged. Resume the import; do not recreate it manually."
            : rowValue.status === "SKIPPED"
              ? "Skipped by the importer; review before acknowledging."
              : rowValue.status === "VALID"
                ? "Ready for the non-posting test."
                : "Awaiting preview.";
      return row([
        String(rowValue.rowNumber ?? "—"),
        formatImportRowStatus(rowValue.status),
        sourceIdentifier,
        note
      ]);
    })
  );
  const firstReviewed = reviewedRows.length ? pageStart + 1 : 0;
  const lastReviewed = pageStart + reviewedRows.length;
  elements["import-outcome-page-status"].textContent = reviewedRows.length
    ? `Reviewing ${reviewedRows.length} ${reviewedRows.length === 1 ? "row" : "rows"} (${firstReviewed}-${lastReviewed} of ${rows.length} total).`
    : "No rows are available to review.";
  elements["previous-import-outcome-page"].disabled = page === 0;
  elements["next-import-outcome-page"].disabled = page >= pageCount - 1;
  const reconciliation = batch.reconciliation;
  const reconciliationCard = elements["import-reconciliation-card"];
  reconciliationCard.hidden = !reconciliation;
  if (!reconciliation) {
    elements["import-reconciliation-values"].replaceChildren();
    return;
  }
  renderImportSourceControls(batch);
  const displayed = importReconciliationEntries(reconciliation);
  elements["import-reconciliation-values"].replaceChildren(
    ...displayed.flatMap(([term, value]) => [definitionTerm(term), definitionDescription(value)])
  );
}

function renderImportSourceControls(batch) {
  const form = elements["import-source-controls-form"];
  const required = sourceControlRequiredImportTypes.has(batch.importType);
  form.hidden = !required;
  if (!required) return;
  const openingBalances = batch.importType === "OPENING_BALANCES";
  elements["import-source-debit-field"].hidden = !openingBalances;
  elements["import-source-credit-field"].hidden = !openingBalances;
  elements["import-source-balance-field"].hidden = openingBalances;
  form.elements.sourceDebitMinor.required = openingBalances;
  form.elements.sourceCreditMinor.required = openingBalances;
  form.elements.sourceBalanceMinor.required = !openingBalances;
  const controls = batch.sourceControls ?? {};
  form.elements.sourceReportName.value = controls.sourceReportName ?? "";
  form.elements.sourceReportDate.value = controls.sourceReportDate ?? "";
  form.elements.sourceReportChecksum.value = controls.sourceReportChecksum ?? "";
  form.elements.sourceDebitMinor.value = controls.sourceDebitMinor ?? "";
  form.elements.sourceCreditMinor.value = controls.sourceCreditMinor ?? "";
  form.elements.sourceBalanceMinor.value = controls.sourceBalanceMinor ?? "";
  const status = batch.reconciliation?.sourceControlStatus;
  elements["import-source-controls-status"].textContent =
    status === "MATCH"
      ? "Source and PennyWise totals agree."
      : status === "MISMATCH"
        ? "Source and PennyWise totals differ. Do not confirm the migration yet."
        : "Enter the source report totals before confirming this financial migration.";
}

function importOutcomeIdentifier(rowValue) {
  const mapped =
    rowValue.mappedData && typeof rowValue.mappedData === "object" ? rowValue.mappedData : {};
  const raw = rowValue.rawData && typeof rowValue.rawData === "object" ? rowValue.rawData : {};
  return (
    rowValue.externalId ||
    mapped.external_id ||
    mapped.customer_number ||
    mapped.vendor_number ||
    mapped.sku ||
    mapped.code ||
    raw.external_id ||
    raw.customer_number ||
    raw.customer_no ||
    raw.vendor_number ||
    raw.vendor_no ||
    raw.sku ||
    raw.code ||
    "—"
  );
}

function formatImportRowStatus(status) {
  return (
    {
      PENDING: "Awaiting preview",
      VALID: "Ready",
      INVALID: "Flagged",
      STAGED: "Staged for safe resume",
      IMPORTED: "Imported",
      SKIPPED: "Skipped",
      FAILED: "Failed"
    }[status] ?? "Review"
  );
}

function importReconciliationEntries(reconciliation) {
  const currency = multiCurrencyState?.baseCurrency ?? "CAD";
  const labels = {
    importedRows: "Imported rows",
    skippedRows: "Skipped rows",
    failedRows: "Failed rows",
    openingTrialBalanceDifferenceMinor: "Opening balance difference",
    receivablesDifferenceMinor: "Receivables difference",
    payablesDifferenceMinor: "Payables difference",
    inventoryDifferenceMinor: "Inventory difference",
    inventoryReconciled: "Inventory control reconciled",
    nonPostingHistoricalRows: "Non-posting history rows",
    unsupportedFields: "Unsupported fields",
    unsupportedData: "Unsupported data"
  };
  const moneyKeys = new Set([
    "openingTrialBalanceDifferenceMinor",
    "receivablesDifferenceMinor",
    "payablesDifferenceMinor",
    "inventoryDifferenceMinor"
  ]);
  return Object.entries(reconciliation)
    .filter(([key, value]) => Object.hasOwn(labels, key) && value !== undefined && value !== null)
    .map(([key, value]) => [
      labels[key],
      moneyKeys.has(key)
        ? formatMinor(String(value), currency)
        : Array.isArray(value)
          ? value.join(", ") || "None"
          : String(value)
    ]);
}

function resetImportItemMatchReview() {
  currentImportItemMatches = null;
  elements["import-item-match-review"].hidden = true;
  elements["import-item-match-rows"].replaceChildren();
  elements["import-item-match-load-status"].textContent = "";
}

function renderImportItemMatchReview() {
  const panel = elements["import-item-match-review"];
  const suggestions = currentImportItemMatches;
  panel.hidden = !suggestions;
  if (!suggestions) return;
  const suggestionsRows = Array.isArray(suggestions.rows) ? suggestions.rows : [];
  const offset = Number(suggestions.offset ?? 0);
  const total = Number(suggestions.totalEligibleRowCount ?? suggestionsRows.length);
  const first = suggestionsRows.length ? offset + 1 : 0;
  const last = offset + suggestionsRows.length;
  elements["import-item-match-summary"].textContent = suggestionsRows.length
    ? `Rows ${first}-${last} of ${total}. Compare up to ${suggestions.candidatesPerRow ?? 5} possible existing items for each source row.`
    : "No mapped item rows are available on this page.";
  elements["import-item-match-boundary"].textContent =
    suggestions.importBoundary === "EXACT_SKU_REQUIRED_FOR_INVENTORY_POSTING"
      ? "Review aid only. Opening inventory still posts only to an active local item with the exact mapped SKU; a similar suggestion is never selected automatically."
      : "Review aid only. A similar item is not merged, skipped, linked, or imported automatically. Resolve likely duplicates before completing the product import.";
  elements["import-item-match-rows"].replaceChildren(...suggestionsRows.map(importItemMatchRow));
  elements["previous-import-item-matches"].disabled = offset <= 0;
  elements["next-import-item-matches"].disabled = !suggestions.hasMore;
  elements["import-item-match-page-status"].textContent = suggestionsRows.length
    ? `${first}-${last} of ${total}`
    : `0 of ${total}`;
}

function importItemMatchRow(suggestion) {
  const article = document.createElement("article");
  article.className = "import-item-match-row";
  article.dataset.sourceRow = String(suggestion.rowNumber ?? "");
  const heading = document.createElement("div");
  heading.className = "import-item-match-row-heading";
  const title = document.createElement("div");
  const titleText = document.createElement("h5");
  titleText.textContent = `Source row ${suggestion.rowNumber}`;
  const titleHelp = document.createElement("p");
  titleHelp.textContent = "Imported evidence";
  title.append(titleText, titleHelp);
  const sourceEvidence = document.createElement("div");
  sourceEvidence.className = "import-item-source-evidence";
  sourceEvidence.append(
    importItemEvidencePill("SKU", suggestion.evidence?.sku),
    importItemEvidencePill("Name", suggestion.evidence?.name),
    importItemEvidencePill("Description", suggestion.evidence?.description)
  );
  heading.append(title, sourceEvidence);
  article.append(heading);
  const candidates = Array.isArray(suggestion.candidates) ? suggestion.candidates : [];
  if (!candidates.length) {
    const empty = document.createElement("p");
    empty.className = "import-item-match-empty";
    empty.textContent =
      "No likely existing local item was found. This is not an approval to import.";
    article.append(empty);
    return article;
  }
  const candidateGrid = document.createElement("div");
  candidateGrid.className = "import-item-match-candidates";
  candidateGrid.append(...candidates.map(importItemMatchCandidate));
  article.append(candidateGrid);
  return article;
}

function importItemMatchCandidate(candidate) {
  const card = document.createElement("section");
  card.className = "import-item-match-candidate";
  const heading = document.createElement("div");
  heading.className = "import-item-match-candidate-heading";
  const name = document.createElement("strong");
  name.textContent = candidate.productItem?.name || "Unnamed local item";
  const sku = document.createElement("span");
  sku.textContent = candidate.productItem?.sku
    ? `SKU ${candidate.productItem.sku}`
    : "No local SKU";
  heading.append(name, sku);
  card.append(heading);
  if (candidate.productItem?.description) {
    const description = document.createElement("p");
    description.textContent = candidate.productItem.description;
    card.append(description);
  }
  const evidence = document.createElement("div");
  evidence.className = "import-item-field-evidence";
  evidence.setAttribute("aria-label", "Nearest-field evidence");
  const reason = candidate.reason ?? {};
  const matches = Array.isArray(reason.matches) ? reason.matches : [];
  evidence.append(
    importItemEvidencePill(
      "SKU",
      matches.includes("NORMALIZED_SKU")
        ? "exact normalized match"
        : importSimilarity(reason.skuSimilarityBasisPoints)
    ),
    importItemEvidencePill("Name", importSimilarity(reason.nameSimilarityBasisPoints)),
    importItemEvidencePill("Description", importSimilarity(reason.descriptionSimilarityBasisPoints))
  );
  card.append(evidence);
  return card;
}

function importItemEvidencePill(label, value) {
  const pill = document.createElement("span");
  const display = value == null || value === "" ? "not available" : String(value);
  pill.textContent = `${label}: ${display.length > 120 ? `${display.slice(0, 117)}...` : display}`;
  return pill;
}

function importSimilarity(value) {
  if (!Number.isFinite(value)) return "not available";
  const percent = value / 100;
  return `${percent.toFixed(Number.isInteger(percent) ? 0 : 1)}% similar`;
}

async function loadImportItemMatchPage(offset) {
  if (!currentImportBatch?.id) return;
  const previousButton = elements["previous-import-item-matches"];
  const nextButton = elements["next-import-item-matches"];
  previousButton.disabled = true;
  nextButton.disabled = true;
  elements["import-item-match-review"].setAttribute("aria-busy", "true");
  elements["import-item-match-load-status"].textContent = "Loading item suggestions...";
  const response = await api(
    `/v1/imports/${currentImportBatch.id}/item-match-suggestions?offset=${encodeURIComponent(offset)}&limit=25`
  );
  elements["import-item-match-review"].removeAttribute("aria-busy");
  if (!response.ok) {
    renderImportItemMatchReview();
    return showError(response);
  }
  currentImportItemMatches = (await response.json()).itemMatchSuggestions;
  currentImportBatch.itemMatchSuggestions = currentImportItemMatches;
  elements["import-item-match-load-status"].textContent = "Item suggestions updated.";
  renderImportItemMatchReview();
}

function formatImportSource(sourceSystem) {
  return (
    {
      QUICKBOOKS_ONLINE: "QuickBooks Online",
      QUICKBOOKS_DESKTOP: "QuickBooks Desktop",
      XERO: "Xero",
      WAVE: "Wave",
      FRESHBOOKS: "FreshBooks",
      SAGE: "Sage",
      ZOHO_BOOKS: "Zoho Books",
      OTHER: "CSV or spreadsheet (other source)"
    }[sourceSystem] ?? "Other or spreadsheet"
  );
}

function renderImportSourceGuide() {
  const sourceSystem = elements["data-import-form"].elements.sourceSystem.value;
  const guide = importSourceGuides[sourceSystem] ?? importSourceGuides.OTHER;
  elements["data-import-source-guide-heading"].textContent = `Before you export from ${guide.name}`;
  elements["data-import-source-summary"].textContent = guide.summary;
  elements["data-import-source-checklist"].replaceChildren(
    ...guide.steps.map((step) => {
      const item = document.createElement("li");
      item.textContent = step;
      return item;
    })
  );
  const help = elements["data-import-source-help"];
  help.hidden = !guide.helpUrl;
  if (guide.helpUrl) {
    help.href = guide.helpUrl;
    help.textContent = `${guide.name} export help`;
  } else {
    help.removeAttribute("href");
    help.textContent = "";
  }
  renderImportSourceDetection();
}

function renderImportSourceDetection() {
  const detection = elements["data-import-source-detection"];
  if (!detection) return;
  const hint = importFilePreview?.sourceHint;
  if (!hint) {
    detection.hidden = true;
    detection.textContent = "";
    return;
  }
  const selected = elements["data-import-form"].elements.sourceSystem.value;
  const selectedName = formatImportSource(selected);
  detection.hidden = false;
  detection.textContent =
    hint.source === selected
      ? `File signal: this resembles ${hint.name} (${hint.matched} recognizable headings). The selected source label will remain immutable when uploaded.`
      : `File signal: this resembles ${hint.name} (${hint.matched} recognizable headings), but the selected source is ${selectedName}. Confirm the previous system before uploading; PennyWise Accounting will not change the source label automatically.`;
}

function renderImportTemplateGuidance() {
  const importType = elements["data-import-form"].elements.importType.value;
  elements["data-import-currency-warning"].hidden = !foreignMigrationWarningTypes.has(importType);
}

function downloadImportTemplate() {
  const form = elements["data-import-form"];
  const importType = form.elements.importType.value;
  const template = dataImportTemplates[importType];
  if (!template) return;
  const source = formatImportSource(form.elements.sourceSystem.value)
    .toLowerCase()
    .replaceAll(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "");
  const content = `${[template.headers, template.example]
    .map((record) => record.map(csvTemplateCell).join(","))
    .join("\r\n")}\r\n`;
  downloadBlob(
    new globalThis.Blob(["\ufeff", content], { type: "text/csv;charset=utf-8" }),
    `pennywise-${source}-${template.slug}-template.csv`
  );
  showNotice(
    "CSV template downloaded. Replace the example row and keep an unchanged source export."
  );
}

function csvTemplateCell(value) {
  const text = String(value ?? "");
  return /[",\r\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
}

function setMigrationStep(activeIndex) {
  const steps = [...document.querySelectorAll(".migration-steps li")];
  const summaries = [
    "Choose the system you are leaving, then upload an unchanged CSV or XLSX export.",
    "Map each PennyWise Accounting field to a source column. Suggested aliases are visible and remain reviewable.",
    "Review representative rows, warnings, skipped fields, and the immutable source provenance before testing.",
    "Run the non-posting dry run. PennyWise Accounting validates dependencies and reports every row that needs attention.",
    "Commit only after the dry run passes. Every created invoice, bill, or master record remains traceable to its source rows.",
    "Review reconciliation totals and acknowledge the completed migration. Keep the source system read-only until controls agree."
  ];
  const boundedIndex = Math.max(0, Math.min(activeIndex, Math.max(steps.length - 1, 0)));
  steps.forEach((step, index) => {
    step.classList.toggle("is-current", index === boundedIndex);
    step.classList.toggle("is-complete", index < boundedIndex);
    if (index === boundedIndex) step.setAttribute("aria-current", "step");
    else step.removeAttribute("aria-current");
  });
  const summary = elements["migration-step-summary"];
  if (summary) summary.textContent = summaries[boundedIndex] ?? summaries[0];
}

function formatImportStatus(status) {
  return (
    {
      UPLOADED: "File uploaded; review mapping",
      VALIDATED: "Validated; preview is ready",
      PREVIEWED: "Ready to test",
      DRY_RUN: "Test passed",
      COMMITTING: "Commit in progress",
      RETRYABLE: "Interrupted safely; resume available",
      COMMITTED: "Import committed; reconcile controls",
      FAILED: "Import failed before posting",
      COMPENSATION_REQUIRED: "Manual recovery required",
      RECONCILED: "Reconciliation confirmed"
    }[status] ?? formatRole(status)
  );
}

async function downloadDataImportErrors() {
  if (!currentImportBatch) return;
  const response = await api(`/v1/imports/${currentImportBatch.id}/errors.csv`);
  if (!response.ok) return showError(response);
  downloadBlob(await response.blob(), "pennywise-import-errors.csv");
}

async function requestOrganizationExport(event) {
  event.preventDefault();
  const data = new FormData(event.currentTarget);
  const response = await api(
    "/v1/exports",
    jsonRequest({ includeAttachments: data.get("includeAttachments") === "on" })
  );
  if (!response.ok) return showError(response);
  currentOrganizationExport = await response.json();
  renderOrganizationExport();
  globalThis.setTimeout(() => void refreshOrganizationExport(), 250);
}

async function refreshOrganizationExport() {
  if (!currentOrganizationExport) return;
  const response = await api(`/v1/exports/${currentOrganizationExport.job.id}`);
  if (!response.ok) return showError(response);
  currentOrganizationExport.job = (await response.json()).job;
  renderOrganizationExport();
  if (["PENDING", "PROCESSING"].includes(currentOrganizationExport.job.status))
    globalThis.setTimeout(() => void refreshOrganizationExport(), 500);
}

function renderOrganizationExport() {
  const job = currentOrganizationExport.job;
  elements["organization-export-status"].textContent = [
    formatRole(job.status),
    job.checksum ? `SHA-256 ${job.checksum}` : "",
    job.byteSize == null ? "" : `${job.byteSize} bytes`,
    `Expires ${job.expiresAt}`
  ]
    .filter(Boolean)
    .join("\n");
  elements["refresh-organization-export"].disabled = false;
  elements["download-organization-export"].disabled = job.status !== "READY";
}

async function downloadOrganizationExport() {
  if (!currentOrganizationExport) return;
  const response = await api(`/v1/exports/${currentOrganizationExport.job.id}/download`, {
    headers: { "x-export-token": currentOrganizationExport.downloadToken }
  });
  if (!response.ok) return showError(response);
  downloadBlob(await response.blob(), `pennywise-${identity.activeOrganizationId}-export-v1.json`);
}

async function requestOrganizationClosure(event) {
  event.preventDefault();
  const data = new FormData(event.currentTarget);
  const response = await api(
    "/v1/organization-closure",
    jsonRequest({
      reason: data.get("reason"),
      legalHold: data.get("legalHold") === "on",
      ...(currentOrganizationExport?.job?.id
        ? { exportJobId: currentOrganizationExport.job.id }
        : {})
    })
  );
  if (!response.ok) return showError(response);
  currentClosureRequest = (await response.json()).closure;
  elements["organization-closure-status"].textContent = formatRole(currentClosureRequest.status);
  elements["finalize-organization-closure"].disabled = currentClosureRequest.status !== "REQUESTED";
}

async function finalizeOrganizationClosure() {
  if (
    !currentClosureRequest ||
    !window.confirm("Schedule organization retention and revoke active access?")
  )
    return;
  const response = await api(
    `/v1/organization-closure/${currentClosureRequest.id}/finalize`,
    jsonRequest({})
  );
  if (!response.ok) return showError(response);
  currentClosureRequest = (await response.json()).closure;
  elements["organization-closure-status"].textContent =
    `${formatRole(currentClosureRequest.status)} | ${currentClosureRequest.retentionUntil}`;
  elements["finalize-organization-closure"].disabled = true;
}

function downloadBlob(blob, fileName) {
  const link = document.createElement("a");
  link.href = URL.createObjectURL(blob);
  link.download = fileName;
  link.click();
  globalThis.setTimeout(() => URL.revokeObjectURL(link.href), 0);
}

async function loadOwnerWorkspace() {
  if (!identity?.activeOrganizationId) return;
  await Promise.allSettled([loadSales(), loadProjects(), loadCalendar(), loadContracts()]);
  renderOwnerWorkspace();
}

function renderOwnerWorkspace() {
  const metrics = elements["owner-workspace-metrics"];
  if (!metrics) return;
  const openInvoices = invoices.filter(
    (invoice) => !["PAID", "VOID", "CANCELLED", "CREDITED"].includes(invoice.status)
  );
  const estimatesToFollowUp = estimates.filter((estimate) =>
    ["DRAFT", "SENT", "VIEWED"].includes(estimate.status)
  );
  const activeJobs = projects.filter(
    (project) => !["COMPLETED", "CANCELLED", "ARCHIVED"].includes(project.status ?? "ACTIVE")
  );
  const draftContracts = contracts.filter((contract) => contract.status === "DRAFT");
  const metricItems = [
    {
      label: "Open invoices",
      value: String(openInvoices.length),
      detail: "Need review, posting, or follow-up"
    },
    {
      label: "Estimates to follow up",
      value: String(estimatesToFollowUp.length),
      detail: "Draft, sent, or viewed"
    },
    { label: "Active jobs", value: String(activeJobs.length), detail: "Scheduled or in progress" },
    {
      label: "Draft agreements",
      value: String(draftContracts.length),
      detail: "Need details or review"
    }
  ];
  metrics.replaceChildren(
    ...metricItems.map((item) => {
      const wrapper = document.createElement("div");
      const term = document.createElement("dt");
      const value = document.createElement("dd");
      const detail = document.createElement("small");
      term.textContent = item.label;
      value.textContent = item.value;
      detail.textContent = item.detail;
      wrapper.append(term, value, detail);
      return wrapper;
    })
  );

  const today = localCalendarDate();
  const upcoming = calendarEvents
    .filter((event) => event.date >= today)
    .sort((left, right) => left.date.localeCompare(right.date))
    .slice(0, 4);
  elements["owner-today-list"].replaceChildren(
    ...(upcoming.length
      ? upcoming.map((event) =>
          ownerWorkspaceItem(
            `${formatOwnerDate(event.date)} · ${event.title}`,
            `${calendarTypeLabel(event)} · ${event.source?.reference ?? "Planning item"}`,
            "Open calendar",
            () => openOwnerAction("calendar")
          )
        )
      : [
          ownerWorkspaceEmpty(
            "No upcoming items in this calendar view. Plan a job or add a work item."
          )
        ])
  );

  const followUps = [
    ...estimatesToFollowUp.slice(0, 2).map((estimate) => ({
      title: `${estimate.estimateNumber ?? estimate.provisionalIdentifier} · ${estimate.customerName}`,
      detail: `${formatRole(estimate.status)} · ${formatMinor(estimate.grandTotalMinor)}`,
      label: "Open estimate",
      action: () => openOwnerAction("estimate")
    })),
    ...openInvoices
      .filter((invoice) => invoice.dueDate && invoice.dueDate < today)
      .slice(0, 2)
      .map((invoice) => ({
        title: `${invoice.invoiceNumber ?? invoice.provisionalIdentifier} · ${invoice.customerNameSnapshot}`,
        detail: `Past due ${formatOwnerDate(invoice.dueDate)} · ${formatMinor(invoice.grandTotalMinor, invoice.currency)}`,
        label: "Open invoices",
        action: () => openOwnerAction("invoice")
      }))
  ];
  elements["owner-attention-list"].replaceChildren(
    ...(followUps.length
      ? followUps.map((item) =>
          ownerWorkspaceItem(item.title, item.detail, item.label, item.action)
        )
      : [
          ownerWorkspaceEmpty(
            "No sales follow-up is currently flagged. Create an estimate when a new opportunity arrives."
          )
        ])
  );

  const jobsAndContracts = [
    ...activeJobs.slice(0, 3).map((project) => ({
      title: project.name,
      detail: `${project.projectNumber ?? "Job"} · ${customerNameForId(project.customerId)}`,
      label: "Open job",
      action: () => openOwnerAction("job")
    })),
    ...draftContracts.slice(0, 3).map((contract) => ({
      title: contract.title,
      detail: `${contract.unresolvedVariables?.length ?? 0} required field${contract.unresolvedVariables?.length === 1 ? "" : "s"} remaining`,
      label: "Open agreement",
      action: () => openContract(contract.id)
    }))
  ];
  elements["owner-jobs-list"].replaceChildren(
    ...(jobsAndContracts.length
      ? jobsAndContracts.map((item) =>
          ownerWorkspaceItem(item.title, item.detail, item.label, item.action)
        )
      : [ownerWorkspaceEmpty("Create a job or agreement to begin the delivery workflow.")])
  );
}

function ownerWorkspaceItem(title, detail, actionLabel, action) {
  const article = document.createElement("article");
  article.className = "owner-workspace-item";
  const copy = document.createElement("div");
  const heading = document.createElement("h3");
  const text = document.createElement("p");
  const button = document.createElement("button");
  heading.textContent = title;
  text.textContent = detail;
  button.type = "button";
  button.className = "text-command";
  button.textContent = actionLabel;
  button.addEventListener("click", action);
  copy.append(heading, text);
  article.append(copy, button);
  return article;
}

function ownerWorkspaceEmpty(message) {
  const item = document.createElement("p");
  item.className = "empty-state";
  item.textContent = message;
  return item;
}

function customerNameForId(customerId) {
  return (
    customers.find((customer) => customer.id === customerId)?.displayName ?? "No customer selected"
  );
}

function formatOwnerDate(value) {
  if (!value) return "No date";
  const date = new Date(`${value.slice(0, 10)}T12:00:00`);
  return Number.isNaN(date.valueOf())
    ? value
    : new Intl.DateTimeFormat("en-CA", { month: "short", day: "numeric" }).format(date);
}

function openOwnerAction(action) {
  const destinations = {
    invoice: { workspaceId: "sales-workspace", targetId: "invoice-form" },
    estimate: { workspaceId: "sales-workspace", targetId: "estimate-form" },
    contact: { workspaceId: "sales-workspace", targetId: "customer-form" },
    job: { planningTab: "projects", targetId: "project-form" },
    calendar: { planningTab: "calendar", targetId: "calendar-heading" },
    contract: { workspaceId: "contracts-workspace", targetId: "contract-form" },
    contracts: { workspaceId: "contracts-workspace", targetId: "contract-form" },
    sales: { workspaceId: "sales-workspace", targetId: "invoice-designer-section" }
  };
  const destination = destinations[action];
  if (!destination) return;
  if (destination.planningTab) {
    openPlanningTab(destination.planningTab, { scroll: false });
  } else {
    activateWorkspace(destination.workspaceId, false);
  }
  globalThis.setTimeout(() => {
    const target = document.getElementById(destination.targetId);
    target?.scrollIntoView({ behavior: preferredScrollBehavior(), block: "start" });
    focusCreateTarget(target);
  }, 0);
}

async function loadContracts({ selectedContractId = activeContract?.id } = {}) {
  if (!identity?.activeOrganizationId) return;
  const [templatesResponse, contractsResponse] = await Promise.all([
    api("/v1/contracts/templates", {}, true),
    api("/v1/contracts", {}, true)
  ]);
  if (!templatesResponse.ok || !contractsResponse.ok) {
    const unavailable =
      templatesResponse.status === 403 || contractsResponse.status === 403
        ? "Contracts are not available for your current role."
        : "Contracts could not be loaded. Refresh and try again.";
    renderContractsUnavailable(unavailable);
    return;
  }
  const templateResult = await templatesResponse.json();
  const contractResult = await contractsResponse.json();
  contractTemplates = [
    ...(templateResult.starters ?? []).map((template) => ({
      ...template,
      sourceType: "starter",
      optionValue: `starter:${template.key}`
    })),
    ...(templateResult.templates ?? []).map((template) => ({
      ...template,
      sourceType: "company",
      optionValue: `company:${template.id}`
    }))
  ];
  contracts = contractResult.contracts ?? [];
  const contractId =
    selectedContractId && contracts.some((contract) => contract.id === selectedContractId)
      ? selectedContractId
      : null;
  activeContract = contractId ? await fetchContract(contractId) : null;
  renderContracts();
  renderOwnerWorkspace();
}

function renderContractsUnavailable(message) {
  contractTemplates = [];
  contracts = [];
  activeContract = null;
  elements["contracts-list"].replaceChildren(ownerWorkspaceEmpty(message));
  elements["contract-template-source"].textContent = message;
  elements["contract-preview"].textContent = message;
  const form = elements["contract-form"];
  for (const control of form.elements) control.disabled = true;
  elements["contract-save-status"].textContent = "Unavailable";
}

function renderContracts() {
  renderContractTemplateOptions();
  renderContractList();
  renderContractEditor();
}

function renderContractTemplateOptions() {
  const select = elements["contract-starter-select"];
  const selected = activeContract
    ? activeContract.templateId
      ? `company:${activeContract.templateId}`
      : activeContract.templateKey
        ? `starter:${activeContract.templateKey}`
        : select.value
    : select.value;
  select.replaceChildren(
    option("", "Choose a starter document"),
    ...contractTemplates.map((template) => option(template.optionValue, template.title))
  );
  if (contractTemplates.some((template) => template.optionValue === selected))
    select.value = selected;
}

function selectedContractTemplate() {
  return (
    contractTemplates.find(
      (template) => template.optionValue === elements["contract-starter-select"].value
    ) ?? null
  );
}

function renderContractList() {
  const list = elements["contracts-list"];
  if (!contracts.length) {
    list.replaceChildren(
      ownerWorkspaceEmpty("No saved agreements yet. Choose a starter and create a draft.")
    );
    return;
  }
  list.replaceChildren(
    ...contracts.map((contract) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = "contract-list-item";
      button.dataset.contractId = contract.id;
      button.setAttribute("aria-current", String(contract.id === activeContract?.id));
      const title = document.createElement("strong");
      const detail = document.createElement("span");
      const status = document.createElement("span");
      title.textContent = contract.title;
      detail.textContent = `${formatRole(contract.status)} · updated ${formatOwnerDate(contract.updatedAt)}`;
      status.className = "status-pill";
      status.textContent = contract.unresolvedVariables?.length
        ? `${contract.unresolvedVariables.length} required field${contract.unresolvedVariables.length === 1 ? "" : "s"}`
        : "Complete";
      button.append(title, detail, status);
      return button;
    })
  );
}

function renderContractEditor() {
  const form = elements["contract-form"];
  const source = activeContract ?? selectedContractTemplate();
  const isDraft = activeContract?.status === "DRAFT";
  const isNew = !activeContract;
  elements["contract-starter-select"].disabled = Boolean(activeContract);
  renderContractReferenceSelects();
  form.elements.contractId.value = activeContract?.id ?? "";
  form.elements.title.value = activeContract?.title ?? "";
  form.elements.jurisdiction.value = activeContract?.jurisdiction ?? source?.jurisdiction ?? "";
  form.elements.content.value = activeContract?.content ?? "";
  form.elements.content.disabled = !isDraft;
  form.elements.customerId.disabled = !isNew;
  form.elements.projectId.disabled = !isNew;
  form.elements.estimateId.disabled = !isNew;
  form.elements.title.disabled = Boolean(activeContract && !isDraft);
  form.elements.jurisdiction.disabled = Boolean(activeContract && !isDraft);
  elements["contract-editor-heading"].textContent = activeContract
    ? activeContract.title
    : "Create a work agreement";
  elements["contract-save-status"].textContent = activeContract
    ? `${formatRole(activeContract.status)} · v${activeContract.version}`
    : source
      ? "Ready to create a draft"
      : "Choose a starter";
  elements["save-contract-draft"].textContent = activeContract ? "Save draft" : "Create draft";
  elements["save-contract-draft"].disabled = Boolean(activeContract && !isDraft) || !source;
  elements["mark-contract-ready"].hidden = !isDraft;
  elements["print-contract"].hidden = !activeContract;
  const acknowledgement = elements["contract-review-acknowledgement"];
  acknowledgement.hidden = !isDraft;
  form.elements.legalReviewAcknowledged.disabled = !isDraft;
  form.elements.legalReviewAcknowledged.checked = Boolean(
    activeContract?.legalReviewAcknowledgedAt
  );
  renderContractVariableFields(activeContract?.variableSchema ?? []);
  renderContractSource(source);
  elements["contract-preview"].textContent =
    activeContract?.renderedText ??
    (source
      ? "Create the draft to apply company, customer, job, and estimate details before reviewing the text."
      : "Choose a starter and create a draft to see the print-ready preview.");
}

function renderContractReferenceSelects() {
  const form = elements["contract-form"];
  const values = {
    customerId: activeContract?.customerId ?? form.elements.customerId.value,
    projectId: activeContract?.projectId ?? form.elements.projectId.value,
    estimateId: activeContract?.estimateId ?? form.elements.estimateId.value
  };
  form.elements.customerId.replaceChildren(
    option("", "No customer selected"),
    ...customers.map((customer) =>
      option(customer.id, `${customer.customerNumber ?? "Customer"} · ${customer.displayName}`)
    )
  );
  form.elements.projectId.replaceChildren(
    option("", "No job selected"),
    ...projects.map((project) =>
      option(project.id, `${project.projectNumber ?? "Job"} · ${project.name}`)
    )
  );
  form.elements.estimateId.replaceChildren(
    option("", "No estimate selected"),
    ...estimates.map((estimate) =>
      option(
        estimate.id,
        `${estimate.estimateNumber ?? estimate.provisionalIdentifier} · ${estimate.customerName}`
      )
    )
  );
  form.elements.customerId.value = values.customerId ?? "";
  form.elements.projectId.value = values.projectId ?? "";
  form.elements.estimateId.value = values.estimateId ?? "";
}

function renderContractVariableFields(definitions) {
  const container = elements["contract-variable-fields"];
  if (!definitions.length) {
    container.replaceChildren(
      ownerWorkspaceEmpty(
        activeContract
          ? "This agreement has no additional variable fields. Review the draft wording before marking it ready."
          : "Create a draft to load company, customer, job, payment, and schedule fields."
      )
    );
    return;
  }
  const editable = activeContract?.status === "DRAFT";
  container.replaceChildren(
    ...definitions.map((definition) => {
      const label = document.createElement("label");
      label.className = "contract-variable-field";
      label.textContent = definition.label;
      const input = document.createElement("input");
      input.name = `contractVariable:${definition.key}`;
      input.type = definition.kind === "date" ? "date" : "text";
      input.maxLength = 4000;
      input.required = definition.required;
      input.disabled = !editable;
      input.value = activeContract?.variableValues?.[definition.key] ?? "";
      if (definition.kind === "money") {
        input.inputMode = "decimal";
        input.placeholder = "0.00";
      }
      const requirement = document.createElement("small");
      requirement.textContent = definition.required ? "Required before review" : "Optional";
      label.append(input, requirement);
      return label;
    })
  );
}

function renderContractSource(source) {
  const sourcePanel = elements["contract-template-source"];
  const sourceLink = elements["contract-source-link"];
  sourcePanel.replaceChildren();
  sourceLink.hidden = true;
  sourceLink.removeAttribute("href");
  if (!source) {
    sourcePanel.textContent = "Choose a starter to see its source guidance.";
    return;
  }
  const heading = document.createElement("strong");
  const detail = document.createElement("span");
  heading.textContent = source.title ?? "Selected agreement";
  detail.textContent = source.sourceLabel ?? "Company document";
  sourcePanel.append(heading, detail);
  if (source.sourceUrl) {
    sourceLink.href = source.sourceUrl;
    sourceLink.hidden = false;
  }
}

function contractVariableValuesFromForm() {
  const values = {};
  for (const definition of activeContract?.variableSchema ?? []) {
    const input = elements["contract-form"].elements[`contractVariable:${definition.key}`];
    values[definition.key] = String(input?.value ?? "").trim();
  }
  return values;
}

async function saveContractDraft(event) {
  event.preventDefault();
  const form = elements["contract-form"];
  const source = selectedContractTemplate();
  const title = form.elements.title.value.trim();
  const jurisdiction = form.elements.jurisdiction.value.trim();
  const wasEditing = Boolean(activeContract);
  let response;
  if (activeContract) {
    response = await api(
      `/v1/contracts/${activeContract.id}`,
      jsonRequest(
        {
          version: activeContract.version,
          title: title || undefined,
          content: form.elements.content.value.trim(),
          jurisdiction: jurisdiction || null,
          variableValues: contractVariableValuesFromForm()
        },
        "PATCH"
      )
    );
  } else {
    if (!source) return showNotice("Choose a contract starter before creating a draft.", true);
    response = await api(
      "/v1/contracts",
      jsonRequest({
        ...(source.sourceType === "starter"
          ? { starterKey: source.key }
          : { templateId: source.id }),
        ...(title ? { title } : {}),
        ...(jurisdiction ? { jurisdiction } : {}),
        customerId: form.elements.customerId.value || null,
        projectId: form.elements.projectId.value || null,
        estimateId: form.elements.estimateId.value || null,
        variableValues: {}
      })
    );
  }
  if (!response.ok) return showError(response);
  const contract = (await response.json()).contract;
  await loadContracts({ selectedContractId: contract.id });
  showNotice(wasEditing ? "Contract draft saved." : "Contract draft created.");
}

async function markContractReady() {
  if (!activeContract || activeContract.status !== "DRAFT") return;
  const form = elements["contract-form"];
  if (!form.elements.legalReviewAcknowledged.checked) {
    return showNotice(
      "Confirm the legal and jurisdictional review acknowledgement before continuing.",
      true
    );
  }
  const response = await api(
    `/v1/contracts/${activeContract.id}/ready`,
    jsonRequest({ version: activeContract.version, legalReviewAcknowledged: true })
  );
  if (!response.ok) return showError(response);
  const contract = (await response.json()).contract;
  await loadContracts({ selectedContractId: contract.id });
  showNotice("Contract marked ready for review. It was not sent or signed automatically.");
}

async function fetchContract(contractId) {
  const response = await api(`/v1/contracts/${contractId}`, {}, true);
  if (!response.ok) {
    if (response.status !== 404) await showError(response);
    return null;
  }
  return (await response.json()).contract;
}

async function openContract(contractId) {
  activateWorkspace("contracts-workspace", false, false);
  const contract = await fetchContract(contractId);
  if (!contract) return;
  activeContract = contract;
  renderContracts();
  document.getElementById("contract-form")?.scrollIntoView({
    behavior: preferredScrollBehavior(),
    block: "start"
  });
}

function handleContractListAction(event) {
  const button = event.target.closest("[data-contract-id]");
  if (!(button instanceof globalThis.HTMLButtonElement)) return;
  void openContract(button.dataset.contractId);
}

function resetContractDraft() {
  activeContract = null;
  const sourceValue = elements["contract-starter-select"].value;
  const form = elements["contract-form"];
  form.reset();
  if (sourceValue) elements["contract-starter-select"].value = sourceValue;
  renderContractList();
  renderContractEditor();
}

function printContractDraft() {
  if (!activeContract?.renderedText) {
    showNotice("Create or open a contract before printing.", true);
    return;
  }
  const frame = document.createElement("iframe");
  frame.className = "contract-print-frame";
  frame.title = `${activeContract.title} print view`;
  // The srcdoc is assembled exclusively from escaped title and rendered text.
  // Allowing scripts lets the browser honor the print call; no script content
  // is interpolated into the generated document.
  frame.sandbox = "allow-same-origin allow-modals allow-scripts";
  frame.srcdoc = `<!doctype html><html><head><meta charset="utf-8"><title>${escapeHtml(activeContract.title)}</title><style>body{font-family:Arial,sans-serif;color:#172b4d;line-height:1.48;margin:28px}pre{font:inherit;white-space:pre-wrap}h1{font-size:18px;margin:0 0 18px}@page{margin:15mm}</style></head><body><h1>${escapeHtml(activeContract.title)}</h1><pre>${escapeHtml(activeContract.renderedText)}</pre></body></html>`;
  frame.addEventListener("load", () => {
    frame.contentWindow?.focus();
    frame.contentWindow?.print();
    globalThis.setTimeout(() => frame.remove(), 1200);
  });
  document.body.append(frame);
}

async function loadIntegrations() {
  if (!identity?.activeOrganizationId) return;
  setCommerceView(activeCommerceView);
  const [providerResponse, connectorResponse] = await Promise.all([
    api("/v1/organizations/current/connectors/providers", {}, true),
    api("/v1/organizations/current/connectors", {}, true)
  ]);
  if (providerResponse.ok) connectorProviders = (await providerResponse.json()).providers;
  if (connectorResponse.ok) connectorInstallations = (await connectorResponse.json()).connectors;
  else if (connectorResponse.status !== 403) await showError(connectorResponse);
  renderConnectorProviders();
  renderConnectorSelects();
  renderConnectorInstallations();
  renderConnectorSyncContinuation();
  setDefaultConnectorDates();
  await Promise.all([loadCommerceInbox(), loadCatalogAutomation(), loadEmailConnections()]);
}

async function loadEmailConnections() {
  if (!identity?.activeOrganizationId) return;
  const response = await api("/v1/email-connections", {}, true);
  if (!response.ok) {
    emailConnections = [];
    const message =
      response.status === 403
        ? "Email connections are not available for your current role."
        : "Email connections could not be loaded. Refresh and try again.";
    renderEmailConnections(message);
    return;
  }
  const payload = await response.json();
  emailConnections = payload.providers ?? [];
  emailDeliveryConfiguration = payload.delivery ?? {
    mode: "DISABLED",
    enabled: false,
    reason: "disabled"
  };
  renderEmailConnections();
}

function renderEmailConnections(unavailableMessage = "") {
  const list = elements["email-connections-list"];
  renderEmailDeliveryConfiguration();
  if (unavailableMessage) {
    list.replaceChildren(ownerWorkspaceEmpty(unavailableMessage));
    return;
  }
  if (!emailConnections.length) {
    list.replaceChildren(
      ownerWorkspaceEmpty("No email providers are available in this environment.")
    );
    return;
  }
  list.replaceChildren(
    ...emailConnections.map((provider) => {
      const card = document.createElement("article");
      card.className = "email-connection-card";
      const copy = document.createElement("div");
      const heading = document.createElement("h3");
      const detail = document.createElement("p");
      const status = document.createElement("span");
      const actions = document.createElement("div");
      const providerLabel =
        provider.provider === "GMAIL"
          ? "Gmail"
          : provider.provider === "MICROSOFT"
            ? "Microsoft Outlook / Hotmail"
            : "SMTP relay";
      heading.textContent = providerLabel;
      status.className = "status-pill";
      if (!provider.configured) {
        status.textContent = "Not configured";
        detail.textContent =
          provider.provider === "SMTP"
            ? "This environment needs the secure email credential encryption key before an SMTP relay can be tested or saved."
            : "This environment needs the provider OAuth client and secure credential encryption before a mailbox can be connected.";
        const action = document.createElement("button");
        action.textContent = "Unavailable";
        action.disabled = true;
        action.type = "button";
        action.className = "secondary-command";
        actions.append(action);
      } else if (provider.connection?.status === "CONNECTED") {
        status.textContent = provider.connection.isDefaultSender ? "Sending mailbox" : "Connected";
        detail.textContent = provider.connection.senderEmail
          ? `${provider.provider === "SMTP" ? "Configured from" : "Authorized as"} ${provider.connection.senderEmail}.${provider.connection.isDefaultSender ? " This is the default sending mailbox." : " Choose it as the default mailbox before sending."}`
          : provider.connection.isDefaultSender
            ? "Configured as the default sending mailbox. Sending remains an explicit action."
            : "Configured. Choose it as the default mailbox before sending.";
        if (!provider.connection.isDefaultSender) {
          const makeDefault = document.createElement("button");
          makeDefault.type = "button";
          makeDefault.className = "secondary-command";
          makeDefault.textContent = "Use for sending";
          makeDefault.dataset.emailConnectionAction = "default";
          makeDefault.dataset.connectionId = provider.connection.id;
          actions.append(makeDefault);
        }
        const disconnect = document.createElement("button");
        disconnect.type = "button";
        disconnect.className = "secondary-command";
        disconnect.textContent = "Disconnect";
        disconnect.dataset.emailConnectionAction = "disconnect";
        disconnect.dataset.connectionId = provider.connection.id;
        actions.append(disconnect);
      } else if (
        provider.provider === "SMTP" &&
        (emailDeliveryConfiguration.mode !== "SMTP" || emailDeliveryConfiguration.enabled !== true)
      ) {
        status.textContent = "Delivery disabled";
        detail.textContent =
          "Enable SMTP delivery in the controlled runtime before PennyWise can test or store this relay.";
        const action = document.createElement("button");
        action.textContent = "SMTP unavailable";
        action.disabled = true;
        action.type = "button";
        action.className = "secondary-command";
        actions.append(action);
      } else {
        status.textContent = provider.connection?.status
          ? formatRole(provider.connection.status)
          : "Not connected";
        detail.textContent = provider.connection?.lastErrorCode
          ? provider.provider === "SMTP"
            ? "The last SMTP test was not completed. Check the relay settings and test again."
            : "The last authorization was not completed. Start a new authorization when ready."
          : provider.provider === "SMTP"
            ? "Enter your relay settings. PennyWise sends one test email before it saves or enables this connection."
            : "Authorize only the minimum sending permission from the provider's sign-in page.";
        const action = document.createElement("button");
        action.textContent =
          provider.provider === "SMTP"
            ? "Configure SMTP"
            : provider.connection?.status === "PENDING"
              ? "Authorize again"
              : "Connect";
        action.dataset.emailConnectionAction =
          provider.provider === "SMTP" ? "configure-smtp" : "connect";
        action.dataset.provider = provider.provider;
        action.type = "button";
        action.className = "secondary-command";
        actions.append(action);
      }
      copy.append(heading, status, detail);
      actions.className = "email-connection-actions";
      card.append(copy, actions);
      return card;
    })
  );
}

function renderEmailDeliveryConfiguration() {
  const status = elements["email-configuration-status"];
  const configuration = emailDeliveryConfiguration;
  status.classList.toggle("is-ready", configuration.enabled === true);
  const messages = {
    ready:
      "Email delivery is ready. An explicit invoice or estimate email uses the selected default mailbox or SMTP relay.",
    disabled:
      "Email delivery is disabled for this environment. Connect a mailbox now if desired; no customer mail can be sent until delivery is enabled.",
    "invalid-mode":
      "Email delivery is disabled because its configured mode is invalid. Set EMAIL_DELIVERY_MODE to connected-mailbox or smtp after reviewing the setup guide.",
    "beta-approval-required":
      "Email delivery is waiting for the beta delivery approval flag. Mailbox connections remain safe to test, but no customer email can be sent yet.",
    "oauth-provider-not-configured":
      "Email delivery needs at least one configured Gmail or Microsoft OAuth client before it can be enabled.",
    "credential-encryption-unavailable":
      "Email delivery needs the secure email credential encryption key before it can be enabled."
  };
  status.textContent = messages[configuration.reason] ?? messages.disabled;
}

async function handleEmailConnectionAction(event) {
  const button = event.target.closest("[data-email-connection-action]");
  if (!(button instanceof globalThis.HTMLButtonElement) || button.disabled) return;
  if (button.dataset.emailConnectionAction === "configure-smtp") {
    openSmtpConnectionDialog();
    return;
  }
  if (button.dataset.emailConnectionAction === "default") {
    button.disabled = true;
    const response = await api(
      `/v1/email-connections/${button.dataset.connectionId}/default`,
      jsonRequest({})
    );
    if (!response.ok) {
      button.disabled = false;
      return showError(response);
    }
    await loadEmailConnections();
    showNotice(
      "Default sending mailbox updated. Customer email still requires an explicit send action."
    );
    return;
  }
  if (button.dataset.emailConnectionAction === "disconnect") {
    button.disabled = true;
    const response = await api(
      `/v1/email-connections/${button.dataset.connectionId}/disconnect`,
      jsonRequest({})
    );
    if (!response.ok) {
      button.disabled = false;
      return showError(response);
    }
    await loadEmailConnections();
    showNotice("Email connection disconnected and its stored credential was removed.");
    return;
  }
  button.disabled = true;
  const response = await api(
    `/v1/email-connections/${button.dataset.provider}/authorize`,
    jsonRequest({})
  );
  if (!response.ok) {
    button.disabled = false;
    return showError(response);
  }
  const result = await response.json();
  window.location.assign(result.authorizationUrl);
}

function openSmtpConnectionDialog() {
  const dialog = elements["smtp-connection-dialog"];
  const form = elements["smtp-connection-form"];
  form.reset();
  form.elements.port.value = "587";
  form.elements.tlsMode.value = "STARTTLS";
  elements["smtp-connection-status"].textContent =
    "The relay is saved only after it accepts this test message over encrypted SMTP.";
  if (typeof dialog.showModal === "function") dialog.showModal();
  else dialog.setAttribute("open", "");
  form.elements.host.focus();
}

async function configureSmtpConnection(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const submit = form.querySelector('button[type="submit"]');
  if (submit) submit.disabled = true;
  const values = new FormData(form);
  const payload = {
    host: String(values.get("host") ?? ""),
    port: Number(values.get("port")),
    tlsMode: String(values.get("tlsMode") ?? ""),
    username: String(values.get("username") ?? ""),
    password: String(values.get("password") ?? ""),
    fromAddress: String(values.get("fromAddress") ?? ""),
    testRecipient: String(values.get("testRecipient") ?? "")
  };
  elements["smtp-connection-status"].textContent = "Testing encrypted SMTP delivery…";
  try {
    const response = await api("/v1/email-connections/smtp", jsonRequest(payload));
    if (!response.ok) {
      elements["smtp-connection-status"].textContent = "SMTP relay was not saved.";
      return showError(response);
    }
    const result = await response.json();
    form.reset();
    elements["smtp-connection-dialog"].close();
    await loadEmailConnections();
    showNotice(
      `SMTP test delivery was accepted. ${result.connection?.isDefaultSender ? "It is now the default sending mailbox." : "Choose it as the default mailbox before sending."}`
    );
  } finally {
    form.elements.password.value = "";
    if (submit) submit.disabled = false;
  }
}

function handleCommerceViewNavigation(event) {
  const button = event.target.closest("[data-commerce-view-target]");
  if (!button) return;
  setCommerceView(button.dataset.commerceViewTarget);
}

function setCommerceView(view) {
  const next = commerceViews.has(view) ? view : "review";
  activeCommerceView = next;
  sessionStorage.setItem(commerceViewStorageKey, next);
  elements["commerce-view-navigation"]
    .querySelectorAll("[data-commerce-view-target]")
    .forEach((button) => {
      const selected = button.dataset.commerceViewTarget === next;
      button.setAttribute("aria-pressed", String(selected));
      button.classList.toggle("active", selected);
    });
  document.querySelectorAll("#integrations-workspace [data-commerce-view]").forEach((panel) => {
    panel.hidden = panel.dataset.commerceView !== next;
  });
  if (activeWorkspaceId === "integrations-workspace")
    buildWorkspaceSubnavigation(elements["integrations-workspace"]);
}

async function loadCatalogAutomation() {
  if (!identity?.activeOrganizationId) return;
  const [
    catalogResponse,
    inventoryResponse,
    locationsResponse,
    productsResponse,
    accountsResponse
  ] = await Promise.all([
    api("/v1/organizations/current/catalog?limit=200", {}, true),
    api("/v1/organizations/current/inventory-sync", {}, true),
    api("/v1/inventory/locations", {}, true),
    api("/v1/products", {}, true),
    api("/v1/accounts", {}, true)
  ]);
  if (catalogResponse.ok) externalCatalogProducts = (await catalogResponse.json()).products;
  else externalCatalogProducts = [];
  if (inventoryResponse.ok) inventorySyncState = await inventoryResponse.json();
  else inventorySyncState = { policies: [], operations: [], accountingEntriesCreated: 0 };
  if (locationsResponse.ok) inventoryLocations = (await locationsResponse.json()).locations;
  if (productsResponse.ok) products = (await productsResponse.json()).products;
  if (accountsResponse.ok) accounts = (await accountsResponse.json()).accounts;
  const availableVariantIds = new Set(catalogVariants().map(({ variant }) => variant.id));
  if (!selectedCatalogVariantId || !availableVariantIds.has(selectedCatalogVariantId))
    selectedCatalogVariantId = catalogVariants()[0]?.variant.id ?? null;
  renderCatalogReview();
  renderInventorySyncReview();
}

async function pollConnectorCatalog(event) {
  event?.preventDefault();
  const form = elements["catalog-poll-form"];
  const data = new FormData(form);
  const connectorId = data.get("connectorId");
  if (!connectorId) return showNotice("Select a connected store before importing products.", true);
  const submit = form.querySelector('button[type="submit"]');
  submit.disabled = true;
  elements["continue-catalog-poll"].disabled = true;
  elements["catalog-operation-status"].textContent =
    "Reading channel products and preserving their source identifiers...";
  try {
    const response = await api(
      `/v1/organizations/current/connectors/${connectorId}/catalog/poll`,
      jsonRequest({
        pageSize: Number(data.get("pageSize")),
        maxPages: Number(data.get("maxPages")),
        restart: false
      })
    );
    if (!response.ok) return showError(response);
    const result = (await response.json()).catalogSync;
    catalogPollHasMore = result.hasMore;
    elements["catalog-operation-status"].textContent =
      `Imported ${result.importedProducts} products and ${result.importedVariants} variations ` +
      `from ${formatConnectorStatus(result.providerKey)} across ${result.pages} page${result.pages === 1 ? "" : "s"}. ` +
      `${result.observations} exact quantity observation${result.observations === 1 ? "" : "s"} recorded. ` +
      (result.hasMore
        ? "More products remain; Continue import resumes from the saved provider cursor."
        : "The available product pages are complete.") +
      " Accounting entries created: 0.";
    await loadCatalogAutomation();
    showNotice(
      result.hasMore
        ? "Product evidence imported. Continue when ready; no books were changed."
        : "Product list imported without changing the books."
    );
  } finally {
    submit.disabled = false;
    elements["continue-catalog-poll"].disabled = !catalogPollHasMore;
  }
}

function continueCatalogPoll() {
  return pollConnectorCatalog();
}

function openProductSpreadsheetImport() {
  activateWorkspace("portability-workspace");
  elements["data-import-source-system"].value = "OTHER";
  elements["data-import-source-system"].dispatchEvent(new globalThis.Event("change"));
  elements["data-import-form"].elements.importType.value = "PRODUCTS";
  elements["data-import-form"].elements.importType.dispatchEvent(new globalThis.Event("change"));
  elements["data-import-form"].scrollIntoView({
    behavior: preferredScrollBehavior(),
    block: "start"
  });
  elements["data-import-form"].elements.file.focus({ preventScroll: true });
}

function catalogVariants() {
  return externalCatalogProducts.flatMap((product) =>
    (product.variants ?? []).map((variant) => ({ product, variant }))
  );
}

function selectedCatalogEntry() {
  return catalogVariants().find(({ variant }) => variant.id === selectedCatalogVariantId) ?? null;
}

function renderCatalogReview() {
  const variants = catalogVariants();
  const confirmed = variants.filter(({ variant }) =>
    (variant.candidates ?? []).some((candidate) => candidate.status === "CONFIRMED")
  ).length;
  const pendingImages = externalCatalogProducts
    .flatMap((product) => [
      ...(product.images ?? []),
      ...(product.variants ?? []).flatMap((variant) => variant.images ?? [])
    ])
    .filter((image) => ["OBSERVED", "APPROVED"].includes(image.status)).length;
  elements["catalog-review-summary"].replaceChildren(
    metric("Channel products", externalCatalogProducts.length),
    metric("Variations", variants.length),
    metric("Approved matches", confirmed),
    metric("Awaiting review", variants.length - confirmed + pendingImages)
  );
  const filter = elements["catalog-product-filter"].value.trim().toLowerCase();
  const matchingProducts = externalCatalogProducts.filter((product) => {
    if (!filter) return true;
    return [
      product.name,
      product.externalProductId,
      ...(product.variants ?? []).flatMap((variant) => [
        variant.name,
        variant.sku,
        variant.gtin,
        variant.manufacturerPartNumber
      ])
    ].some((value) =>
      String(value ?? "")
        .toLowerCase()
        .includes(filter)
    );
  });
  elements["catalog-product-list"].replaceChildren(
    ...(matchingProducts.length
      ? matchingProducts.map(renderCatalogProduct)
      : [
          commerceEmptyState(
            externalCatalogProducts.length
              ? "No products match this search"
              : "No products imported",
            externalCatalogProducts.length
              ? "Try a product name, SKU, barcode, or manufacturer part number."
              : "Choose a connected store above and import its product list, or use the spreadsheet mapper."
          )
        ])
  );
  renderCatalogSelection();
}

function renderCatalogProduct(product) {
  const article = document.createElement("article");
  article.className = "commerce-catalog-product";
  article.setAttribute("role", "listitem");
  const header = document.createElement("header");
  const heading = document.createElement("h4");
  heading.textContent = product.name;
  const source = document.createElement("p");
  const connector = connectorInstallations.find((item) => item.id === product.installationId);
  source.textContent = `${connector?.displayName ?? "Connected store"} / source ${product.externalProductId}`;
  header.append(heading, source);
  const list = document.createElement("div");
  list.className = "commerce-catalog-variants";
  for (const variant of product.variants ?? []) {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "commerce-catalog-variant";
    button.dataset.catalogVariantId = variant.id;
    button.setAttribute("aria-pressed", String(variant.id === selectedCatalogVariantId));
    const copy = document.createElement("span");
    copy.className = "commerce-variant-copy";
    const name = document.createElement("strong");
    name.textContent = variant.name;
    const identifiers = document.createElement("small");
    identifiers.textContent = variant.sku ? `SKU ${variant.sku}` : "No channel SKU";
    copy.append(name, identifiers);
    const state = document.createElement("span");
    const approved = (variant.candidates ?? []).some(
      (candidate) => candidate.status === "CONFIRMED"
    );
    state.className = `mapping-authority ${approved ? "is-approved" : "is-proposed"}`;
    state.textContent = approved ? "Approved" : "Review";
    button.append(copy, state);
    list.append(button);
  }
  article.append(header, list);
  return article;
}

function selectCatalogVariant(event) {
  const button = event.target.closest("[data-catalog-variant-id]");
  if (!button) return;
  selectedCatalogVariantId = button.dataset.catalogVariantId;
  renderCatalogReview();
}

function renderCatalogSelection() {
  const container = elements["catalog-selection"];
  const entry = selectedCatalogEntry();
  if (!entry) {
    container.replaceChildren(
      commerceEmptyState(
        "Select a channel product",
        "PennyWise Accounting keeps imported product facts separate from approved item mappings."
      )
    );
    return;
  }
  const { product, variant } = entry;
  const confirmed = (variant.candidates ?? []).find(
    (candidate) => candidate.status === "CONFIRMED"
  );
  const heading = document.createElement("div");
  heading.className = "catalog-detail-heading";
  const titleBlock = document.createElement("div");
  const authority = document.createElement("span");
  authority.className = `mapping-authority ${confirmed ? "is-approved" : "is-proposed"}`;
  authority.textContent = confirmed ? "Approved item mapping" : "Proposed evidence only";
  const title = document.createElement("h3");
  title.id = "catalog-selection-heading";
  title.textContent = variant.name;
  const subtitle = document.createElement("p");
  subtitle.textContent = `${product.name} / source variation ${variant.externalVariantId}`;
  titleBlock.append(authority, title, subtitle);
  const actions = document.createElement("div");
  actions.className = "form-actions";
  const suggest = document.createElement("button");
  suggest.type = "button";
  suggest.className = "secondary-command";
  suggest.dataset.catalogAction = "suggest";
  suggest.textContent = "Find possible matches";
  const create = document.createElement("button");
  create.type = "button";
  create.dataset.catalogAction = "create";
  create.textContent = "Create a new item";
  actions.append(suggest, create);
  heading.append(titleBlock, actions);

  const facts = document.createElement("dl");
  facts.className = "catalog-facts";
  for (const [label, value] of [
    ["Channel SKU", variant.sku || "Not provided"],
    ["Barcode / GTIN", variant.gtin || "Not provided"],
    ["Manufacturer", variant.manufacturer || "Not provided"],
    ["Part number", variant.manufacturerPartNumber || "Not provided"]
  ])
    facts.append(descriptionItem(label, value));

  const matches = document.createElement("section");
  matches.className = "catalog-match-review";
  const matchHeading = document.createElement("div");
  matchHeading.className = "catalog-subheading";
  const matchTitle = document.createElement("h4");
  matchTitle.textContent = "Possible PennyWise Accounting items";
  const matchDescription = document.createElement("p");
  matchDescription.textContent = confirmed
    ? `Approved: ${confirmed.productItem?.sku ?? "No SKU"} / ${confirmed.productItem?.name ?? "PennyWise Accounting item"}`
    : "Scores explain similarity only. Every match requires your approval.";
  matchHeading.append(matchTitle, matchDescription);
  const candidateList = document.createElement("div");
  candidateList.className = "catalog-candidate-list";
  candidateList.replaceChildren(
    ...((variant.candidates ?? []).length
      ? variant.candidates.map((candidate) =>
          renderCatalogCandidate(candidate, Boolean(confirmed), product.installationId, variant.sku)
        )
      : [
          commerceEmptyState(
            "No suggestions yet",
            "Choose Find possible matches to compare SKUs, barcodes, manufacturer parts, names, and descriptions."
          )
        ])
  );
  matches.append(matchHeading, candidateList);

  const patternDetails = document.createElement("details");
  patternDetails.className = "catalog-pattern-editor";
  const patternSummary = document.createElement("summary");
  patternSummary.textContent = "Remember a safe prefix or suffix SKU pattern";
  const patternCopy = document.createElement("p");
  patternCopy.textContent =
    "Use anchored text only. PennyWise Accounting previews existing rows and blocks collisions before enabling the rule.";
  const patternForm = document.createElement("form");
  patternForm.className = "form-grid compact-form";
  const patternName = document.createElement("input");
  patternName.name = "name";
  patternName.placeholder = "Rule name";
  patternName.required = true;
  const prefix = document.createElement("input");
  prefix.name = "prefix";
  prefix.placeholder = "Prefix, e.g. AMZ-";
  const suffix = document.createElement("input");
  suffix.name = "suffix";
  suffix.placeholder = "Suffix, e.g. -FBA";
  const patternActions = document.createElement("div");
  patternActions.className = "form-actions";
  const savePattern = document.createElement("button");
  savePattern.type = "submit";
  savePattern.dataset.catalogPatternAction = "approve";
  savePattern.textContent = "Preview & approve pattern";
  patternActions.append(savePattern);
  patternForm.append(
    labeledControl("Name", patternName),
    labeledControl("Prefix", prefix),
    labeledControl("Suffix", suffix),
    patternActions
  );
  patternDetails.append(patternSummary, patternCopy, patternForm);

  const imageReview = renderCatalogImages(product, variant);
  container.replaceChildren(heading, facts, matches, patternDetails, imageReview);
}

function labeledControl(label, control) {
  const wrapper = document.createElement("label");
  wrapper.append(document.createTextNode(label), control);
  return wrapper;
}

function renderCatalogCandidate(candidate, hasConfirmedCandidate, installationId, sourceSku) {
  const article = document.createElement("article");
  article.className = `catalog-candidate ${candidate.status === "CONFIRMED" ? "is-approved" : ""}`;
  const main = document.createElement("div");
  const heading = document.createElement("div");
  heading.className = "catalog-candidate-heading";
  const name = document.createElement("strong");
  name.textContent = `${candidate.productItem?.sku ?? "No SKU"} / ${candidate.productItem?.name ?? "PennyWise Accounting item"}`;
  const status = document.createElement("span");
  status.className = `mapping-authority ${candidate.status === "CONFIRMED" ? "is-approved" : "is-proposed"}`;
  status.textContent = formatConnectorStatus(candidate.status);
  heading.append(name, status);
  const confidence = Math.max(0, Math.min(100, Number(candidate.score ?? 0) / 1000));
  const meterLabel = document.createElement("label");
  meterLabel.className = "candidate-confidence";
  meterLabel.textContent = `${confidence.toFixed(confidence % 1 ? 1 : 0)}% evidence match`;
  const meter = document.createElement("progress");
  meter.max = 100;
  meter.value = confidence;
  meterLabel.append(meter);
  const reasons = document.createElement("ul");
  reasons.className = "candidate-reasons";
  for (const reason of catalogReasonCodes(candidate.reason)) {
    const item = document.createElement("li");
    item.textContent = catalogMatchReason(reason, candidate.reason);
    reasons.append(item);
  }
  if (!reasons.childElementCount) {
    const item = document.createElement("li");
    item.textContent = "Ranked by nearest-field evidence; no exact identifier evidence.";
    reasons.append(item);
  }
  const similarity = renderCatalogSimilarityEvidence(candidate.reason);
  main.append(heading, meterLabel, reasons, similarity);
  const actions = document.createElement("div");
  actions.className = "catalog-candidate-actions";
  if (candidate.status === "CONFIRMED") {
    const reject = document.createElement("button");
    reject.type = "button";
    reject.className = "secondary-command";
    reject.dataset.catalogCandidateAction = "reject";
    reject.dataset.candidateId = candidate.id;
    reject.textContent = "Remove approval";
    actions.append(reject);
  } else {
    const approve = document.createElement("button");
    approve.type = "button";
    approve.dataset.catalogCandidateAction = "confirm";
    approve.dataset.candidateId = candidate.id;
    approve.textContent = "Approve this match";
    approve.disabled = hasConfirmedCandidate;
    if (hasConfirmedCandidate)
      approve.title = "Remove the current approved match before approving another one.";
    actions.append(approve);
    if (sourceSku && installationId) {
      const remember = document.createElement("button");
      remember.type = "button";
      remember.className = "secondary-command";
      remember.dataset.catalogCandidateAction = "alias";
      remember.dataset.candidateId = candidate.id;
      remember.textContent = "Approve & remember SKU";
      remember.disabled = hasConfirmedCandidate;
      actions.append(remember);
    }
  }
  if (installationId) article.dataset.installationId = installationId;
  if (sourceSku) article.dataset.sourceSku = sourceSku;
  article.append(main, actions);
  return article;
}

function catalogReasonCodes(evidence = {}) {
  const values = Array.isArray(evidence.codes)
    ? evidence.codes
    : Array.isArray(evidence.matches)
      ? evidence.matches
      : [];
  return [...new Set(values.filter((value) => typeof value === "string" && value.trim()))];
}

function catalogMatchReason(reason, evidence = {}) {
  if (reason === "EXACT_GTIN") return "Exact barcode / GTIN";
  if (reason === "EXACT_MANUFACTURER_PART_NUMBER") return "Exact manufacturer and part number";
  if (reason === "NORMALIZED_SKU") return "Same SKU after case and spacing cleanup";
  if (reason === "EXPLICIT_LOCAL_PRODUCT_CREATION") return "Created from this channel variation";
  if (reason === "SKU_SIMILARITY")
    return `Nearest SKU evidence (${formatSimilarityBasisPoints(evidence.skuSimilarityBasisPoints)})`;
  if (reason === "NAME_SIMILARITY")
    return `Nearest name evidence (${formatSimilarityBasisPoints(evidence.nameSimilarityBasisPoints)})`;
  if (reason === "DESCRIPTION_SIMILARITY")
    return `Nearest description evidence (${formatSimilarityBasisPoints(evidence.descriptionSimilarityBasisPoints)})`;
  if (reason === "NAME_SIMILARITY_ONLY")
    return `Nearest name only (${formatSimilarityBasisPoints(evidence.nameSimilarityBasisPoints)}) - verify carefully`;
  return formatConnectorStatus(reason);
}

function renderCatalogSimilarityEvidence(evidence = {}) {
  const section = document.createElement("section");
  section.className = "candidate-similarity-evidence";
  const title = document.createElement("h5");
  title.textContent = `Nearest-field evidence · reason v${Number.isInteger(evidence.version) ? evidence.version : "unknown"}`;
  const description = document.createElement("p");
  description.textContent =
    "The composite ranks separate identifier, SKU, name, and description evidence. Fuzzy evidence never approves or links an item.";
  const state = document.createElement("p");
  state.className = `catalog-decision-state is-${String(evidence.decisionState ?? "unknown").toLowerCase()}`;
  const stateLabel = evidence.decisionState ?? "UNKNOWN";
  const margin = formatSimilarityBasisPoints(evidence.suggestionMarginBasisPoints);
  state.textContent =
    stateLabel === "AUTO_MATCH_CANDIDATE"
      ? "Deterministic candidate — review and explicitly approve before posting."
      : stateLabel === "AMBIGUOUS"
        ? `Ambiguous candidate — competing evidence is too close (margin ${margin}).`
        : stateLabel === "UNMATCHED"
          ? "No useful candidate was found."
          : "Suggested candidate — verify the source identity before approving.";
  if (evidence.matchMethod === "APPROVED_ALIAS" || evidence.matchMethod === "APPROVED_PATTERN") {
    const method = document.createElement("p");
    method.className = "catalog-match-method";
    method.textContent =
      evidence.matchMethod === "APPROVED_ALIAS"
        ? "Approved source SKU alias matched exactly."
        : "Approved anchored SKU pattern extracted a base SKU.";
    section.append(method);
  }
  section.append(title, description, state);
  if (Array.isArray(evidence.matchedTokens) && evidence.matchedTokens.length) {
    const matched = document.createElement("p");
    matched.className = "catalog-matched-tokens";
    matched.textContent = `Matched words: ${evidence.matchedTokens.join(", ")}`;
    section.append(matched);
  }
  if (Array.isArray(evidence.conflicts) && evidence.conflicts.length) {
    const conflicts = document.createElement("p");
    conflicts.className = "catalog-match-conflicts";
    conflicts.textContent = `Conflicts requiring review: ${evidence.conflicts.join(", ")}`;
    section.append(conflicts);
  }
  const list = document.createElement("dl");
  list.className = "candidate-similarity-grid";
  for (const [label, value, explanation] of [
    [
      "Composite",
      evidence.compositeSimilarityBasisPoints,
      "Weighted ranking evidence; it is not an approval threshold."
    ],
    [
      "Nearest SKU",
      evidence.skuSimilarityBasisPoints,
      "Compares product codes after safe case and spacing cleanup."
    ],
    [
      "Nearest name",
      evidence.nameSimilarityBasisPoints,
      "Compares the channel and local item names."
    ],
    [
      "Nearest description",
      evidence.descriptionSimilarityBasisPoints,
      "Compares descriptive text only when both systems provide it."
    ]
  ]) {
    const row = document.createElement("div");
    const term = document.createElement("dt");
    term.textContent = label;
    const detail = document.createElement("dd");
    const score = document.createElement("strong");
    score.textContent = formatSimilarityBasisPoints(value);
    const note = document.createElement("span");
    note.textContent = explanation;
    detail.append(score, note);
    row.append(term, detail);
    list.append(row);
  }
  section.append(list);
  return section;
}

function formatSimilarityBasisPoints(value) {
  if (value === null || value === undefined || value === "") return "Not available";
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return "Not available";
  const percent = Math.max(0, Math.min(100, numeric / 100));
  return `${percent.toFixed(percent % 1 ? 1 : 0)}%`;
}

function renderCatalogImages(product, variant) {
  const section = document.createElement("section");
  section.className = "catalog-image-review";
  const heading = document.createElement("div");
  heading.className = "catalog-subheading";
  const title = document.createElement("h4");
  title.textContent = "Product image evidence";
  const description = document.createElement("p");
  description.textContent =
    "Approve a trusted provider source, then verify its file type, size, and dimensions. Images never decide an item match.";
  heading.append(title, description);
  const unique = new Map(
    [...(product.images ?? []), ...(variant.images ?? [])].map((image) => [image.id, image])
  );
  const list = document.createElement("div");
  list.className = "catalog-image-list";
  list.replaceChildren(
    ...(unique.size
      ? [...unique.values()].map(renderCatalogImage)
      : [commerceEmptyState("No image evidence", "This channel product did not provide an image.")])
  );
  section.append(heading, list);
  return section;
}

function renderCatalogImage(image) {
  const article = document.createElement("article");
  article.className = "catalog-image-item";
  const media = document.createElement("div");
  media.className = "catalog-image-frame";
  if (["APPROVED", "INGESTED"].includes(image.status)) {
    const preview = document.createElement("img");
    preview.src = image.remoteUrl;
    preview.alt = "Approved channel product preview";
    preview.loading = "lazy";
    preview.referrerPolicy = "no-referrer";
    media.append(preview);
  } else {
    const placeholder = document.createElement("span");
    placeholder.textContent = "Preview appears after source approval";
    media.append(placeholder);
  }
  const copy = document.createElement("div");
  const state = document.createElement("span");
  state.className = `mapping-authority ${image.status === "INGESTED" ? "is-approved" : "is-proposed"}`;
  state.textContent =
    image.status === "INGESTED" ? "Verified" : formatConnectorStatus(image.status);
  const dimensions = document.createElement("p");
  dimensions.textContent =
    image.width && image.height
      ? `${image.width} x ${image.height}${image.contentTypeHint ? ` / ${image.contentTypeHint}` : ""}`
      : "Dimensions not verified";
  const source = document.createElement("a");
  source.href = image.remoteUrl;
  source.target = "_blank";
  source.rel = "noopener noreferrer";
  source.textContent = "Open source image";
  copy.append(state, dimensions, source);
  const actions = document.createElement("div");
  actions.className = "catalog-image-actions";
  const addAction = (label, action, primary = false) => {
    const button = document.createElement("button");
    button.type = "button";
    if (!primary) button.className = "secondary-command";
    button.dataset.catalogImageAction = action;
    button.dataset.imageId = image.id;
    button.textContent = label;
    actions.append(button);
  };
  if (image.status === "OBSERVED") {
    addAction("Approve source", "approve", true);
    addAction("Reject", "reject");
  } else if (image.status === "APPROVED") {
    addAction("Verify image file", "ingest", true);
    addAction("Reject", "reject");
  }
  article.append(media, copy, actions);
  return article;
}

function commerceEmptyState(title, description) {
  const wrapper = document.createElement("div");
  wrapper.className = "commerce-empty-state";
  const heading = document.createElement("h4");
  heading.textContent = title;
  const copy = document.createElement("p");
  copy.textContent = description;
  wrapper.append(heading, copy);
  return wrapper;
}

function descriptionItem(label, value) {
  const wrapper = document.createElement("div");
  const term = document.createElement("dt");
  term.textContent = label;
  const detail = document.createElement("dd");
  detail.textContent = value;
  wrapper.append(term, detail);
  return wrapper;
}

async function handleCatalogReviewAction(event) {
  const actionButton = event.target.closest(
    "[data-catalog-action], [data-catalog-candidate-action], [data-catalog-image-action]"
  );
  if (!actionButton) return;
  const entry = selectedCatalogEntry();
  if (!entry) return;
  if (actionButton.dataset.catalogAction === "suggest")
    return suggestCatalogCandidates(entry.variant.id);
  if (actionButton.dataset.catalogAction === "create") return openCatalogProductDialog(entry);
  if (actionButton.dataset.catalogCandidateAction) {
    const candidate = (entry.variant.candidates ?? []).find(
      (item) => item.id === actionButton.dataset.candidateId
    );
    if (!candidate) return;
    const action = actionButton.dataset.catalogCandidateAction;
    const approvalMessage =
      action === "confirm" || action === "alias"
        ? `Approve ${candidate.productItem?.sku ?? "this item"} / ${candidate.productItem?.name ?? "PennyWise Accounting item"} as the match for ${entry.variant.name}?`
        : `Remove the approved match between ${entry.variant.name} and ${candidate.productItem?.name ?? "this item"}?`;
    if (!window.confirm(approvalMessage)) return;
    if (action === "alias") {
      const confirmed = await api(
        `/v1/organizations/current/catalog/candidates/${candidate.id}/confirm`,
        jsonRequest({
          version: candidate.version,
          reason: "Approved in visual catalog review and saved as a source SKU alias."
        })
      );
      if (!confirmed.ok) return handleCatalogAutomationError(confirmed);
      const alias = await api(
        `/v1/organizations/current/connectors/${entry.product.installationId}/catalog/sku-aliases`,
        jsonRequest(
          {
            sourceSku: entry.variant.sku,
            productItemId: candidate.productItem.id,
            reason: "Approved from the catalog match review."
          },
          "POST"
        )
      );
      if (!alias.ok) return handleCatalogAutomationError(alias);
      await loadCatalogAutomation();
      showNotice("Item match approved and this source SKU was saved as a durable alias.");
      return;
    }
    const response = await api(
      `/v1/organizations/current/catalog/candidates/${candidate.id}/${action}`,
      jsonRequest({
        version: candidate.version,
        reason:
          action === "confirm"
            ? "Approved in the visual catalog review after comparing source identifiers."
            : "Approval removed in the visual catalog review."
      })
    );
    if (!response.ok) return handleCatalogAutomationError(response);
    await loadCatalogAutomation();
    showNotice(
      action === "confirm"
        ? "Item match approved. Inventory automation remains off until you configure a rule."
        : "Item match approval removed. Existing inventory rules may require review."
    );
    return;
  }
  const image = [...(entry.product.images ?? []), ...(entry.variant.images ?? [])].find(
    (item) => item.id === actionButton.dataset.imageId
  );
  if (!image) return;
  const action = actionButton.dataset.catalogImageAction;
  if (
    action === "approve" &&
    !window.confirm(
      "Approve this provider-hosted image source for a preview? This does not attach it to an item."
    )
  )
    return;
  const response = await api(
    `/v1/organizations/current/catalog/images/${image.id}/${action}`,
    jsonRequest({
      version: image.version,
      ...(action === "reject" ? { reason: "Rejected during product image review." } : {})
    })
  );
  if (!response.ok) return handleCatalogAutomationError(response);
  await loadCatalogAutomation();
  showNotice(
    action === "approve"
      ? "Image source approved. Verify its file before using the reference."
      : action === "ingest"
        ? "Image file verified for type, size, dimensions, and evidence hash."
        : "Image evidence rejected."
  );
}

async function handleCatalogPatternAction(event) {
  const form = event.target.closest("form");
  if (!form?.querySelector("[data-catalog-pattern-action]")) return;
  event.preventDefault();
  const entry = selectedCatalogEntry();
  if (!entry?.product.installationId || !entry.variant.sku) return;
  const data = new FormData(form);
  const prefix = String(data.get("prefix") ?? "").trim();
  const suffix = String(data.get("suffix") ?? "").trim();
  if (!prefix && !suffix)
    return showNotice("Enter a prefix or suffix before saving the rule.", true);
  const response = await api(
    `/v1/organizations/current/connectors/${entry.product.installationId}/catalog/sku-patterns`,
    jsonRequest({
      name: String(data.get("name") ?? "").trim(),
      ...(prefix ? { prefix } : {}),
      ...(suffix ? { suffix } : {}),
      examples: [entry.variant.sku],
      reason: "Approved from the catalog match review."
    })
  );
  if (!response.ok) return handleCatalogAutomationError(response);
  await loadCatalogAutomation();
  showNotice(
    "Pattern preview passed. The source-scoped SKU rule is now available for review matches."
  );
}

async function suggestCatalogCandidates(catalogVariantId) {
  const response = await api(
    `/v1/organizations/current/catalog/variants/${catalogVariantId}/candidates`,
    jsonRequest({ limit: 25 })
  );
  if (!response.ok) return handleCatalogAutomationError(response);
  const candidates = (await response.json()).candidates;
  await loadCatalogAutomation();
  showNotice(
    candidates.length
      ? `${candidates.length} possible item match${candidates.length === 1 ? "" : "es"} found. Review the evidence before approving one.`
      : "No useful item matches were found. Create a new PennyWise Accounting item or import a product spreadsheet."
  );
}

async function handleCatalogAutomationError(response) {
  const stale = response.status === 409;
  await showError(response);
  if (stale) {
    await loadCatalogAutomation();
    elements["catalog-operation-status"].textContent =
      "The review changed in another session. Current catalog and inventory evidence has been reloaded.";
  }
}

function openCatalogProductDialog(entry) {
  const form = elements["catalog-product-form"];
  const accountGroups = catalogProductAccountGroups();
  const missingAccount = Object.values(accountGroups).some(
    (types) =>
      !accounts.some((item) => types.includes(item.type) && !item.isControl && !item.isArchived)
  );
  if (missingAccount || !inventoryLocations.some((location) => location.isActive)) {
    showNotice(
      "Set up the required inventory accounts and at least one active location before creating this item.",
      true
    );
    activateWorkspace("inventory-workspace");
    elements["inventory-product-form"].scrollIntoView({
      behavior: preferredScrollBehavior(),
      block: "start"
    });
    return;
  }
  form.reset();
  form.dataset.catalogVariantId = entry.variant.id;
  form.elements.sku.value = entry.variant.sku ?? "";
  form.elements.name.value = entry.variant.name;
  for (const [field, types] of Object.entries(accountGroups))
    form.elements[field].replaceChildren(
      ...accounts
        .filter((item) => types.includes(item.type) && !item.isControl && !item.isArchived)
        .map((item) => option(item.id, `${item.code} ${item.name}`))
    );
  form.elements.defaultLocationId.replaceChildren(
    ...inventoryLocations
      .filter((location) => location.isActive)
      .map((location) => option(location.id, `${location.code} ${location.name}`))
  );
  const verifiedImages = new Map(
    [...(entry.product.images ?? []), ...(entry.variant.images ?? [])]
      .filter((image) => image.status === "INGESTED")
      .map((image) => [image.id, image])
  );
  form.elements.productImageReference.replaceChildren(
    option("", "Do not attach an image reference"),
    ...[...verifiedImages.values()].map((image, index) =>
      option(image.remoteUrl, `Verified channel image ${index + 1}`)
    )
  );
  elements["catalog-product-dialog"].showModal();
  form.elements.sku.focus();
}

function catalogBulkEligibleVariants() {
  return catalogVariants().filter(
    ({ variant }) =>
      !(variant.candidates ?? []).some((candidate) => candidate.status === "CONFIRMED")
  );
}

function openCatalogBulkProductDialog() {
  const form = elements["catalog-bulk-product-form"];
  const accountGroups = catalogProductAccountGroups();
  const missingAccount = Object.values(accountGroups).some(
    (types) =>
      !accounts.some((item) => types.includes(item.type) && !item.isControl && !item.isArchived)
  );
  if (missingAccount || !inventoryLocations.some((location) => location.isActive)) {
    showNotice(
      "Set up the required inventory accounts and at least one active location before creating channel items.",
      true
    );
    activateWorkspace("inventory-workspace");
    elements["inventory-product-form"].scrollIntoView({
      behavior: preferredScrollBehavior(),
      block: "start"
    });
    return;
  }
  const candidates = catalogBulkEligibleVariants();
  if (!candidates.length)
    return showNotice(
      "Every imported channel variation already has an approved item mapping.",
      true
    );
  const visibleCandidates = candidates.slice(0, 100);
  form.reset();
  for (const [field, types] of Object.entries(accountGroups))
    form.elements[field].replaceChildren(
      ...accounts
        .filter((item) => types.includes(item.type) && !item.isControl && !item.isArchived)
        .map((item) => option(item.id, `${item.code} ${item.name}`))
    );
  form.elements.defaultLocationId.replaceChildren(
    ...inventoryLocations
      .filter((location) => location.isActive)
      .map((location) => option(location.id, `${location.code} ${location.name}`))
  );
  const selection = elements["catalog-bulk-product-selection"];
  selection.replaceChildren(...visibleCandidates.map(renderCatalogBulkSelectionRow));
  elements["catalog-bulk-product-summary"].textContent =
    candidates.length > visibleCandidates.length
      ? `${candidates.length} unmatched variations are available. Select from the first ${visibleCandidates.length}; refresh or narrow the imported catalog before the next batch.`
      : `${candidates.length} unmatched channel variation${candidates.length === 1 ? " is" : "s are"} ready for deliberate creation.`;
  form.elements.attachFirstIngestedImage.checked = true;
  form.elements.confirmMappings.checked = false;
  renderCatalogBulkCreateSelectionSummary();
  elements["catalog-bulk-product-dialog"].showModal();
  form.elements.salesPriceMinor.focus();
}

function renderCatalogBulkSelectionRow(entry) {
  const label = document.createElement("label");
  label.className = "checkbox-row catalog-bulk-selection-row";
  const input = document.createElement("input");
  input.type = "checkbox";
  input.name = "catalogVariantIds";
  input.value = entry.variant.id;
  input.checked = true;
  const copy = document.createElement("span");
  const name = document.createElement("strong");
  name.textContent = entry.variant.name;
  const source = document.createElement("small");
  source.textContent = `${entry.product.name} · ${entry.variant.sku ? `SKU ${entry.variant.sku}` : "No channel SKU"}`;
  copy.append(name, source);
  label.append(input, copy);
  return label;
}

function renderCatalogBulkCreateSelectionSummary() {
  const form = elements["catalog-bulk-product-form"];
  const selected = new FormData(form).getAll("catalogVariantIds").length;
  const submit = form.querySelector('button[type="submit"]');
  submit.disabled = selected === 0;
  submit.textContent = selected
    ? `Create ${selected} selected item${selected === 1 ? "" : "s"}`
    : "Select at least one item";
}

async function createProductsFromCatalogBulk(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const data = new FormData(form);
  const catalogVariantIds = data.getAll("catalogVariantIds").map((value) => String(value));
  if (!catalogVariantIds.length) return showNotice("Select at least one channel variation.", true);
  let salesPriceMinor;
  let reorderPointMicros;
  try {
    salesPriceMinor = parseMoneyInput(data.get("salesPriceMinor"));
    reorderPointMicros = quantityToMicros(data.get("reorderPoint"));
  } catch (error) {
    return showNotice(
      error instanceof Error ? error.message : "Enter valid item amounts before creating products.",
      true
    );
  }
  const confirmMappings = data.get("confirmMappings") === "on";
  const confirmation = confirmMappings
    ? `Create ${catalogVariantIds.length} inventory item${catalogVariantIds.length === 1 ? "" : "s"} and explicitly approve each selected source mapping? No stock or accounting entries will be created.`
    : `Create ${catalogVariantIds.length} inventory item${catalogVariantIds.length === 1 ? "" : "s"}? Their source mappings will remain in review and no stock or accounting entries will be created.`;
  if (!window.confirm(confirmation)) return;
  const submit = form.querySelector('button[type="submit"]');
  submit.disabled = true;
  try {
    const response = await api(
      "/v1/organizations/current/catalog/bulk-create-local-products",
      jsonRequest({
        catalogVariantIds,
        itemType: "INVENTORY_PRODUCT",
        salesPriceMinor,
        incomeAccountId: data.get("incomeAccountId"),
        inventoryAssetAccountId: data.get("inventoryAssetAccountId"),
        costOfGoodsSoldAccountId: data.get("costOfGoodsSoldAccountId"),
        purchaseClearingAccountId: data.get("purchaseClearingAccountId"),
        adjustmentGainAccountId: data.get("adjustmentGainAccountId"),
        inventoryLossAccountId: data.get("inventoryLossAccountId"),
        defaultLocationId: data.get("defaultLocationId"),
        reorderPointMicros,
        unitOfMeasure: "each",
        attachFirstIngestedImage: data.get("attachFirstIngestedImage") === "on",
        confirmMappings
      })
    );
    if (!response.ok) return handleCatalogAutomationError(response);
    const result = (await response.json()).bulkCreate;
    const summary = result.summary;
    await loadCatalogAutomation();
    elements["catalog-bulk-product-dialog"].close();
    elements["catalog-operation-status"].textContent =
      `Created ${summary.created}; already created ${summary.alreadyCreated}; already mapped ${summary.alreadyMapped}; ` +
      `needs review ${summary.reviewRequired}; not created ${summary.notCreated}. ` +
      "Inventory movements and accounting entries created: 0.";
    showNotice(
      summary.notCreated || summary.reviewRequired
        ? "Channel-item creation finished with rows requiring review. See the catalog status for the count."
        : "Selected channel items are ready. Establish quantity only through a reviewed inventory workflow."
    );
  } finally {
    renderCatalogBulkCreateSelectionSummary();
  }
}

function catalogProductAccountGroups() {
  return {
    incomeAccountId: ["REVENUE", "CONTRA_REVENUE"],
    inventoryAssetAccountId: ["ASSET"],
    costOfGoodsSoldAccountId: ["EXPENSE"],
    purchaseClearingAccountId: ["ASSET"],
    adjustmentGainAccountId: ["REVENUE", "CONTRA_REVENUE"],
    inventoryLossAccountId: ["EXPENSE"]
  };
}

async function createProductFromCatalog(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const catalogVariantId = form.dataset.catalogVariantId;
  if (!catalogVariantId) return showNotice("Select a channel product first.", true);
  const data = new FormData(form);
  let salesPriceMinor;
  let reorderPointMicros;
  try {
    salesPriceMinor = parseMoneyInput(data.get("salesPriceMinor"));
    reorderPointMicros = quantityToMicros(data.get("reorderPoint"));
  } catch (error) {
    return showNotice(
      error instanceof Error ? error.message : "Enter valid product amounts.",
      true
    );
  }
  const imageReference = String(data.get("productImageReference") ?? "").trim();
  const response = await api(
    `/v1/organizations/current/catalog/variants/${catalogVariantId}/create-local-product`,
    jsonRequest({
      sku: data.get("sku"),
      name: data.get("name"),
      itemType: "INVENTORY_PRODUCT",
      salesPriceMinor,
      incomeAccountId: data.get("incomeAccountId"),
      inventoryAssetAccountId: data.get("inventoryAssetAccountId"),
      costOfGoodsSoldAccountId: data.get("costOfGoodsSoldAccountId"),
      purchaseClearingAccountId: data.get("purchaseClearingAccountId"),
      adjustmentGainAccountId: data.get("adjustmentGainAccountId"),
      inventoryLossAccountId: data.get("inventoryLossAccountId"),
      defaultLocationId: data.get("defaultLocationId"),
      reorderPointMicros,
      unitOfMeasure: "each",
      ...(imageReference ? { productImageReference: imageReference } : {})
    })
  );
  if (!response.ok) return handleCatalogAutomationError(response);
  elements["catalog-product-dialog"].close();
  await loadCatalogAutomation();
  showNotice(
    "PennyWise Accounting item created. Its suggested channel match is visible now and still requires your approval."
  );
}

function approvedCatalogVariants() {
  return catalogVariants().flatMap(({ product, variant }) => {
    const candidate = (variant.candidates ?? []).find((item) => item.status === "CONFIRMED");
    const localProduct = candidate
      ? products.find((item) => item.id === candidate.productItemId)
      : null;
    return candidate && localProduct?.itemType === "INVENTORY_PRODUCT"
      ? [{ product, variant, candidate }]
      : [];
  });
}

function renderInventorySyncReview() {
  const policies = inventorySyncState.policies ?? [];
  const operations = inventorySyncState.operations ?? [];
  const conflicts = policies.flatMap((policy) =>
    (policy.conflicts ?? []).map((conflict) => ({ policy, conflict }))
  );
  elements["inventory-sync-summary"].replaceChildren(
    metric("Approved item matches", approvedCatalogVariants().length),
    metric("Saved rules", policies.length),
    metric("Automation enabled", policies.filter((policy) => policy.enabled).length),
    metric(
      "Open differences",
      conflicts.filter(({ conflict }) => conflict.status === "OPEN").length
    )
  );
  renderInventoryPolicyOptions();
  elements["inventory-sync-policies"].replaceChildren(
    ...(policies.length
      ? policies.map(renderInventoryPolicyRow)
      : [
          row([
            "No saved rules",
            "Approve a catalog match first",
            "Not available",
            "Manual review",
            "Off",
            "Not available",
            "Not available"
          ])
        ])
  );
  const statusFilter = elements["inventory-conflict-filter"].value;
  const visibleConflicts = conflicts.filter(
    ({ conflict }) => !statusFilter || conflict.status === statusFilter
  );
  elements["inventory-sync-conflicts"].replaceChildren(
    ...(visibleConflicts.length
      ? visibleConflicts.map(({ policy, conflict }) => renderInventoryConflictRow(policy, conflict))
      : [
          row([
            statusFilter === "OPEN" ? "No open quantity differences" : "No matching differences",
            "Not available",
            "Not available",
            "Not available",
            "Not available",
            "Not available",
            "Not available"
          ])
        ])
  );
  elements["inventory-sync-operations"].replaceChildren(
    ...(operations.length
      ? operations.map(renderInventoryOperationRow)
      : [row(["No queued provider updates", "Not available", "Not available", "Not available"])])
  );
}

function renderInventoryPolicyOptions() {
  const form = elements["inventory-sync-policy-form"];
  const variantSelect = form.elements.catalogVariantId;
  const locationSelect = form.elements.locationId;
  const previousVariant = variantSelect.value;
  const previousLocation = locationSelect.value;
  const approved = approvedCatalogVariants();
  variantSelect.replaceChildren(
    option("", approved.length ? "Select an approved item" : "Approve a catalog match first"),
    ...approved.map(({ product, variant, candidate }) => {
      const connector = connectorInstallations.find((item) => item.id === product.installationId);
      return option(
        variant.id,
        `${connector?.displayName ?? "Channel"} / ${variant.sku ?? variant.name} to ${candidate.productItem?.sku ?? candidate.productItem?.name ?? "PennyWise Accounting item"}`
      );
    })
  );
  locationSelect.replaceChildren(
    option("", "Select a location"),
    ...inventoryLocations
      .filter((location) => location.isActive)
      .map((location) => option(location.id, `${location.code} ${location.name}`))
  );
  if (approved.some(({ variant }) => variant.id === previousVariant))
    variantSelect.value = previousVariant;
  else if (approved.length === 1) variantSelect.value = approved[0].variant.id;
  if (inventoryLocations.some((location) => location.isActive && location.id === previousLocation))
    locationSelect.value = previousLocation;
  else {
    const defaultLocation = inventoryLocations.find(
      (location) => location.isActive && location.isDefault
    );
    if (defaultLocation) locationSelect.value = defaultLocation.id;
  }
  fillExistingInventoryPolicy();
}

function renderInventoryPolicyMapping() {
  const form = elements["inventory-sync-policy-form"];
  const approved = approvedCatalogVariants().find(
    ({ variant }) => variant.id === form.elements.catalogVariantId.value
  );
  elements["inventory-policy-mapping-summary"].textContent = approved
    ? `${approved.variant.sku ?? approved.variant.name} from the channel is approved as ${approved.candidate.productItem?.sku ?? "No SKU"} / ${approved.candidate.productItem?.name ?? "PennyWise Accounting item"}.`
    : "Approve a catalog match before configuring inventory.";
  fillExistingInventoryPolicy();
}

function fillExistingInventoryPolicy() {
  const form = elements["inventory-sync-policy-form"];
  const variantId = form.elements.catalogVariantId.value;
  const locationId = form.elements.locationId.value;
  const policy = (inventorySyncState.policies ?? []).find(
    (item) => item.catalogVariantId === variantId && item.locationId === locationId
  );
  form.elements.version.value = policy?.version ?? "";
  form.elements.sourceOfTruth.value = policy?.sourceOfTruth ?? "MANUAL_REVIEW";
  form.elements.desiredQuantity.value =
    policy?.desiredQuantityMicros === null || policy?.desiredQuantityMicros === undefined
      ? ""
      : formatQuantityMicros(policy.desiredQuantityMicros);
  form.elements.enabled.checked = Boolean(policy?.enabled);
  form.elements.approval.checked = false;
  renderInventoryPolicyEffect();
}

function inventoryChannelAuthorityLabel(installation) {
  if (installation?.providerKey === "WOOCOMMERCE") return "This WooCommerce store authoritative";
  if (installation?.providerKey === "ETSY") return "This Etsy shop authoritative";
  return "This sales channel authoritative";
}

function selectedInventoryInstallation() {
  const form = elements["inventory-sync-policy-form"];
  const approved = approvedCatalogVariants().find(
    ({ variant }) => variant.id === form.elements.catalogVariantId.value
  );
  return connectorInstallations.find((item) => item.id === approved?.product.installationId);
}

function renderInventoryAuthorityOptions() {
  const form = elements["inventory-sync-policy-form"];
  const installation = selectedInventoryInstallation();
  form.elements.sourceOfTruth.querySelector('[value="LOCAL"]').textContent =
    "PennyWise authoritative";
  form.elements.sourceOfTruth.querySelector('[value="CHANNEL"]').textContent =
    inventoryChannelAuthorityLabel(installation);
}

function renderInventoryPolicyEffect() {
  const form = elements["inventory-sync-policy-form"];
  const source = form.elements.sourceOfTruth.value;
  const enabled = form.elements.enabled;
  const scope = "Scope: this item + channel + inventory location.";
  const sharedPoolWarning = "Do not make two channels authoritative for one shared stock pool.";
  const channelAuthority = inventoryChannelAuthorityLabel(selectedInventoryInstallation());
  renderInventoryAuthorityOptions();
  if (source === "MANUAL_REVIEW") {
    enabled.checked = false;
    enabled.disabled = true;
  } else enabled.disabled = false;
  const approval = form.querySelector(".inventory-policy-approval");
  approval.hidden = !(enabled.checked && source !== "MANUAL_REVIEW");
  if (approval.hidden) form.elements.approval.checked = false;
  elements["inventory-policy-effect"].textContent =
    source === "LOCAL"
      ? enabled.checked
        ? `PennyWise authoritative. ${scope} A reviewed difference can queue its exact quantity to the channel; provider failures leave local inventory unchanged. ${sharedPoolWarning}`
        : `PennyWise authoritative, but automation remains off until you explicitly enable and approve it. ${scope} ${sharedPoolWarning}`
      : source === "CHANNEL"
        ? enabled.checked
          ? `${channelAuthority}. ${scope} Differences still stop for review; adopting one can create a dated local inventory adjustment and related accounting entry. ${sharedPoolWarning}`
          : `${channelAuthority}, but automation remains off until you explicitly enable and approve it. ${scope} ${sharedPoolWarning}`
        : `Manual review records exact observations and differences only. It cannot update the channel or create local inventory movements. ${scope} ${sharedPoolWarning}`;
}

function resetInventoryPolicyForm() {
  const form = elements["inventory-sync-policy-form"];
  form.reset();
  form.elements.version.value = "";
  renderInventoryPolicyOptions();
  elements["inventory-policy-status"].textContent = "";
}

async function saveInventorySyncPolicy(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const data = new FormData(form);
  const approved = approvedCatalogVariants().find(
    ({ variant }) => variant.id === data.get("catalogVariantId")
  );
  if (!approved) return showNotice("Choose an item with an approved catalog match.", true);
  const sourceOfTruth = data.get("sourceOfTruth");
  const enabled = sourceOfTruth === "MANUAL_REVIEW" ? false : data.get("enabled") === "on";
  if (enabled && data.get("approval") !== "on")
    return showNotice("Confirm the named quantity authority before enabling automation.", true);
  const quantityText = String(data.get("desiredQuantity") ?? "").trim();
  let desiredQuantityMicros = null;
  try {
    if (quantityText) desiredQuantityMicros = quantityToMicros(quantityText);
  } catch (error) {
    return showNotice(error instanceof Error ? error.message : "Enter a valid quantity.", true);
  }
  const version = String(data.get("version") ?? "").trim();
  const response = await api(
    "/v1/organizations/current/inventory-sync/policies",
    jsonRequest(
      {
        installationId: approved.product.installationId,
        catalogVariantId: approved.variant.id,
        productItemId: approved.candidate.productItemId,
        locationId: data.get("locationId"),
        sourceOfTruth,
        desiredQuantityMicros,
        enabled,
        ...(version ? { version: Number(version) } : {})
      },
      "PUT"
    )
  );
  if (!response.ok) return handleCatalogAutomationError(response);
  const policy = (await response.json()).policy;
  elements["inventory-policy-status"].textContent =
    `${inventoryAuthorityLabel(policy.sourceOfTruth, selectedInventoryInstallation())} saved for this item and location. ` +
    `Automation ${policy.enabled ? "enabled with explicit approval" : "off"}. Accounting entries created: 0.`;
  await loadCatalogAutomation();
  showNotice("Inventory rule saved. No quantity or accounting entry was changed.");
}

function renderInventoryPolicyRow(policy) {
  const automation = document.createElement("span");
  automation.className = `mapping-authority ${policy.enabled ? "is-approved" : "is-proposed"}`;
  automation.textContent = policy.enabled ? "Enabled" : "Off";
  const edit = document.createElement("button");
  edit.type = "button";
  edit.className = "secondary-command";
  edit.dataset.inventoryPolicyId = policy.id;
  edit.textContent = "Review rule";
  const latest = policy.observations?.[0];
  return row([
    `${policy.installation?.displayName ?? "Channel"}\n${policy.variant?.sku ?? policy.variant?.name ?? policy.variant?.product?.name ?? "Variation"}`,
    `${policy.productItem?.sku ?? "No SKU"}\n${policy.productItem?.name ?? "PennyWise Accounting item"}`,
    `${policy.location?.code ?? ""} ${policy.location?.name ?? ""}`.trim(),
    inventoryAuthorityLabel(policy.sourceOfTruth, policy.installation),
    automation,
    latest
      ? `${formatQuantityMicros(latest.observedQuantityMicros)} / ${formatConnectorTime(latest.observedAt)}`
      : "No observation yet",
    edit
  ]);
}

function editInventorySyncPolicy(event) {
  const button = event.target.closest("[data-inventory-policy-id]");
  if (!button) return;
  const policy = (inventorySyncState.policies ?? []).find(
    (item) => item.id === button.dataset.inventoryPolicyId
  );
  if (!policy) return;
  const form = elements["inventory-sync-policy-form"];
  form.elements.catalogVariantId.value = policy.catalogVariantId;
  form.elements.locationId.value = policy.locationId;
  fillExistingInventoryPolicy();
  form.scrollIntoView({ behavior: preferredScrollBehavior(), block: "center" });
  form.elements.sourceOfTruth.focus({ preventScroll: true });
}

function renderInventoryConflictRow(policy, conflict) {
  const action = document.createElement("button");
  action.type = "button";
  action.className = "secondary-command";
  action.dataset.inventoryConflictId = conflict.id;
  action.textContent = conflict.status === "OPEN" ? "Review difference" : "View evidence";
  const status = document.createElement("span");
  status.className = `mapping-authority ${conflict.status === "RESOLVED" ? "is-approved" : "is-proposed"}`;
  status.textContent = formatConnectorStatus(conflict.status);
  return row([
    `${policy.productItem?.sku ?? policy.variant?.sku ?? "Item"}\n${policy.location?.code ?? policy.location?.name ?? "Location"}`,
    formatQuantityMicros(conflict.observedQuantityMicros),
    formatQuantityMicros(conflict.desiredQuantityMicros),
    formatQuantityMicros(conflict.differenceMicros),
    inventoryAuthorityLabel(policy.sourceOfTruth, policy.installation),
    status,
    action
  ]);
}

function inventoryAuthorityLabel(sourceOfTruth, installation) {
  if (sourceOfTruth === "LOCAL") return "PennyWise authoritative";
  if (sourceOfTruth === "CHANNEL") return inventoryChannelAuthorityLabel(installation);
  return "Manual review";
}

function inventoryConflictEntry(conflictId) {
  for (const policy of inventorySyncState.policies ?? []) {
    const conflict = (policy.conflicts ?? []).find((item) => item.id === conflictId);
    if (conflict) return { policy, conflict };
  }
  return null;
}

function openInventoryConflictReview(event) {
  const button = event.target.closest("[data-inventory-conflict-id]");
  if (!button) return;
  const entry = inventoryConflictEntry(button.dataset.inventoryConflictId);
  if (!entry) return;
  activeInventoryConflict = entry;
  const { policy, conflict } = entry;
  const form = elements["inventory-conflict-form"];
  form.reset();
  elements["inventory-conflict-dialog-summary"].textContent =
    `${policy.productItem?.sku ?? policy.variant?.sku ?? "Item"} at ${policy.location?.code ?? policy.location?.name ?? "this location"}: ` +
    `channel ${formatQuantityMicros(conflict.observedQuantityMicros)}, expected ${formatQuantityMicros(conflict.desiredQuantityMicros)}, difference ${formatQuantityMicros(conflict.differenceMicros)}.`;
  const actions = [option("IGNORE", "Keep both systems unchanged and close this difference")];
  if (conflict.status === "OPEN" && policy.enabled && policy.sourceOfTruth === "LOCAL")
    actions.unshift(
      option("PUSH_LOCAL_TO_CHANNEL", "Send PennyWise Accounting quantity to the channel")
    );
  if (conflict.status === "OPEN" && policy.enabled && policy.sourceOfTruth === "CHANNEL")
    actions.unshift(
      option("ADOPT_CHANNEL_LOCALLY", "Adopt channel quantity in PennyWise Accounting")
    );
  form.elements.action.replaceChildren(...actions);
  form.elements.action.disabled = conflict.status !== "OPEN";
  form.querySelector('button[type="submit"]').hidden = conflict.status !== "OPEN";
  form.elements.effectiveDate.value = new Date().toISOString().slice(0, 10);
  renderInventoryConflictEffect();
  elements["inventory-conflict-dialog"].showModal();
  if (conflict.status === "OPEN") form.elements.action.focus();
}

function renderInventoryConflictEffect() {
  const form = elements["inventory-conflict-form"];
  const action = form.elements.action.value;
  const adopting = action === "ADOPT_CHANNEL_LOCALLY";
  for (const field of form.querySelectorAll(
    '[data-conflict-field="effectiveDate"], [data-conflict-field="unitCost"], [data-conflict-field="approval"]'
  ))
    field.hidden = !adopting;
  form.elements.effectiveDate.required = adopting;
  form.elements.approval.required = adopting;
  form.elements.reason.required = adopting || action === "IGNORE";
  if (!adopting) form.elements.approval.checked = false;
  elements["inventory-conflict-effect"].textContent =
    action === "PUSH_LOCAL_TO_CHANNEL"
      ? "Queues the exact PennyWise Accounting quantity for provider delivery. A provider failure leaves local inventory unchanged and remains visible for retry."
      : adopting
        ? "Creates a dated local inventory adjustment from reviewed channel evidence. This can change inventory value and create its related accounting entry."
        : "Closes this difference with your review note. Neither PennyWise Accounting nor the sales channel quantity is changed.";
}

async function resolveInventoryConflict(event) {
  event.preventDefault();
  if (!activeInventoryConflict || activeInventoryConflict.conflict.status !== "OPEN") return;
  const form = event.currentTarget;
  const data = new FormData(form);
  const action = data.get("action");
  const reason = String(data.get("reason") ?? "").trim();
  if ((action === "IGNORE" || action === "ADOPT_CHANNEL_LOCALLY") && !reason)
    return showNotice("Add a review note for this resolution.", true);
  if (action === "ADOPT_CHANNEL_LOCALLY" && data.get("approval") !== "on")
    return showNotice("Approve the local inventory adjustment before continuing.", true);
  const body = {
    action,
    version: activeInventoryConflict.conflict.version,
    ...(action === "IGNORE" ? { reason } : {}),
    ...(action === "ADOPT_CHANNEL_LOCALLY"
      ? {
          effectiveDate: data.get("effectiveDate"),
          reason
        }
      : {})
  };
  const unitCost = String(data.get("unitCost") ?? "").trim();
  if (action === "ADOPT_CHANNEL_LOCALLY" && unitCost) {
    try {
      body.unitCostMinor = parseMoneyInput(unitCost);
    } catch (error) {
      return showNotice(error instanceof Error ? error.message : "Enter a valid unit cost.", true);
    }
  }
  const request = jsonRequest(body);
  if (action === "ADOPT_CHANNEL_LOCALLY")
    request.headers["idempotency-key"] = globalThis.crypto.randomUUID();
  const response = await api(
    `/v1/organizations/current/inventory-sync/conflicts/${activeInventoryConflict.conflict.id}/resolve`,
    request
  );
  if (!response.ok) return handleCatalogAutomationError(response);
  elements["inventory-conflict-dialog"].close();
  activeInventoryConflict = null;
  await loadCatalogAutomation();
  showNotice(
    action === "PUSH_LOCAL_TO_CHANNEL"
      ? "PennyWise Accounting quantity queued for provider delivery."
      : action === "ADOPT_CHANNEL_LOCALLY"
        ? "Reviewed channel quantity adopted through the inventory adjustment workflow."
        : "Quantity difference closed without changing either system."
  );
}

function renderInventoryOperationRow(operation) {
  const action = document.createElement("button");
  action.type = "button";
  action.className = "secondary-command";
  action.dataset.inventoryOperationId = operation.id;
  action.textContent = "Retry";
  action.disabled = operation.status !== "FAILED";
  return row([
    formatConnectorTime(operation.occurredAt),
    formatConnectorStatus(operation.status),
    operation.attempts,
    action
  ]);
}

async function processInventoryOperations() {
  const button = elements["process-inventory-operations"];
  button.disabled = true;
  try {
    const response = await api(
      "/v1/organizations/current/inventory-sync/operations/process",
      jsonRequest({ limit: 10 })
    );
    if (!response.ok) return handleCatalogAutomationError(response);
    const result = await response.json();
    await loadCatalogAutomation();
    showNotice(
      `Inventory delivery queue processed: ${result.completed} completed, ${result.failed} failed, ${result.claimed} claimed.`
    );
  } finally {
    button.disabled = false;
  }
}

async function retryInventoryOperation(event) {
  const button = event.target.closest("[data-inventory-operation-id]");
  if (!button || button.disabled) return;
  const response = await api(
    `/v1/organizations/current/inventory-sync/operations/${button.dataset.inventoryOperationId}/retry`,
    jsonRequest({})
  );
  if (!response.ok) return handleCatalogAutomationError(response);
  await loadCatalogAutomation();
  showNotice("Failed provider update returned to the pending queue.");
}

function renderConnectorProviders() {
  elements["load-commerce-demo"].hidden = !connectorProviders.some(
    (provider) => provider.demoAvailable
  );
  elements["connector-provider-cards"].replaceChildren(
    ...connectorProviders.map((provider) => {
      const card = document.createElement("article");
      card.className = "connector-provider-card";
      const mark = document.createElement("span");
      mark.className = "connector-provider-mark";
      mark.textContent = provider.providerKey === "WOOCOMMERCE" ? "W" : "E";
      mark.setAttribute("aria-hidden", "true");
      const copy = document.createElement("div");
      const heading = document.createElement("h3");
      heading.textContent = provider.displayName;
      const description = document.createElement("p");
      description.textContent = provider.description;
      const approval = document.createElement("p");
      approval.textContent = provider.externalApproval;
      copy.append(heading, description, approval);
      card.append(mark, copy);
      return card;
    })
  );
}

async function loadCommerceDemo() {
  const button = elements["load-commerce-demo"];
  button.disabled = true;
  try {
    const response = await api("/v1/organizations/current/commerce/demo", jsonRequest({}));
    if (!response.ok) return showError(response);
    const result = (await response.json()).demo;
    await loadIntegrations();
    elements["connector-operation-status"].textContent =
      `Sample order ${result.event.resourceId} is in the review inbox. ` +
      `Accounting entries created: ${result.accountingEntriesCreated}.`;
    showNotice("Safe sample commerce evidence loaded. No books were changed.");
  } finally {
    button.disabled = false;
  }
}

function renderConnectorSelects() {
  for (const select of document.querySelectorAll("[data-connector-select]")) {
    const previous = select.value;
    const provider = select.dataset.connectorSelect;
    const matches = connectorInstallations.filter(
      (connector) => provider === "ALL" || connector.providerKey === provider
    );
    select.replaceChildren(
      option("", matches.length ? "Select a store" : "Add a store above first"),
      ...matches.map((connector) =>
        option(
          connector.id,
          `${connector.displayName} · ${formatConnectorStatus(connector.status)}`
        )
      )
    );
    if (matches.some((connector) => connector.id === previous)) select.value = previous;
    else if (matches.length === 1) select.value = matches[0].id;
  }
  fillConnectorMappingForm();
  renderEtsyWebhookUrl();
}

function renderConnectorInstallations() {
  elements["connector-installations"].replaceChildren(
    ...connectorInstallations.map((connector) => {
      const status = document.createElement("span");
      status.className = `status-pill ${connector.healthStatus === "FAILED" ? "is-error" : connector.healthStatus === "DEGRADED" ? "is-warning" : ""}`;
      status.textContent = `${formatConnectorStatus(connector.status)} · ${formatConnectorStatus(connector.healthStatus)}`;
      const webhook = document.createElement("span");
      webhook.className = `status-pill ${connector.webhookStatus === "FAILED" ? "is-error" : connector.webhookStatus === "DEGRADED" ? "is-warning" : ""}`;
      webhook.textContent = formatConnectorStatus(connector.webhookStatus);
      const actions = document.createElement("div");
      actions.className = "connector-action-group";
      const addAction = (label, action, disabled = false) => {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "secondary-command";
        button.textContent = label;
        button.dataset.connectorAction = action;
        button.dataset.connectorId = connector.id;
        button.disabled = disabled;
        actions.append(button);
      };
      addAction("Health", "health", !connector.consentedAt);
      addAction("Sync", "sync", connector.status !== "READY");
      if (connector.providerKey === "WOOCOMMERCE")
        addAction("Webhooks", "register-webhooks", connector.status !== "READY");
      else addAction("Webhook setup", "etsy-webhook", connector.status !== "READY");
      addAction(
        connector.status === "PAUSED" ? "Resume" : "Pause",
        connector.status === "PAUSED" ? "resume" : "pause",
        !["READY", "PAUSED"].includes(connector.status)
      );
      addAction("Logs", "logs");
      addAction(
        "Disconnect",
        "disconnect",
        !connector.consentedAt || connector.status === "DISCONNECTED"
      );
      return row([
        connector.externalAccountId
          ? `${connector.displayName}\n${connector.externalAccountId}`
          : connector.displayName,
        connector.providerKey === "WOOCOMMERCE" ? "WooCommerce" : "Etsy",
        status,
        formatConnectorTime(connector.lastSyncAt),
        webhook,
        actions
      ]);
    })
  );
}

async function createConnectorDraft(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const data = new FormData(form);
  const response = await api(
    "/v1/organizations/current/connectors",
    jsonRequest({
      providerKey: data.get("providerKey"),
      displayName: data.get("displayName"),
      mapping: {
        customerStrategy: "UNCONFIGURED",
        skuMappings: {},
        taxMappings: {},
        taxRemittanceMappings: {},
        taxRemittanceResponsibility: "REVIEW_REQUIRED"
      }
    })
  );
  if (!response.ok) return showError(response);
  form.reset();
  await loadIntegrations();
  showNotice("Store added. Complete its secure connection next.");
}

async function connectWooCommerce(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const data = new FormData(form);
  const connectorId = data.get("connectorId");
  const response = await api(
    `/v1/organizations/current/connectors/${connectorId}/connect`,
    jsonRequest({
      credentials: {
        storeUrl: data.get("storeUrl"),
        consumerKey: data.get("consumerKey"),
        consumerSecret: data.get("consumerSecret")
      },
      backfillStartAt: connectorDateBoundary(data.get("backfillStart"), false),
      backfillEndAt: connectorDateBoundary(data.get("backfillEnd"), true)
    })
  );
  form.elements.consumerKey.value = "";
  form.elements.consumerSecret.value = "";
  if (!response.ok) return showError(response);
  await loadIntegrations();
  showNotice("WooCommerce credentials verified. Run the first synchronization when ready.");
}

async function startEtsyOAuth(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const data = new FormData(form);
  const connectorId = data.get("connectorId");
  const response = await api(
    `/v1/organizations/current/connectors/${connectorId}/etsy/oauth/start`,
    jsonRequest({
      apiKey: data.get("apiKey"),
      sharedSecret: data.get("sharedSecret"),
      ...(String(data.get("shopId") || "").trim() ? { shopId: data.get("shopId") } : {}),
      redirectUri: new URL("/", window.location.origin).toString()
    })
  );
  form.elements.apiKey.value = "";
  form.elements.sharedSecret.value = "";
  if (!response.ok) return showError(response);
  const authorization = (await response.json()).authorization;
  sessionStorage.setItem("clearledger_etsy_oauth_connector", connectorId);
  window.location.assign(authorization.authorizationUrl);
}

async function completeEtsyOAuthFromCallback() {
  const connectorId = sessionStorage.getItem("clearledger_etsy_oauth_connector");
  const query = new URLSearchParams(window.location.search);
  if (!connectorId || (!query.has("code") && !query.has("error"))) return;
  activeWorkspaceId = "integrations-workspace";
  sessionStorage.setItem("clearledger_active_workspace", activeWorkspaceId);
  if (query.has("error")) {
    showNotice("Etsy authorization was cancelled or rejected.", true);
  } else {
    const response = await api(
      `/v1/organizations/current/connectors/${connectorId}/etsy/oauth/complete`,
      jsonRequest({ code: query.get("code"), state: query.get("state") })
    );
    if (!response.ok) await showError(response);
    else showNotice("Etsy shop connected. Run the first synchronization when ready.");
  }
  sessionStorage.removeItem("clearledger_etsy_oauth_connector");
  window.history.replaceState({}, "", "/");
  showWorkspaceNavigation();
  await loadIntegrations();
}

async function syncConnector(event) {
  event.preventDefault();
  const data = new FormData(event.currentTarget);
  await runConnectorSync(data.get("connectorId"), {
    from: connectorDateBoundary(data.get("from"), false),
    to: connectorDateBoundary(data.get("to"), true),
    maxPages: Number(data.get("maxPages")),
    pageSize: 50,
    scope: "ALL"
  });
}

async function runConnectorSync(connectorId, body = {}) {
  const isContinuation = Boolean(body.continuationToken);
  if (!isContinuation) setConnectorSyncContinuation(null);
  elements["continue-connector-sync"].disabled = true;
  elements["connector-operation-status"].textContent = "Synchronizing provider evidence…";
  const response = await api(
    `/v1/organizations/current/connectors/${connectorId}/sync`,
    jsonRequest(body)
  );
  if (!response.ok) {
    elements["connector-operation-status"].textContent = "";
    renderConnectorSyncContinuation();
    return showError(response);
  }
  const result = (await response.json()).sync;
  setConnectorSyncContinuation(
    result.continuation
      ? {
          organizationId: identity.activeOrganizationId,
          connectorId,
          token: result.continuation.token,
          remainingScopes: result.continuation.remainingScopes,
          window: result.continuation.window
        }
      : null
  );
  const remaining = result.continuation?.remainingScopes?.map(formatRole).join(", ") || "";
  elements["connector-operation-status"].textContent =
    `Imported ${result.imported}; already present ${result.replayed}; integrity conflicts ${result.conflicts}; pages ${result.pages}.\n` +
    (result.complete
      ? "All requested provider pages are complete. "
      : `More provider pages remain${remaining ? ` for ${remaining}` : ""}. Choose Continue sync to resume the same date range. `) +
    "Accounting entries created: 0. Imported events are waiting in the review inbox.";
  await loadIntegrations();
  showNotice(
    result.complete
      ? "Commerce synchronization completed without changing the books."
      : "More provider pages remain. Continue this synchronization when ready."
  );
}

async function continueConnectorSync() {
  if (
    !connectorSyncContinuation ||
    connectorSyncContinuation.organizationId !== identity?.activeOrganizationId
  )
    return;
  await runConnectorSync(connectorSyncContinuation.connectorId, {
    continuationToken: connectorSyncContinuation.token,
    maxPages: Number(elements["connector-sync-form"].elements.maxPages.value)
  });
}

function setConnectorSyncContinuation(value) {
  connectorSyncContinuation = value;
  if (value) sessionStorage.setItem(connectorSyncContinuationStorageKey, JSON.stringify(value));
  else sessionStorage.removeItem(connectorSyncContinuationStorageKey);
  renderConnectorSyncContinuation();
}

function readConnectorSyncContinuation() {
  try {
    const value = JSON.parse(sessionStorage.getItem(connectorSyncContinuationStorageKey) || "null");
    return value &&
      typeof value.organizationId === "string" &&
      typeof value.connectorId === "string" &&
      typeof value.token === "string"
      ? value
      : null;
  } catch {
    return null;
  }
}

function renderConnectorSyncContinuation() {
  const available =
    connectorSyncContinuation?.organizationId === identity?.activeOrganizationId &&
    connectorInstallations.some(
      (connector) => connector.id === connectorSyncContinuation.connectorId
    );
  elements["continue-connector-sync"].disabled = !available;
  elements["continue-connector-sync"].title = available
    ? "Resume the same provider date range from its saved cursor."
    : "No incomplete synchronization is waiting.";
}

async function saveConnectorMapping(event) {
  event.preventDefault();
  const data = new FormData(event.currentTarget);
  const connector = connectorInstallations.find((item) => item.id === data.get("connectorId"));
  if (!connector) return showNotice("Select a store.", true);
  let skuMappings;
  let taxMappings;
  let taxRemittanceMappings;
  try {
    skuMappings = parseMappingLines(data.get("skuMappings"));
    taxMappings = parseMappingLines(data.get("taxMappings"));
    taxRemittanceMappings = parseMappingLines(data.get("taxRemittanceMappings"));
  } catch (error) {
    return showNotice(error.message, true);
  }
  const editableMapping = Object.fromEntries(
    Object.entries(connector.mapping ?? {}).filter(
      ([key]) =>
        ![
          "catalogVariantMappings",
          "catalogProductMappings",
          "catalogSkuMappings",
          "catalogSkuAliases",
          "catalogSkuPatternRules"
        ].includes(key)
    )
  );
  const response = await api(
    `/v1/organizations/current/connectors/${connector.id}/mapping`,
    jsonRequest(
      {
        version: connector.mappingVersion,
        mapping: {
          ...editableMapping,
          customerStrategy: data.get("customerStrategy"),
          skuMappings,
          taxMappings,
          taxRemittanceMappings,
          taxRemittanceResponsibility: data.get("taxRemittanceResponsibility")
        }
      },
      "PATCH"
    )
  );
  if (!response.ok) return showError(response);
  await loadIntegrations();
  showNotice("Import rules saved. Synchronize again to apply them to staged events.");
}

function fillConnectorMappingForm() {
  const form = elements["connector-mapping-form"];
  const connector = connectorInstallations.find(
    (item) => item.id === form.elements.connectorId.value
  );
  if (!connector) return;
  form.elements.customerStrategy.value = connector.mapping?.customerStrategy || "UNCONFIGURED";
  form.elements.skuMappings.value = formatMappingLines(connector.mapping?.skuMappings);
  form.elements.taxMappings.value = formatMappingLines(connector.mapping?.taxMappings);
  form.elements.taxRemittanceMappings.value = formatMappingLines(
    connector.mapping?.taxRemittanceMappings
  );
  form.elements.taxRemittanceResponsibility.value =
    connector.mapping?.taxRemittanceResponsibility || "REVIEW_REQUIRED";
}

async function handleConnectorAction(event) {
  const button = event.target.closest("[data-connector-action]");
  if (!button) return;
  const connectorId = button.dataset.connectorId;
  const action = button.dataset.connectorAction;
  if (action === "sync") return runConnectorSync(connectorId);
  if (action === "etsy-webhook") {
    const details = elements["etsy-webhook-form"].closest("details");
    details.open = true;
    elements["etsy-webhook-form"].elements.connectorId.value = connectorId;
    renderEtsyWebhookUrl();
    details.scrollIntoView({ behavior: preferredScrollBehavior(), block: "center" });
    return;
  }
  if (action === "register-webhooks") {
    const deliveryUrl = connectorWebhookUrl("woocommerce", connectorId);
    const response = await api(
      `/v1/organizations/current/connectors/${connectorId}/webhooks/register`,
      jsonRequest({ deliveryUrl })
    );
    if (!response.ok) return showError(response);
    const result = (await response.json()).webhook;
    elements["connector-operation-status"].textContent =
      `WooCommerce webhooks active. Created ${result.created}; already present ${result.existing}.`;
    await loadIntegrations();
    return;
  }
  if (action === "logs") {
    const response = await api(`/v1/organizations/current/connectors/${connectorId}/logs?limit=20`);
    if (!response.ok) return showError(response);
    const logs = (await response.json()).logs;
    elements["connector-operation-status"].textContent = logs.length
      ? logs.map((log) => `${formatConnectorTime(log.createdAt)} · ${log.message}`).join("\n")
      : "No connector activity has been recorded yet.";
    return;
  }
  if (
    action === "disconnect" &&
    !window.confirm(
      "Remove the stored provider credentials? Imported review evidence will be retained."
    )
  )
    return;
  const response = await api(
    `/v1/organizations/current/connectors/${connectorId}/${action}`,
    jsonRequest({})
  );
  if (!response.ok) return showError(response);
  await loadIntegrations();
  showNotice(
    action === "health"
      ? "Connector health check completed."
      : action === "disconnect"
        ? "Connector credentials removed; imported evidence was retained."
        : `Connector ${action === "pause" ? "paused" : "resumed"}.`
  );
}

async function saveEtsyWebhookSecret(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const data = new FormData(form);
  const connectorId = data.get("connectorId");
  const response = await api(
    `/v1/organizations/current/connectors/${connectorId}/webhook-secret`,
    jsonRequest({ signingSecret: data.get("signingSecret") }, "PUT")
  );
  form.elements.signingSecret.value = "";
  if (!response.ok) return showError(response);
  await loadIntegrations();
  showNotice("Etsy signing secret saved. A verified delivery will mark the webhook active.");
}

function renderEtsyWebhookUrl() {
  const form = elements["etsy-webhook-form"];
  const connectorId = form.elements.connectorId.value;
  form.elements.webhookUrl.value = connectorId ? connectorWebhookUrl("etsy", connectorId) : "";
}

function connectorWebhookUrl(provider, connectorId) {
  const configuredBase = connectorProviders.find(
    (entry) => entry.providerKey === provider.toUpperCase()
  )?.webhookBaseUrl;
  if (configuredBase)
    return new URL(
      `/v1/webhooks/commerce/${encodeURIComponent(provider)}/${encodeURIComponent(connectorId)}`,
      `${configuredBase}/`
    ).toString();
  return new URL(
    `/api/v1/webhooks/commerce/${encodeURIComponent(provider)}/${encodeURIComponent(connectorId)}`,
    window.location.origin
  ).toString();
}

async function loadCommerceInbox() {
  if (!identity?.activeOrganizationId) return;
  const status = elements["commerce-inbox-filter"].value;
  const response = await api(
    `/v1/organizations/current/commerce/inbox?limit=200${status ? `&status=${encodeURIComponent(status)}` : ""}`,
    {},
    true
  );
  if (!response.ok) {
    if (response.status !== 403) await showError(response);
    commerceInboxEvents = [];
  } else commerceInboxEvents = (await response.json()).events;
  renderCommerceInbox();
}

function renderCommerceInbox() {
  const counts = Object.fromEntries(
    ["REVIEW_REQUIRED", "NORMALIZED", "DEAD_LETTER"].map((status) => [
      status,
      commerceInboxEvents.filter((event) => event.status === status).length
    ])
  );
  elements["commerce-inbox-summary"].replaceChildren(
    metric("Needs review", counts.REVIEW_REQUIRED),
    metric("Reviewed", counts.NORMALIZED),
    metric("Cannot process", counts.DEAD_LETTER),
    metric("Visible events", commerceInboxEvents.length)
  );
  elements["commerce-inbox-events"].replaceChildren(
    ...commerceInboxEvents.map((event) => {
      const issues = Array.isArray(event.normalizationIssues) ? event.normalizationIssues : [];
      const issueList = document.createElement("ul");
      issueList.className = "commerce-issue-list";
      for (const issue of issues.slice(0, 4)) {
        const item = document.createElement("li");
        item.className = issue.severity === "BLOCKING" ? "is-blocking" : "";
        item.textContent = issue.message;
        issueList.append(item);
      }
      if (issues.length > 4) {
        const item = document.createElement("li");
        item.textContent = `+ ${issues.length - 4} more findings`;
        issueList.append(item);
      }
      if (!issues.length) {
        const item = document.createElement("li");
        item.textContent = "No normalization findings";
        issueList.append(item);
      }
      const action = document.createElement("button");
      action.type = "button";
      action.className = "secondary-command";
      action.dataset.commerceEventId = event.id;
      const conversionComplete = Boolean(event.resultingInvoiceId);
      if (event.status === "NORMALIZED" && !conversionComplete) {
        action.textContent =
          event.conversionStatus === "REJECTED" ? "Review again" : "Preview draft";
      } else if (conversionComplete) {
        action.textContent = event.conversionStatus === "POSTED" ? "Posted" : "Draft linked";
      } else {
        action.textContent = "Mark reviewed";
      }
      action.disabled =
        conversionComplete ||
        (event.status !== "NORMALIZED" && issues.some((issue) => issue.severity === "BLOCKING"));
      return row([
        formatConnectorTime(event.occurredAt ?? event.createdAt),
        `${event.providerKey === "WOOCOMMERCE" ? "WooCommerce" : "Etsy"}\n${event.shopExternalId}`,
        `${formatConnectorStatus(event.eventType)}\n${event.resourceId}`,
        commerceEventTotal(event),
        issueList,
        event.conversionStatus && event.conversionStatus !== "NOT_STARTED"
          ? `${formatConnectorStatus(event.status)} · ${formatConnectorStatus(event.conversionStatus)}`
          : formatConnectorStatus(event.status),
        action
      ]);
    })
  );
}

async function reviewCommerceEvent(event) {
  const button = event.target.closest("[data-commerce-event-id]");
  if (!button) return;
  const item = commerceInboxEvents.find((entry) => entry.id === button.dataset.commerceEventId);
  if (!item) return;
  if (item.status === "NORMALIZED" && !item.resultingInvoiceId)
    return openCommerceConversionReview(item);
  const response = await api(
    `/v1/organizations/current/commerce/inbox/${item.id}/review`,
    jsonRequest({
      version: item.version,
      status: "NORMALIZED",
      reviewNote:
        "Reviewed in the PennyWise Accounting commerce inbox. No accounting entry was created."
    })
  );
  if (!response.ok) return showError(response);
  await loadCommerceInbox();
  showNotice("Commerce evidence marked reviewed. The books were not changed.");
}

async function openCommerceConversionReview(event) {
  const response = await api(
    `/v1/organizations/current/commerce/inbox/${event.id}/conversion-preflight`,
    {},
    true
  );
  if (!response.ok) return showError(response);
  const body = await response.json();
  activeCommerceConversion = { event, conversion: body.conversion };
  renderCommerceConversionReview();
  elements["commerce-conversion-dialog"].showModal();
}

function renderCommerceConversionReview() {
  const conversion = activeCommerceConversion?.conversion;
  if (!conversion) return;
  const provider = conversion.providerTotals ?? {};
  const providerMoney = provider.money?.total ?? provider.money?.amount;
  const providerReconciliation = provider.reconciliation;
  const providerOutput = elements["commerce-conversion-provider-evidence"];
  providerOutput.replaceChildren(
    conversionHeading("Provider evidence"),
    conversionDetail("Order currency", provider.currency ?? "Unknown"),
    conversionDetail("Provider subtotal", provider.money?.subtotal?.decimal ?? "Not supplied"),
    conversionDetail(
      "Provider tax",
      providerMoney?.currency ? (provider.money?.tax?.decimal ?? "Not supplied") : "Not supplied"
    ),
    conversionDetail("Provider total", providerMoney?.decimal ?? "Not supplied"),
    conversionDetail(
      "Reconciliation",
      providerReconciliation?.isExact === false
        ? "Provider totals need review"
        : "Retained provider totals"
    )
  );

  const draftOutput = elements["commerce-conversion-draft-preview"];
  draftOutput.replaceChildren(conversionHeading("Proposed PennyWise draft"));
  if (conversion.draft) {
    const draft = conversion.draft;
    draftOutput.append(
      conversionDetail("Customer", draft.customerName ?? "Selected customer"),
      conversionDetail("Issue date", String(draft.issueDate).slice(0, 10)),
      conversionDetail("Due date", String(draft.dueDate).slice(0, 10)),
      conversionDetail("Currency", draft.currency),
      conversionDetail("Subtotal", formatMinor(draft.subtotalMinor, draft.currency)),
      conversionDetail("Discount", formatMinor(draft.discountTotalMinor, draft.currency)),
      conversionDetail("Tax", formatMinor(draft.taxTotalMinor, draft.currency)),
      conversionDetail("Total", formatMinor(draft.grandTotalMinor, draft.currency))
    );
    const lines = document.createElement("ul");
    lines.className = "commerce-issue-list";
    for (const line of draft.lines ?? []) {
      const item = document.createElement("li");
      item.textContent = `${line.description} · ${formatQuantityMicros(line.quantityMicros)} × ${formatMinor(line.unitPriceMinor, draft.currency)} · net ${formatMinor(line.netAmountMinor, draft.currency)} · tax ${formatMinor(line.taxTotalMinor, draft.currency)} · income ${line.incomeAccountCode ?? "unmapped"} · tax code ${line.taxCodeId ?? "none"}`;
      lines.append(item);
    }
    draftOutput.append(conversionHeading("Lines, accounts, and tax"), lines);
  } else {
    const empty = document.createElement("p");
    empty.textContent = "No invoice draft can be assembled until the listed gaps are resolved.";
    draftOutput.append(empty);
  }

  const gapsOutput = elements["commerce-conversion-gaps"];
  gapsOutput.replaceChildren(
    conversionHeading(conversion.ready ? "Decision" : "Required before conversion")
  );
  if (conversion.ready) {
    const ready = document.createElement("p");
    ready.textContent = `Ready for explicit confirmation. Customer policy: ${conversion.customerStrategy}. This action creates a DRAFT only.`;
    gapsOutput.append(ready);
  } else {
    const gaps = document.createElement("ul");
    gaps.className = "commerce-issue-list";
    for (const gap of conversion.gaps ?? []) {
      const item = document.createElement("li");
      item.textContent = `${gap.code}: ${gap.message}${gap.path ? ` (${gap.path})` : ""}`;
      gaps.append(item);
    }
    gapsOutput.append(gaps);
  }
  elements["commerce-conversion-confirm"].disabled = !conversion.ready;
  elements["commerce-conversion-reject"].disabled = Boolean(conversion.resultingInvoiceId);
}

function conversionHeading(text) {
  const heading = document.createElement("h3");
  heading.textContent = text;
  return heading;
}

function conversionDetail(label, value) {
  const detail = document.createElement("p");
  detail.textContent = `${label}: ${value}`;
  return detail;
}

async function confirmCommerceConversion() {
  const active = activeCommerceConversion;
  if (!active?.conversion?.ready) return;
  const response = await api(
    `/v1/organizations/current/commerce/inbox/${active.event.id}/convert`,
    jsonRequest({ decision: "CONFIRM", version: active.event.version })
  );
  if (!response.ok) return showError(response);
  elements["commerce-conversion-dialog"].close();
  activeCommerceConversion = null;
  await loadCommerceInbox();
  showNotice("Draft invoice created. Posting remains a separate invoice action.");
}

async function rejectCommerceConversion() {
  const active = activeCommerceConversion;
  if (!active) return;
  const reason = elements["commerce-conversion-rejection-reason"].value.trim();
  if (!reason) return showNotice("Enter a rejection reason before rejecting conversion.", true);
  const response = await api(
    `/v1/organizations/current/commerce/inbox/${active.event.id}/convert`,
    jsonRequest({ decision: "REJECT", version: active.event.version, reason })
  );
  if (!response.ok) return showError(response);
  elements["commerce-conversion-dialog"].close();
  activeCommerceConversion = null;
  await loadCommerceInbox();
  showNotice("Conversion rejected with a review note. The books were not changed.");
}

function commerceEventTotal(event) {
  const total = event.normalizedPayload?.money?.total ?? event.normalizedPayload?.money?.amount;
  return total?.currency && total?.decimal ? `${total.currency} ${total.decimal}` : "—";
}

function metric(label, value) {
  const wrapper = document.createElement("div");
  const term = document.createElement("dt");
  term.textContent = label;
  const detail = document.createElement("dd");
  detail.textContent = String(value);
  wrapper.append(term, detail);
  return wrapper;
}

function parseMappingLines(value) {
  const mappings = {};
  for (const [index, rawLine] of String(value || "")
    .split(/\r?\n/)
    .entries()) {
    const line = rawLine.trim();
    if (!line) continue;
    const separator = line.indexOf("=");
    if (separator <= 0 || !line.slice(separator + 1).trim())
      throw new Error(`Mapping line ${index + 1} must use “source = destination”.`);
    const source = line.slice(0, separator).trim();
    const destination = line.slice(separator + 1).trim();
    if (source in mappings) throw new Error(`Mapping source “${source}” is listed more than once.`);
    mappings[source] = destination;
  }
  return mappings;
}

function formatMappingLines(value) {
  return value && typeof value === "object"
    ? Object.entries(value)
        .sort(([left], [right]) => left.localeCompare(right))
        .map(([source, destination]) => `${source} = ${destination}`)
        .join("\n")
    : "";
}

function setDefaultConnectorDates() {
  const today = new Date().toISOString().slice(0, 10);
  const from = new Date(Date.now() - 30 * 24 * 60 * 60_000).toISOString().slice(0, 10);
  for (const form of [elements["woocommerce-connect-form"], elements["connector-sync-form"]]) {
    if (!form.elements.backfillStart?.value && form.elements.backfillStart)
      form.elements.backfillStart.value = from;
    if (!form.elements.backfillEnd?.value && form.elements.backfillEnd)
      form.elements.backfillEnd.value = today;
    if (!form.elements.from?.value && form.elements.from) form.elements.from.value = from;
    if (!form.elements.to?.value && form.elements.to) form.elements.to.value = today;
  }
}

function connectorDateBoundary(value, end) {
  const date = String(value || "");
  const today = new Date().toISOString().slice(0, 10);
  if (!date) return null;
  if (end && date === today) return new Date().toISOString();
  return `${date}T${end ? "23:59:59.999" : "00:00:00.000"}Z`;
}

function formatConnectorTime(value) {
  if (!value) return "Never";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "Unknown" : date.toLocaleString();
}

function formatConnectorStatus(value) {
  return String(value || "unknown")
    .toLowerCase()
    .replaceAll("_", " ")
    .replace(/^./, (letter) => letter.toUpperCase());
}

function payrollToday() {
  return new Date().toISOString().slice(0, 10);
}

function payrollRequest(body, method = "POST") {
  return {
    ...jsonRequest(body, method),
    headers: {
      "content-type": "application/json",
      "idempotency-key": globalThis.crypto.randomUUID()
    }
  };
}

function setPayrollFormDisabled(formId, disabled) {
  const form = elements[formId];
  if (!form) return;
  for (const control of form.querySelectorAll("input, select, textarea, button")) {
    control.disabled = disabled;
  }
}

function replacePayrollOptions(select, options, selectedValue = select?.value ?? "") {
  if (!select) return;
  const empty = document.createElement("option");
  empty.value = "";
  empty.textContent = options.length ? "Choose..." : "No choices available";
  select.replaceChildren(
    empty,
    ...options.map((item) => {
      const option = document.createElement("option");
      option.value = item.value;
      option.textContent = item.label;
      return option;
    })
  );
  select.value = options.some((item) => item.value === selectedValue) ? selectedValue : "";
}

function payrollCodeReadinessSummary(readiness) {
  if (!readiness) return "The CA-AB base code check is unavailable.";
  if (readiness.ready)
    return `CA-AB base code set is ready (${payrollState?.activePayrollCodeCount ?? 0} active payroll codes total).`;
  const missing = readiness.missing?.length ? `Missing: ${readiness.missing.join(", ")}.` : "";
  const invalid = readiness.invalid?.length
    ? `Wrong category: ${readiness.invalid.map((item) => item.code).join(", ")}.`
    : "";
  return ["CA-AB base code set needs attention.", missing, invalid].filter(Boolean).join(" ");
}

function renderPayrollAccountOptions() {
  const settings = payrollState?.settings;
  const accountOptions = (accountType) =>
    accounts
      .filter((account) => account.type === accountType)
      .map((account) => ({
        value: account.id,
        label: `${account.code} ${account.name}`
      }));
  const expenseOptions = accountOptions("EXPENSE");
  const liabilityOptions = accountOptions("LIABILITY");
  const form = elements["payroll-settings-form"];
  replacePayrollOptions(
    form?.elements.defaultExpenseAccountId,
    expenseOptions,
    settings?.defaultExpenseAccountId ?? form?.elements.defaultExpenseAccountId?.value
  );
  replacePayrollOptions(
    form?.elements.defaultLiabilityAccountId,
    liabilityOptions,
    settings?.defaultLiabilityAccountId ?? form?.elements.defaultLiabilityAccountId?.value
  );
  replacePayrollOptions(
    form?.elements.netPayClearingAccountId,
    liabilityOptions,
    settings?.netPayClearingAccountId ?? form?.elements.netPayClearingAccountId?.value
  );
  if (settings) {
    form.elements.calculationRulePackId.value = settings.calculationRulePackId;
    form.elements.calculationRulePackVersion.value = settings.calculationRulePackVersion;
  }
  const canConfigure =
    expenseOptions.length > 0 &&
    liabilityOptions.length > 1 &&
    Boolean(identity?.activeOrganizationId);
  for (const control of form.querySelectorAll("select, button")) control.disabled = !canConfigure;
  elements["payroll-code-status"].textContent = settings
    ? payrollCodeReadinessSummary(payrollState.caAbBaseCodes)
    : expenseOptions.length && liabilityOptions.length > 1
      ? "Save the three ledger accounts before adding people or schedules."
      : "Add at least one expense account and two liability accounts before configuring payroll.";
  elements["ensure-ca-ab-payroll-codes"].disabled = !settings;
}

function renderPayrollScheduleOptions() {
  const options = (payrollState?.schedules ?? []).map((schedule) => ({
    value: schedule.id,
    label: `${schedule.name} (${formatRole(schedule.frequency)})`
  }));
  for (const formId of ["payroll-period-form", "payroll-scheduled-draft-form"]) {
    const select = elements[formId]?.elements.scheduleId;
    replacePayrollOptions(select, options, select?.value);
  }
}

function setPayrollDefaultDates() {
  const today = payrollToday();
  for (const formId of [
    "payroll-worker-form",
    "payroll-schedule-form",
    "payroll-period-form",
    "payroll-scheduled-draft-form",
    "payroll-automation-form"
  ]) {
    const form = elements[formId];
    if (!form) continue;
    for (const fieldName of [
      "effectiveFrom",
      "anchorPayDate",
      "periodStart",
      "periodEnd",
      "payDate",
      "asOfDate"
    ]) {
      if (form.elements[fieldName] && !form.elements[fieldName].value)
        form.elements[fieldName].value = today;
    }
  }
}

async function loadPayroll() {
  if (!identity?.activeOrganizationId) return;
  const requestId = ++payrollLoadRequestId;
  const response = await api("/v1/payroll/overview", {}, true);
  if (requestId !== payrollLoadRequestId) return;
  if (!response.ok) {
    payrollState = null;
    activePayrollRun = null;
    renderPayroll();
    if (activeWorkspaceId === "payroll-workspace") await showError(response);
    return;
  }
  payrollState = (await response.json()).payroll;
  renderPayroll();
}

function renderPayroll() {
  setPayrollDefaultDates();
  renderPayrollAccountOptions();
  renderPayrollScheduleOptions();
  const unavailable = !payrollState;
  elements["payroll-status"].textContent = unavailable
    ? "Payroll information is unavailable for this company or your current role."
    : payrollState.settings
      ? "Payroll is configured for controlled CA-AB regular-pay workflow. Direct deposit and tax filing remain provider-gated."
      : "Start with the three payroll ledger accounts. No payroll run can be prepared until that setup is saved.";
  const state = payrollState;
  const workingRuns = (state?.runs ?? []).filter((run) => run.status !== "POSTED");
  elements["payroll-summary"].replaceChildren(
    metric("Setup", state?.settings ? "Ready" : "Needs setup"),
    metric("People", state?.workers?.length ?? 0),
    metric("Open runs", workingRuns.length),
    metric("Open remittances", state?.openRemittances?.length ?? 0)
  );
  renderPayrollWorkers();
  renderPayrollSchedules();
  renderPayrollRemittances();
  renderPayrollRuns();
  const configured = Boolean(state?.settings);
  const hasSchedules = Boolean(state?.schedules?.length);
  setPayrollFormDisabled("payroll-worker-form", !configured);
  setPayrollFormDisabled("payroll-schedule-form", !configured);
  setPayrollFormDisabled("payroll-period-form", !configured || !hasSchedules);
  setPayrollFormDisabled("payroll-scheduled-draft-form", !configured || !hasSchedules);
  setPayrollFormDisabled("payroll-automation-form", !configured || !hasSchedules);
  if (state?.periods?.length) {
    const upcoming = [...state.periods]
      .filter((period) => period.payDate >= payrollToday())
      .sort((left, right) => left.payDate.localeCompare(right.payDate))
      .slice(0, 3);
    elements["payroll-automation-status"].textContent = upcoming.length
      ? `${state.periods.length} explicit period${state.periods.length === 1 ? "" : "s"} saved. Next: ${upcoming.map((period) => `${period.schedule?.name ?? "Schedule"} ${period.payDate}`).join("; ")}.`
      : `${state.periods.length} explicit period${state.periods.length === 1 ? "" : "s"} saved. Add the next pay period before it becomes due.`;
  } else {
    elements["payroll-automation-status"].textContent = configured
      ? "No explicit pay periods are saved yet. Create one before using scheduled drafts."
      : "Finish payroll setup before planning a pay period.";
  }
  renderPayrollRunDetail();
}

function renderPayrollWorkers() {
  const workers = payrollState?.workers ?? [];
  elements["payroll-workers"].replaceChildren(
    ...workers.map((worker) =>
      row([
        `${worker.displayName}\n${worker.workerNumber}`,
        formatRole(worker.kind),
        worker.governmentIdMask || worker.bankAccountMask
          ? "Masked identifiers held outside this screen"
          : "No identifier or bank data in this browser"
      ])
    )
  );
  if (!workers.length) {
    const empty = row(["No payroll workers yet.", "", ""]);
    empty.querySelector("td").colSpan = 3;
    empty.deleteCell(2);
    empty.deleteCell(1);
    elements["payroll-workers"].append(empty);
  }
}

function renderPayrollSchedules() {
  const schedules = payrollState?.schedules ?? [];
  elements["payroll-schedules"].replaceChildren(
    ...schedules.map((schedule) => {
      const action = document.createElement("button");
      action.type = "button";
      action.className = "secondary-command";
      action.textContent = schedule.automaticDraftsEnabled
        ? "Disable draft prep"
        : "Enable draft prep";
      action.title =
        "This changes only scheduled DRAFT preparation; it cannot calculate, post, pay, or file payroll.";
      action.addEventListener("click", () =>
        updatePayrollScheduleAutomation(schedule, !schedule.automaticDraftsEnabled)
      );
      return row([
        `${schedule.name}\n${schedule.code}`,
        formatRole(schedule.frequency),
        schedule.automaticDraftsEnabled
          ? `Enabled ${schedule.draftLeadDays} day${schedule.draftLeadDays === 1 ? "" : "s"} before pay date`
          : "Off",
        action
      ]);
    })
  );
  if (!schedules.length) {
    const empty = row(["No pay schedules yet.", "", "", ""]);
    empty.querySelector("td").colSpan = 4;
    empty.deleteCell(3);
    empty.deleteCell(2);
    empty.deleteCell(1);
    elements["payroll-schedules"].append(empty);
  }
}

function payrollListEmpty(text) {
  const item = document.createElement("p");
  item.className = "field-help";
  item.textContent = text;
  return item;
}

function renderPayrollRemittances() {
  const remittances = payrollState?.openRemittances ?? [];
  elements["payroll-remittances"].replaceChildren(
    ...(remittances.length
      ? remittances.map((item) => {
          const line = document.createElement("div");
          line.className = "payroll-compact-list-item";
          const label = document.createElement("strong");
          label.textContent = `${item.authorityCode} due ${item.dueDate}`;
          const detail = document.createElement("span");
          detail.textContent = `${formatMinor(item.amountMinor, item.run.currency)} · ${formatRole(item.status)} · ${item.run.runNumber}`;
          line.append(label, detail);
          return line;
        })
      : [
          payrollListEmpty(
            "No open remittance records. Posting a reviewed run can create reviewable remittance liabilities."
          )
        ])
  );
  const batches = payrollState?.paymentBatches ?? [];
  elements["payroll-payment-batches"].replaceChildren(
    ...(batches.length
      ? batches.map((item) => {
          const line = document.createElement("div");
          line.className = "payroll-compact-list-item";
          const label = document.createElement("strong");
          label.textContent = `${item.batchNumber} · ${formatRole(item.status)}`;
          const detail = document.createElement("span");
          detail.textContent = `${formatMinor(item.totalMinor, item.run.currency)} · ${item.paymentDate} · ${item.run.runNumber}`;
          line.append(label, detail);
          return line;
        })
      : [
          payrollListEmpty(
            "No payment batches. PennyWise Accounting does not initiate direct deposit or transfer funds."
          )
        ])
  );
}

function renderPayrollRuns() {
  const runs = payrollState?.runs ?? [];
  elements["payroll-runs"].replaceChildren(
    ...runs.map((run) => {
      const action = document.createElement("button");
      action.type = "button";
      action.className = "secondary-command";
      action.textContent = activePayrollRun?.id === run.id ? "Open" : "Review";
      action.addEventListener("click", () => openPayrollRun(run.id));
      return row([
        run.payDate,
        `${run.runNumber}\n${run.schedule?.name ?? formatRole(run.kind)}`,
        formatRole(run.status),
        run.workerCount,
        run.remittanceCount,
        action
      ]);
    })
  );
  if (!runs.length) {
    const empty = row(["No payroll runs yet.", "", "", "", "", ""]);
    empty.querySelector("td").colSpan = 6;
    for (let index = 0; index < 5; index += 1) empty.deleteCell(1);
    elements["payroll-runs"].append(empty);
  }
}

function renderPayrollRunDetail() {
  const detail = elements["payroll-run-detail"];
  const run = activePayrollRun;
  if (!run) {
    detail.hidden = true;
    return;
  }
  detail.hidden = false;
  elements["payroll-run-detail-heading"].textContent =
    `${run.runNumber} - ${formatRole(run.status)}`;
  elements["payroll-run-detail-summary"].textContent =
    `${run.periodStart} to ${run.periodEnd}; pay date ${run.payDate}; ${run.currency}.`;
  elements["payroll-run-workers"].replaceChildren(
    ...run.workers.map((worker) =>
      row([
        `${worker.worker.displayName}\n${worker.worker.workerNumber}`,
        worker.worker.jurisdictionCode,
        worker.draftGrossPayMinor == null
          ? "-"
          : formatMinor(worker.draftGrossPayMinor, run.currency),
        formatMinor(worker.grossPayMinor, run.currency),
        formatMinor(worker.employeeDeductionsMinor, run.currency),
        formatMinor(worker.netPayMinor, run.currency)
      ])
    )
  );
  const actions = elements["payroll-run-detail-actions"];
  actions.replaceChildren();
  const status = elements["payroll-run-detail-status"];
  const baseCodeReadiness = payrollState?.caAbBaseCodes;
  if (run.status === "DRAFT") {
    const calculate = document.createElement("button");
    calculate.type = "button";
    calculate.textContent = "Calculate payroll";
    calculate.disabled = !baseCodeReadiness?.ready;
    calculate.title = calculate.disabled
      ? "Add the released CA-AB base codes before calculating this draft."
      : "Calculate with the released CA-AB rule pack. This does not post or pay payroll.";
    calculate.addEventListener("click", () => performPayrollRunAction("calculate"));
    actions.append(calculate);
    status.textContent = calculate.disabled
      ? `This is a draft. ${payrollCodeReadinessSummary(baseCodeReadiness)}`
      : "This is a draft. Calculation creates an immutable result for review; it does not post, pay, or file anything.";
  } else if (run.status === "CALCULATED") {
    const review = document.createElement("button");
    review.type = "button";
    review.textContent = "Mark reviewed";
    review.addEventListener("click", () => performPayrollRunAction("review"));
    actions.append(review);
    status.textContent =
      "Review the worker totals and deductions. A different permitted reviewer may be required before approval.";
  } else if (run.status === "REVIEWED") {
    const approve = document.createElement("button");
    approve.type = "button";
    approve.textContent = "Approve payroll";
    approve.addEventListener("click", () => performPayrollRunAction("approve"));
    actions.append(approve);
    status.textContent =
      "Approval is a separate controlled action. It still does not create a journal or move funds.";
  } else if (run.status === "APPROVED") {
    const post = document.createElement("button");
    post.type = "button";
    post.textContent = "Post to ledger";
    post.addEventListener("click", () => performPayrollRunAction("post"));
    actions.append(post);
    status.textContent =
      "Posting creates the accounting journal, payslip snapshot, and remittance records. Direct deposit and filing remain disconnected.";
  } else {
    status.textContent = run.journalId
      ? "Posted to the ledger. Any payment export must be handled through an approved provider workflow; PennyWise Accounting did not send funds."
      : "This payroll run is complete.";
  }
}

async function savePayrollSettings(event) {
  event.preventDefault();
  const data = new FormData(event.currentTarget);
  const response = await api(
    "/v1/payroll/settings",
    jsonRequest(
      {
        defaultExpenseAccountId: data.get("defaultExpenseAccountId"),
        defaultLiabilityAccountId: data.get("defaultLiabilityAccountId"),
        netPayClearingAccountId: data.get("netPayClearingAccountId"),
        calculationRulePackId: data.get("calculationRulePackId"),
        calculationRulePackVersion: data.get("calculationRulePackVersion")
      },
      "PUT"
    )
  );
  if (!response.ok) return showError(response);
  await loadPayroll();
  showNotice(
    "Payroll setup saved. Add the released CA-AB base code set before calculating a draft."
  );
}

async function ensureCaAbPayrollCodes() {
  const response = await api("/v1/payroll/ca-ab-base-codes", payrollRequest({}));
  if (!response.ok) return showError(response);
  const result = (await response.json()).payrollCodeSet;
  await loadPayroll();
  showNotice(
    result.created
      ? `${result.created} missing CA-AB base payroll code${result.created === 1 ? " was" : "s were"} added. Existing mappings were not changed.`
      : "The released CA-AB base code set is already present. Existing mappings were not changed."
  );
}

function parsePayrollHoursMicros(value) {
  const text = String(value ?? "")
    .trim()
    .replace(",", ".");
  if (!text) return null;
  if (!/^\d+(?:\.\d{1,6})?$/.test(text))
    throw new Error("Enter hours as a number with up to six decimal places.");
  const [whole, fraction = ""] = text.split(".");
  const micros = BigInt(whole) * 1_000_000n + BigInt(fraction.padEnd(6, "0"));
  if (micros <= 0n) throw new Error("Hours per pay period must be greater than zero.");
  return micros.toString();
}

async function createPayrollWorker(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const data = new FormData(form);
  let rateMinor;
  let hoursPerPeriodMicros;
  let additionalTaxMinor;
  try {
    rateMinor = parseMoneyInput(data.get("rate"));
    hoursPerPeriodMicros =
      data.get("compensationKind") === "HOURLY"
        ? parsePayrollHoursMicros(data.get("hoursPerPeriod"))
        : null;
    if (data.get("compensationKind") === "HOURLY" && !hoursPerPeriodMicros)
      throw new Error(
        "Hourly workers need default hours per pay period before a draft can be prepared."
      );
    additionalTaxMinor = String(data.get("additionalTax") ?? "").trim()
      ? parseMoneyInput(data.get("additionalTax"))
      : null;
  } catch (error) {
    return showNotice(
      error instanceof Error ? error.message : "Check worker compensation values.",
      true
    );
  }
  const response = await api(
    "/v1/payroll/workers",
    payrollRequest({
      workerNumber: data.get("workerNumber"),
      kind: data.get("kind"),
      displayName: data.get("displayName"),
      profile: {
        effectiveFrom: data.get("effectiveFrom"),
        status: "ACTIVE",
        jurisdictionCode: data.get("jurisdictionCode"),
        taxAttributes: {
          canadianWithholding: {
            federalClaimCode: Number(data.get("federalClaimCode")),
            provincialClaimCode: Number(data.get("provincialClaimCode")),
            ...(additionalTaxMinor ? { additionalTaxMinor } : {})
          }
        }
      },
      compensation: {
        effectiveFrom: data.get("effectiveFrom"),
        kind: data.get("compensationKind"),
        rateMinor,
        hoursPerPeriodMicros
      }
    })
  );
  if (!response.ok) return showError(response);
  form.reset();
  setPayrollDefaultDates();
  await loadPayroll();
  showNotice(
    "Payroll worker added. No government identifier or bank detail was collected in this browser."
  );
}

async function createPayrollSchedule(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const data = new FormData(form);
  const response = await api(
    "/v1/payroll/schedules",
    payrollRequest({
      code: data.get("code"),
      name: data.get("name"),
      frequency: data.get("frequency"),
      anchorPayDate: data.get("anchorPayDate"),
      automaticDraftsEnabled: data.get("automaticDraftsEnabled") === "on",
      draftLeadDays: Number(data.get("draftLeadDays"))
    })
  );
  if (!response.ok) return showError(response);
  form.reset();
  setPayrollDefaultDates();
  await loadPayroll();
  showNotice(
    "Pay schedule added. Scheduled preparation can create only reviewable drafts from explicit periods."
  );
}

async function updatePayrollScheduleAutomation(schedule, automaticDraftsEnabled) {
  const response = await api(
    `/v1/payroll/schedules/${schedule.id}/automation`,
    jsonRequest(
      {
        version: schedule.version,
        automaticDraftsEnabled,
        draftLeadDays: schedule.draftLeadDays
      },
      "PATCH"
    )
  );
  if (!response.ok) return showError(response);
  await loadPayroll();
  showNotice(
    automaticDraftsEnabled
      ? "Scheduled draft preparation enabled. It cannot calculate, approve, post, pay, or file payroll."
      : "Scheduled draft preparation disabled. Existing drafts were not changed."
  );
}

async function createPayrollPeriod(event) {
  event.preventDefault();
  const data = new FormData(event.currentTarget);
  const response = await api(
    "/v1/payroll/periods",
    jsonRequest({
      scheduleId: data.get("scheduleId"),
      periodStart: data.get("periodStart"),
      periodEnd: data.get("periodEnd"),
      payDate: data.get("payDate"),
      sequence: Number(data.get("sequence"))
    })
  );
  if (!response.ok) return showError(response);
  await loadPayroll();
  showNotice("Explicit pay period saved. It can now be prepared as a reviewable draft when due.");
}

async function createScheduledPayrollDraft(event) {
  event.preventDefault();
  const data = new FormData(event.currentTarget);
  const rawSequence = String(data.get("sequence") ?? "").trim();
  const response = await api(
    `/v1/payroll/schedules/${encodeURIComponent(String(data.get("scheduleId")))}/generate-draft`,
    payrollRequest({
      periodStart: data.get("periodStart"),
      periodEnd: data.get("periodEnd"),
      payDate: data.get("payDate"),
      ...(rawSequence ? { sequence: Number(rawSequence) } : {})
    })
  );
  if (!response.ok) return showError(response);
  activePayrollRun = (await response.json()).payrollRun;
  await loadPayroll();
  renderPayrollRunDetail();
  showNotice("Payroll draft prepared. Review the planned gross pay, then calculate it when ready.");
}

async function runPayrollDraftAutomation(event) {
  event.preventDefault();
  const data = new FormData(event.currentTarget);
  const response = await api(
    "/v1/payroll/automation/run",
    jsonRequest({ asOfDate: data.get("asOfDate") })
  );
  if (!response.ok) return showError(response);
  const result = (await response.json()).payrollAutomation;
  await loadPayroll();
  elements["payroll-automation-status"].textContent =
    `${result.checked} period${result.checked === 1 ? "" : "s"} checked; ${result.created.length} draft${result.created.length === 1 ? "" : "s"} prepared; ${result.alreadyPrepared.length} already prepared; ${result.notDue.length} not due; ${result.blocked.length} blocked.`;
  showNotice(
    "Due-period check complete. It prepared drafts only; no calculation, posting, payment, or filing occurred."
  );
}

async function openPayrollRun(runId) {
  const response = await api(`/v1/payroll/runs/${encodeURIComponent(runId)}`, {}, true);
  if (!response.ok) return showError(response);
  activePayrollRun = (await response.json()).payrollRun;
  renderPayrollRunDetail();
}

async function performPayrollRunAction(action) {
  const run = activePayrollRun;
  if (!run) return;
  const path = `/v1/payroll/runs/${encodeURIComponent(run.id)}/${action === "review" ? "review" : action === "approve" ? "approve" : action === "post" ? "post" : "calculate"}`;
  const request =
    action === "calculate"
      ? jsonRequest({})
      : action === "post"
        ? payrollRequest({ version: run.version })
        : jsonRequest({ version: run.version });
  const response = await api(path, request);
  if (!response.ok) return showError(response);
  activePayrollRun = (await response.json()).payrollRun;
  await loadPayroll();
  renderPayrollRunDetail();
  const labels = {
    calculate: "Payroll calculated for review. No journal was posted and no funds moved.",
    review: "Payroll marked reviewed. Approval remains a separate controlled action.",
    approve: "Payroll approved. Posting to the ledger remains a separate controlled action.",
    post: "Payroll posted to the ledger. No direct deposit or filing was initiated."
  };
  showNotice(labels[action]);
}

// ---------------------------------------------------------------------------
// Orders & fulfilment workspace
//
// D3/D4/D5 built the order-conversion, picking-slip and shipping services and no
// way to drive them: before this, apps/web contained zero references to picking,
// shipment, carrier or commerce/orders. This is the operator surface for that
// loop — review, convert, pick, ship.
//
// The connector review boundary is the point of the screen. Provider data stays
// non-posting until a person acts, so nothing here converts implicitly: loading
// the workspace, selecting an order and reading its preflight all post nothing.
// ---------------------------------------------------------------------------

let fulfilmentOrders = [];
let fulfilmentSelectedEventId = null;
let fulfilmentPreflight = null;
let fulfilmentCarrierAccounts = [];
let fulfilmentInvoice = null;
let fulfilmentPickingSlip = null;
let fulfilmentShipment = null;
let fulfilmentPickingMessage = null;
let fulfilmentShipmentMessage = null;
const fulfilmentProgressByInvoice = new Map();
const fulfilmentShipmentIds = readFulfilmentShipmentIds();

function readFulfilmentShipmentIds() {
  try {
    const stored = JSON.parse(
      sessionStorage.getItem("clearledger_fulfilment_shipments_v1") ?? "{}"
    );
    return new Map(
      Object.entries(stored).filter(
        ([invoiceId, shipmentId]) =>
          typeof invoiceId === "string" && typeof shipmentId === "string" && shipmentId
      )
    );
  } catch {
    return new Map();
  }
}

function rememberFulfilmentShipment(invoiceId, shipmentId) {
  if (!invoiceId || !shipmentId) return;
  fulfilmentShipmentIds.set(invoiceId, shipmentId);
  sessionStorage.setItem(
    "clearledger_fulfilment_shipments_v1",
    JSON.stringify(Object.fromEntries(fulfilmentShipmentIds))
  );
}

function fulfilmentShipmentIdFor(invoiceId) {
  return invoiceId ? (fulfilmentShipmentIds.get(invoiceId) ?? null) : null;
}

function setFulfilmentStatus(message, isError = false) {
  const status = elements["fulfilment-status"];
  if (!status) return;
  status.hidden = !message;
  status.textContent = message ?? "";
  status.dataset.state = message ? (isError ? "error" : "info") : "idle";
}

async function loadFulfilment() {
  if (!identity?.activeOrganizationId) return;
  await Promise.all([
    loadFulfilmentOrders(),
    loadFulfilmentCarrierAccounts(),
    accounts.length ? Promise.resolve() : loadFulfilmentAccounts()
  ]);
}

async function loadFulfilmentAccounts() {
  const response = await api("/v1/accounts", {}, true);
  if (response.ok) accounts = (await response.json()).accounts ?? [];
}

async function loadFulfilmentOrders() {
  const list = elements["fulfilment-order-list"];
  if (!list) return;
  const status = elements["fulfilment-status-filter"]?.value ?? "";
  const query = status ? `?status=${encodeURIComponent(status)}` : "";
  const response = await api(`/v1/organizations/current/commerce/inbox${query}`, {}, true);
  if (!response.ok) {
    fulfilmentOrders = [];
    list.replaceChildren(
      fulfilmentEmptyState(
        response.status === 403
          ? "Your role cannot review store orders."
          : "Orders could not be loaded. No order was changed."
      )
    );
    setFulfilmentStatus("Orders are unavailable right now.", true);
    return;
  }
  setFulfilmentStatus(null);
  fulfilmentOrders = (await response.json()).events ?? [];
  renderFulfilmentOrders();
  await loadFulfilmentProgress();
}

async function loadFulfilmentProgress() {
  const converted = fulfilmentOrders.filter((event) => event.resultingInvoiceId);
  await Promise.all(
    converted.map(async (event) => {
      const invoiceId = event.resultingInvoiceId;
      const pickingResponse = await api(`/v1/invoices/${invoiceId}/picking-slip`, {}, true);
      let pickingSlip = null;
      if (pickingResponse.ok) pickingSlip = (await pickingResponse.json()).slip ?? null;
      const shipmentId = fulfilmentShipmentIdFor(invoiceId);
      let shipment = null;
      if (shipmentId) {
        const shipmentResponse = await api(`/v1/shipments/${shipmentId}`, {}, true);
        if (shipmentResponse.ok) shipment = (await shipmentResponse.json()).shipment ?? null;
      }
      fulfilmentProgressByInvoice.set(invoiceId, { pickingSlip, shipment });
    })
  );
  renderFulfilmentOrders();
}

function fulfilmentEmptyState(message) {
  const item = document.createElement("li");
  item.className = "empty-state";
  item.textContent = message;
  return item;
}

// The inbox returns the provider's raw payload. Read it defensively: a store can
// omit anything, and a missing field must read as unknown rather than as zero.
function fulfilmentOrderSummary(event) {
  const payload = event.rawPayload ?? {};
  const lines = Array.isArray(payload.line_items) ? payload.line_items : [];
  const buyer = payload.billing ?? {};
  const name = [buyer.first_name, buyer.last_name].filter(Boolean).join(" ").trim();
  return {
    reference: payload.number ?? payload.id ?? event.resourceId ?? event.externalEventId,
    customerName: name || buyer.company || null,
    lineCount: lines.length,
    total: typeof payload.total === "string" ? payload.total : null,
    currency: event.sourceCurrency ?? payload.currency ?? null
  };
}

const fulfilmentStatusLabels = {
  AWAITING_REVIEW: "Awaiting review",
  REVIEW_REQUIRED: "Review required",
  REVIEWED: "Reviewed",
  CONVERTED: "Converted",
  PICKED: "Picked",
  SHORT_PICK: "Short pick",
  SHIPPED: "Shipped",
  FAILED: "Failed"
};

function fulfilmentDerivedStatus(event) {
  const invoiceId = event?.resultingInvoiceId ?? null;
  const progress = invoiceId ? fulfilmentProgressByInvoice.get(invoiceId) : null;
  const shipment =
    event?.id === fulfilmentSelectedEventId ? fulfilmentShipment : (progress?.shipment ?? null);
  if (shipment?.status === "PURCHASED" || shipment?.status === "PURCHASED_EXPENSE_PENDING")
    return "SHIPPED";
  if (progress?.pickingSlip?.status === "SHORT_PICK") return "SHORT_PICK";
  if (progress?.pickingSlip?.status === "PICKED") return "PICKED";
  if (invoiceId) return "CONVERTED";
  if (event.status === "NORMALIZED") return "REVIEWED";
  if (event.status === "DEAD_LETTER") return "FAILED";
  if (event.status === "REVIEW_REQUIRED") return "REVIEW_REQUIRED";
  return "AWAITING_REVIEW";
}

function renderFulfilmentOrders() {
  const list = elements["fulfilment-order-list"];
  if (!list) return;
  if (fulfilmentOrders.length === 0) {
    list.replaceChildren(
      fulfilmentEmptyState("No orders are waiting. Nothing needs your attention here.")
    );
    renderFulfilmentDetail();
    return;
  }
  list.replaceChildren(
    ...fulfilmentOrders.map((event) => {
      const summary = fulfilmentOrderSummary(event);
      const item = document.createElement("li");
      const button = document.createElement("button");
      button.type = "button";
      button.className = "fulfilment-order";
      button.dataset.eventId = event.id;
      if (event.id === fulfilmentSelectedEventId) button.setAttribute("aria-current", "true");

      const heading = document.createElement("span");
      heading.className = "fulfilment-order-reference";
      heading.textContent = `Order ${String(summary.reference)}`;

      const meta = document.createElement("span");
      meta.className = "fulfilment-order-meta";
      const parts = [];
      if (summary.customerName) parts.push(summary.customerName);
      parts.push(`${String(summary.lineCount)} line${summary.lineCount === 1 ? "" : "s"}`);
      // The provider's own total, labelled as theirs. PennyWise's calculated
      // total appears only in the preflight, where the two can be compared.
      if (summary.total && summary.currency)
        parts.push(`${summary.currency} ${summary.total} at the store`);
      meta.textContent = parts.join(" · ");

      const state = document.createElement("span");
      state.className = "fulfilment-order-state";
      const derivedStatus = fulfilmentDerivedStatus(event);
      state.dataset.status = derivedStatus;
      state.textContent = fulfilmentStatusLabels[derivedStatus] ?? derivedStatus;

      button.append(heading, meta, state);
      button.addEventListener("click", () => void selectFulfilmentOrder(event.id));
      item.append(button);
      return item;
    })
  );
}

async function selectFulfilmentOrder(eventId) {
  fulfilmentSelectedEventId = eventId;
  fulfilmentPreflight = null;
  fulfilmentInvoice = null;
  fulfilmentPickingSlip = null;
  fulfilmentShipment = null;
  fulfilmentPickingMessage = null;
  fulfilmentShipmentMessage = null;
  renderFulfilmentOrders();
  const detail = elements["fulfilment-detail"];
  if (detail) detail.replaceChildren(fulfilmentParagraph("Checking this order…", "empty-state"));
  const response = await api(
    `/v1/organizations/current/commerce/inbox/${eventId}/conversion-preflight`,
    {},
    true
  );
  if (!response.ok) {
    fulfilmentPreflight = null;
    if (detail)
      detail.replaceChildren(
        fulfilmentParagraph(
          "This order could not be checked. Nothing was converted or changed.",
          "empty-state"
        )
      );
    return;
  }
  const body = await response.json();
  fulfilmentPreflight = body.conversion ?? body;
  await loadFulfilmentLinkedRecords();
  renderFulfilmentDetail();
}

async function loadFulfilmentLinkedRecords() {
  const event = fulfilmentSelectedEvent();
  const invoiceId = event?.resultingInvoiceId ?? null;
  if (!invoiceId) {
    renderFulfilmentPicking();
    renderFulfilmentShipping();
    return;
  }
  const invoiceResponse = await api(`/v1/invoices/${invoiceId}`, {}, true);
  fulfilmentInvoice = invoiceResponse.ok ? ((await invoiceResponse.json()).invoice ?? null) : null;
  await Promise.all([loadFulfilmentPicking(invoiceId), loadFulfilmentShipment(invoiceId)]);
  fulfilmentProgressByInvoice.set(invoiceId, {
    pickingSlip: fulfilmentPickingSlip,
    shipment: fulfilmentShipment
  });
  renderFulfilmentOrders();
}

async function loadFulfilmentShipment(invoiceId) {
  fulfilmentShipment = null;
  fulfilmentShipmentMessage = null;
  const shipmentId = fulfilmentShipmentIdFor(invoiceId);
  if (!shipmentId) {
    renderFulfilmentShipping();
    return;
  }
  const response = await api(`/v1/shipments/${shipmentId}`, {}, true);
  if (!response.ok) {
    fulfilmentShipmentMessage =
      response.status === 404
        ? "The saved shipment is no longer available. Create a new shipment draft."
        : "The shipment could not be loaded. No shipping action was made.";
    renderFulfilmentShipping();
    return;
  }
  fulfilmentShipment = (await response.json()).shipment ?? null;
  renderFulfilmentShipping();
}

function fulfilmentParagraph(text, className) {
  const p = document.createElement("p");
  if (className) p.className = className;
  p.textContent = text;
  return p;
}

// providerTotals carries the store's own money representation. Render the
// provider's decimal string as given rather than reformatting it — this is the
// number to compare against, and re-deriving it would defeat the comparison.
function fulfilmentProviderTotal(providerTotals) {
  const total = providerTotals?.money?.total;
  if (!total) return null;
  const currency = total.currency ?? providerTotals.currency ?? "";
  const value = total.providerRepresentation ?? total.decimal;
  return value ? `${currency} ${value}`.trim() : null;
}

function fulfilmentOrderLines(event) {
  const payload = event?.rawPayload ?? {};
  return Array.isArray(payload.line_items) ? payload.line_items : [];
}

function renderFulfilmentOrderLines(event) {
  const lines = fulfilmentOrderLines(event);
  if (!lines.length) return fulfilmentParagraph("The store supplied no line items.", "empty-state");
  const wrapper = document.createElement("div");
  wrapper.className = "fulfilment-line-list";
  const heading = document.createElement("h4");
  heading.textContent = "Store line items";
  const table = document.createElement("table");
  table.className = "fulfilment-lines-table";
  table.innerHTML =
    '<thead><tr><th scope="col">Item</th><th scope="col">Qty</th><th scope="col">Price</th><th scope="col">Total</th></tr></thead>';
  const body = document.createElement("tbody");
  for (const line of lines) {
    const row = document.createElement("tr");
    const values = [
      line.name ?? line.product_name ?? line.sku ?? "Unnamed item",
      line.quantity ?? "Unknown",
      line.price ?? line.unit_price ?? "Unknown",
      line.total ?? line.subtotal ?? "Unknown"
    ];
    for (const value of values) {
      const cell = document.createElement("td");
      cell.textContent = String(value);
      row.append(cell);
    }
    body.append(row);
  }
  table.append(body);
  wrapper.append(heading, table);
  return wrapper;
}

function renderFulfilmentDetail() {
  const detail = elements["fulfilment-detail"];
  if (!detail) return;
  if (!fulfilmentSelectedEventId || !fulfilmentPreflight) {
    detail.replaceChildren(
      fulfilmentParagraph("Choose an order to see what converting it would create.", "empty-state")
    );
    return;
  }
  const preflight = fulfilmentPreflight;
  const event = fulfilmentOrders.find((candidate) => candidate.id === fulfilmentSelectedEventId);
  if (!event) {
    detail.replaceChildren(
      fulfilmentParagraph("Refresh the order list and choose an order again.", "empty-state")
    );
    return;
  }
  const summary = event ? fulfilmentOrderSummary(event) : null;
  const nodes = [];

  const heading = document.createElement("h3");
  heading.className = "fulfilment-detail-reference";
  heading.textContent = summary ? `Order ${String(summary.reference)}` : "Order";
  nodes.push(heading);

  const state = document.createElement("p");
  state.className = "fulfilment-detail-state";
  const derivedStatus = fulfilmentDerivedStatus(event);
  state.textContent = `Workflow status: ${fulfilmentStatusLabels[derivedStatus] ?? derivedStatus}`;
  state.dataset.status = derivedStatus;
  nodes.push(state, renderFulfilmentOrderLines(event));

  // Readiness first: the operator's question is "can I convert this, and if not,
  // what do I have to do".
  const readiness = document.createElement("p");
  readiness.className = "fulfilment-readiness";
  readiness.dataset.ready = String(preflight.ready === true);
  readiness.textContent = preflight.ready
    ? "Ready to convert. This creates a draft customer invoice. Posting is a separate explicit accounting action."
    : "Not ready to convert yet.";
  nodes.push(readiness);

  const facts = document.createElement("dl");
  facts.className = "fulfilment-facts";
  const providerTotal = fulfilmentProviderTotal(preflight.providerTotals);
  const rows = [
    ["Store total", providerTotal ?? "Not supplied by the store"],
    ["Customer handling", preflight.customerStrategy ?? "Unknown"],
    ["Conversion status", preflight.conversionStatus ?? preflight.status ?? "Unknown"]
  ];
  for (const [label, value] of rows) {
    const term = document.createElement("dt");
    term.textContent = label;
    const description = document.createElement("dd");
    description.textContent = String(value);
    facts.append(term, description);
  }
  nodes.push(facts);

  if (fulfilmentInvoice) nodes.push(renderFulfilmentInvoiceState(fulfilmentInvoice));

  if (Array.isArray(preflight.gaps) && preflight.gaps.length > 0) {
    const gapsHeading = document.createElement("h4");
    gapsHeading.textContent = "Before this order can be converted";
    const gaps = document.createElement("ul");
    gaps.className = "fulfilment-gaps";
    for (const gap of preflight.gaps) {
      const item = document.createElement("li");
      // Show the service's own message. A friendlier rewrite here would lose the
      // reason the operator needs in order to fix it.
      item.textContent = gap.message ?? gap.code ?? "Unspecified requirement";
      gaps.append(item);
    }
    nodes.push(gapsHeading, gaps);
  }

  const actions = document.createElement("div");
  actions.className = "fulfilment-actions";

  if (!event.resultingInvoiceId) {
    const markReviewed = document.createElement("button");
    markReviewed.type = "button";
    markReviewed.className = "secondary-command";
    markReviewed.textContent = "Mark reviewed";
    markReviewed.addEventListener("click", () => void reviewFulfilmentOrder("NORMALIZED"));

    const convert = document.createElement("button");
    convert.type = "button";
    convert.className = "fulfilment-convert";
    convert.textContent = "Convert to invoice";
    convert.disabled = preflight.ready !== true;
    if (preflight.ready !== true)
      convert.title = "Resolve the listed requirements before this order can be converted.";
    convert.addEventListener("click", () => void convertFulfilmentOrder());

    const reject = document.createElement("button");
    reject.type = "button";
    reject.className = "text-command";
    reject.textContent = "Reject order";
    reject.addEventListener("click", () => void rejectFulfilmentOrder());

    actions.append(markReviewed, convert, reject);
  }
  nodes.push(actions);

  detail.replaceChildren(...nodes);
}

function renderFulfilmentInvoiceState(invoice) {
  const wrapper = document.createElement("section");
  wrapper.className = "fulfilment-linked-record";
  const heading = document.createElement("h4");
  heading.textContent = "Linked invoice";
  const facts = document.createElement("dl");
  facts.className = "fulfilment-facts";
  for (const [label, value] of [
    ["Invoice", invoice.invoiceNumber ?? invoice.provisionalIdentifier ?? invoice.id],
    ["Status", invoice.status ?? "Unknown"],
    ["Total", formatMinor(invoice.grandTotalMinor, invoice.currency)]
  ]) {
    const term = document.createElement("dt");
    term.textContent = label;
    const description = document.createElement("dd");
    description.textContent = String(value);
    facts.append(term, description);
  }
  wrapper.append(heading, facts);
  if (invoice.status === "DRAFT" || invoice.status === "APPROVED") {
    const note = fulfilmentParagraph(
      "Posting creates the customer invoice journal and depletes linked inventory. Nothing has been posted yet.",
      "non-posting-callout"
    );
    const button = document.createElement("button");
    button.type = "button";
    button.className = "fulfilment-convert";
    button.textContent = "Post invoice";
    button.addEventListener("click", () => void postFulfilmentInvoice(invoice));
    wrapper.append(note, button);
  } else if (invoice.status === "POSTED") {
    wrapper.append(
      fulfilmentParagraph(
        "Invoice is posted. Warehouse and shipping actions below do not post accounting entries."
      )
    );
  }
  return wrapper;
}

function fulfilmentSelectedEvent() {
  return fulfilmentOrders.find((candidate) => candidate.id === fulfilmentSelectedEventId) ?? null;
}

async function reviewFulfilmentOrder(status) {
  const event = fulfilmentSelectedEvent();
  if (!event) return;
  const response = await api(
    `/v1/organizations/current/commerce/inbox/${event.id}/review`,
    jsonRequest({ status, version: event.version ?? 1 })
  );
  if (!response.ok) return showError(response);
  showNotice("Order marked reviewed.");
  await loadFulfilmentOrders();
  await selectFulfilmentOrder(event.id);
}

async function convertFulfilmentOrder() {
  const event = fulfilmentSelectedEvent();
  if (!event || fulfilmentPreflight?.ready !== true) return;
  const summary = fulfilmentOrderSummary(event);
  const confirmed = window.confirm(
    `Convert order ${String(summary.reference)} into a customer invoice?\n\n` +
      "This creates a draft invoice only. Posting it is a separate explicit accounting action in Order detail."
  );
  if (!confirmed) return;
  const response = await api(
    `/v1/organizations/current/commerce/inbox/${event.id}/convert`,
    jsonRequest({ decision: "CONFIRM", version: event.version ?? 1 })
  );
  if (!response.ok) return showError(response);
  const body = await response.json().catch(() => ({}));
  const invoiceId =
    body.conversion?.resultingInvoiceId ?? body.invoice?.id ?? body.invoiceId ?? null;
  showNotice(
    invoiceId
      ? "Order converted to a draft invoice. Review it, then post it explicitly to continue."
      : "Order converted to an invoice draft."
  );
  await loadFulfilmentOrders();
  await selectFulfilmentOrder(event.id);
}

async function postFulfilmentInvoice(invoice) {
  const label = invoice.invoiceNumber ?? invoice.provisionalIdentifier ?? invoice.id;
  if (
    !window.confirm(
      `Post invoice ${label} for ${formatMinor(invoice.grandTotalMinor, invoice.currency)}?\n\n` +
        "This creates the customer invoice journal and depletes linked inventory. The action is recorded in the audit trail."
    )
  )
    return;
  const response = await api(`/v1/invoices/${invoice.id}/post`, {
    ...jsonRequest({ version: invoice.version }),
    headers: {
      "content-type": "application/json",
      "idempotency-key": globalThis.crypto.randomUUID()
    }
  });
  if (!response.ok) return showError(response);
  showNotice("Invoice posted. You can now create the picking slip.");
  await loadFulfilmentOrders();
  await selectFulfilmentOrder(fulfilmentSelectedEventId);
}

async function rejectFulfilmentOrder() {
  const event = fulfilmentSelectedEvent();
  if (!event) return;
  const reason = window.prompt(
    "Why is this order being rejected? The reason is kept with the order."
  );
  if (!reason || !reason.trim()) return;
  const response = await api(
    `/v1/organizations/current/commerce/inbox/${event.id}/convert`,
    jsonRequest({ decision: "REJECT", version: event.version ?? 1, reason: reason.trim() })
  );
  if (!response.ok) return showError(response);
  showNotice("Order rejected.");
  fulfilmentSelectedEventId = null;
  fulfilmentPreflight = null;
  await loadFulfilmentOrders();
  renderFulfilmentDetail();
}

// --- Picking ---------------------------------------------------------------

async function loadFulfilmentPicking(invoiceId) {
  fulfilmentPickingSlip = null;
  fulfilmentPickingMessage = null;
  const response = await api(`/v1/invoices/${invoiceId}/picking-slip`, {}, true);
  if (!response.ok) {
    fulfilmentPickingMessage =
      response.status === 404
        ? "No picking slip exists for this order yet."
        : "The picking slip could not be loaded. No warehouse record was changed.";
    renderFulfilmentPicking();
    return;
  }
  fulfilmentPickingSlip = (await response.json()).slip ?? null;
  renderFulfilmentPicking();
}

function fulfilmentCreateSlipButton(invoiceId) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "secondary-command";
  button.textContent = "Create picking slip";
  button.addEventListener("click", () => void createFulfilmentPickingSlip(invoiceId));
  return button;
}

async function createFulfilmentPickingSlip(invoiceId) {
  const response = await api(`/v1/invoices/${invoiceId}/picking-slip`, jsonRequest({}));
  if (!response.ok) return showError(response);
  showNotice("Picking slip created.");
  await loadFulfilmentPicking(invoiceId);
  fulfilmentProgressByInvoice.set(invoiceId, {
    pickingSlip: fulfilmentPickingSlip,
    shipment: fulfilmentShipment
  });
  renderFulfilmentOrders();
}

function renderFulfilmentPicking(slip = fulfilmentPickingSlip) {
  const panel = elements["fulfilment-picking"];
  if (!panel) return;
  if (!fulfilmentInvoice) {
    panel.replaceChildren(
      fulfilmentParagraph(
        "Convert and post an order before producing a picking slip.",
        "empty-state"
      )
    );
    return;
  }
  if (fulfilmentInvoice.status === "DRAFT" || fulfilmentInvoice.status === "APPROVED") {
    panel.replaceChildren(
      fulfilmentParagraph(
        "Post the linked invoice before producing a picking slip. Posting is an explicit accounting action in Order detail.",
        "empty-state"
      )
    );
    return;
  }
  if (!slip) {
    panel.replaceChildren(
      fulfilmentParagraph(
        fulfilmentPickingMessage ?? "No picking slip exists for this order yet.",
        "empty-state"
      ),
      fulfilmentCreateSlipButton(fulfilmentInvoice.id)
    );
    return;
  }
  const nodes = [];
  const facts = document.createElement("dl");
  facts.className = "fulfilment-facts";
  for (const [label, value] of [
    ["Slip", slip.slipNumber ?? slip.id ?? "Unknown"],
    ["Generation", slip.generation != null ? String(slip.generation) : "1"],
    ["Status", slip.status ?? "Open"]
  ]) {
    const term = document.createElement("dt");
    term.textContent = label;
    const description = document.createElement("dd");
    description.textContent = String(value);
    facts.append(term, description);
  }
  nodes.push(facts);

  const lineHeading = document.createElement("h4");
  lineHeading.textContent = "Record picked quantities";
  nodes.push(lineHeading);
  const explanation = fulfilmentParagraph(
    "Enter what was physically picked for every line. A short pick creates an inventory-count review only; it does not change stock or post a journal.",
    "field-help"
  );
  nodes.push(explanation);

  if (slip.status !== "PICKED") {
    const form = document.createElement("form");
    form.className = "fulfilment-picking-form";
    form.addEventListener("submit", (event) => void recordFulfilmentPick(event, slip));
    const table = document.createElement("table");
    table.className = "fulfilment-lines-table";
    table.innerHTML =
      '<thead><tr><th scope="col">Item</th><th scope="col">To pick</th><th scope="col">Picked</th></tr></thead>';
    const body = document.createElement("tbody");
    for (const line of slip.lines ?? []) {
      const row = document.createElement("tr");
      const item = document.createElement("td");
      item.textContent = [line.descriptionSnapshot, line.skuSnapshot].filter(Boolean).join(" | ");
      const toPick = document.createElement("td");
      toPick.textContent = formatQuantityMicros(line.quantityToPick);
      const pickedCell = document.createElement("td");
      const input = document.createElement("input");
      input.type = "text";
      input.inputMode = "decimal";
      input.required = true;
      input.value =
        line.pickedQuantityMicros == null
          ? formatQuantityMicros(line.quantityToPick)
          : formatQuantityMicros(line.pickedQuantityMicros);
      input.dataset.pickingLineId = line.id;
      input.setAttribute("aria-label", `Picked quantity for ${line.descriptionSnapshot}`);
      pickedCell.append(input);
      row.append(item, toPick, pickedCell);
      body.append(row);
    }
    table.append(body);
    const submit = document.createElement("button");
    submit.type = "submit";
    submit.textContent = "Record picked quantities";
    form.append(table, submit);
    nodes.push(form);
  } else {
    nodes.push(
      fulfilmentParagraph(
        "All lines were picked. No accounting entry was created by this warehouse action."
      )
    );
  }

  const actions = document.createElement("div");
  actions.className = "fulfilment-actions";
  const openPdf = document.createElement("button");
  openPdf.type = "button";
  openPdf.className = "secondary-command";
  openPdf.textContent = "Open picking slip PDF";
  openPdf.addEventListener("click", () => void openFulfilmentPickingPdf(slip));
  const reprint = document.createElement("button");
  reprint.type = "button";
  reprint.className = "secondary-command";
  reprint.textContent = "Reprint";
  reprint.addEventListener("click", () => void reprintFulfilmentPickingSlip(slip));
  actions.append(openPdf, reprint);
  nodes.push(actions);
  panel.replaceChildren(...nodes);
}

async function openFulfilmentPickingPdf(slip) {
  const response = await api(`/v1/picking-slips/${slip.id}/pdf`, {}, true);
  if (!response.ok) return showError(response);
  const url = URL.createObjectURL(await response.blob());
  const link = document.createElement("a");
  link.href = url;
  link.target = "_blank";
  link.rel = "noopener";
  link.download = `${slip.slipNumber ?? slip.id}.pdf`;
  link.click();
  URL.revokeObjectURL(url);
  showNotice("Picking slip PDF opened. No accounting entry was created.");
}

async function recordFulfilmentPick(event, slip) {
  event.preventDefault();
  const form = event.currentTarget;
  const lines = [...form.querySelectorAll("[data-picking-line-id]")].map((input) => ({
    lineId: input.dataset.pickingLineId,
    pickedQuantity: input.value.trim()
  }));
  if (lines.some((line) => !line.pickedQuantity))
    return showNotice("Record a picked quantity for every line.", true);
  const response = await api(`/v1/picking-slips/${slip.id}/short-pick`, jsonRequest({ lines }));
  if (!response.ok) return showError(response);
  const body = await response.json();
  fulfilmentPickingSlip = body.slip ?? slip;
  fulfilmentPickingMessage = null;
  fulfilmentProgressByInvoice.set(fulfilmentInvoice.id, {
    pickingSlip: fulfilmentPickingSlip,
    shipment: fulfilmentShipment
  });
  showNotice(
    fulfilmentPickingSlip.status === "PICKED"
      ? "All picked quantities recorded. No accounting entry was created."
      : "Short pick recorded for inventory review. No accounting entry was created."
  );
  renderFulfilmentPicking();
  renderFulfilmentOrders();
}

async function reprintFulfilmentPickingSlip(slip) {
  const response = await api(
    `/v1/picking-slips/${slip.id}/reprint`,
    jsonRequest({ version: slip.version ?? 1 })
  );
  if (!response.ok) return showError(response);
  showNotice("Picking slip reprinted.");
  const body = await response.json().catch(() => ({}));
  renderFulfilmentPicking(body.slip ?? slip);
}

// --- Shipping --------------------------------------------------------------

async function loadFulfilmentCarrierAccounts() {
  const response = await api("/v1/shipping/carrier-accounts", {}, true);
  if (!response.ok) {
    fulfilmentCarrierAccounts = [];
    fulfilmentShipmentMessage =
      "Carrier accounts could not be loaded. No label was bought or changed.";
    renderFulfilmentShipping();
    return;
  }
  fulfilmentCarrierAccounts = (await response.json()).carrierAccounts ?? [];
  renderFulfilmentShipping();
}

function renderFulfilmentShipping() {
  const panel = elements["fulfilment-shipping"];
  if (!panel) return;
  const activeCarrierAccounts = fulfilmentCarrierAccounts.filter(
    (account) => account.status === "ACTIVE"
  );
  if (fulfilmentCarrierAccounts.length === 0 || activeCarrierAccounts.length === 0) {
    const nodes = [
      fulfilmentParagraph(
        "No carrier account is connected, so labels cannot be bought yet.",
        "empty-state"
      ),
      fulfilmentParagraph(
        "Connect the carrier account you already hold in External integrations. Postage is billed to that account by the carrier.",
        "field-help"
      )
    ];
    const open = document.createElement("button");
    open.type = "button";
    open.className = "secondary-command";
    open.textContent = "Open External integrations";
    open.addEventListener("click", () => activateWorkspace("integrations-workspace"));
    nodes.push(open);
    panel.replaceChildren(...nodes);
    return;
  }
  if (!fulfilmentInvoice) {
    panel.replaceChildren(
      fulfilmentParagraph("Convert and post an order before creating a shipment.", "empty-state")
    );
    return;
  }
  if (!["POSTED", "PARTIALLY_PAID", "PAID", "OVERDUE"].includes(fulfilmentInvoice.status)) {
    panel.replaceChildren(
      fulfilmentParagraph(
        "The linked invoice must be posted before a shipment can be created.",
        "empty-state"
      )
    );
    return;
  }
  if (!fulfilmentShipment) {
    panel.replaceChildren(
      fulfilmentShipmentMessage
        ? fulfilmentParagraph(fulfilmentShipmentMessage, "empty-state")
        : fulfilmentParagraph(
            "Create a shipment draft. This does not call the carrier or post an expense.",
            "field-help"
          ),
      fulfilmentCreateShipmentForm(activeCarrierAccounts)
    );
    return;
  }
  panel.replaceChildren(renderFulfilmentShipmentState(fulfilmentShipment));
  /*
      .join(" · ");
    item.append(name, meta);
    list.append(item);
  }
  panel.replaceChildren(list);
  */
}

function fulfilmentField(labelText, control, helpText) {
  const label = document.createElement("label");
  label.className = "fulfilment-field";
  const text = document.createElement("span");
  text.textContent = labelText;
  label.append(text, control);
  if (helpText) {
    const help = document.createElement("small");
    help.className = "field-help";
    help.textContent = helpText;
    label.append(help);
  }
  return label;
}

function fulfilmentInput(name, type, value, options = {}) {
  const input = document.createElement("input");
  input.name = name;
  input.type = type;
  input.value = value;
  if (options.required) input.required = true;
  if (options.min !== undefined) input.min = String(options.min);
  if (options.step !== undefined) input.step = String(options.step);
  if (options.inputMode) input.inputMode = options.inputMode;
  if (options.placeholder) input.placeholder = options.placeholder;
  return input;
}

function fulfilmentSelect(name, choices, required = false) {
  const select = document.createElement("select");
  select.name = name;
  select.replaceChildren(...choices.map(([value, label]) => option(value, label)));
  select.required = required;
  return select;
}

function fulfilmentFormActions(submitLabel) {
  const actions = document.createElement("div");
  actions.className = "fulfilment-actions";
  const submit = document.createElement("button");
  submit.type = "submit";
  submit.className = "fulfilment-convert";
  submit.textContent = submitLabel;
  actions.append(submit);
  return actions;
}

function fulfilmentCreateShipmentForm(carrierAccounts) {
  const form = document.createElement("form");
  form.className = "fulfilment-shipment-form";
  form.addEventListener("submit", (event) => void createFulfilmentShipment(event));
  const carrier = fulfilmentSelect(
    "carrierAccountId",
    [
      ["", "Choose carrier account"],
      ...carrierAccounts.map((account) => [
        account.id,
        `${account.displayName ?? account.carrierKey} | ${account.environment}`
      ])
    ],
    true
  );
  const parcelFields = document.createElement("div");
  parcelFields.className = "fulfilment-form-grid";
  parcelFields.append(
    fulfilmentField("Carrier account", carrier),
    fulfilmentField(
      "Weight (grams)",
      fulfilmentInput("weightGrams", "number", "1500", { required: true, min: 1 })
    ),
    fulfilmentField(
      "Length (mm)",
      fulfilmentInput("lengthMm", "number", "300", { required: true, min: 1 })
    ),
    fulfilmentField(
      "Width (mm)",
      fulfilmentInput("widthMm", "number", "200", { required: true, min: 1 })
    ),
    fulfilmentField(
      "Height (mm)",
      fulfilmentInput("heightMm", "number", "100", { required: true, min: 1 })
    ),
    fulfilmentField(
      "Package type",
      fulfilmentInput("packageType", "text", "BOX", { placeholder: "BOX" }),
      "Dimensions and weight are sent to the carrier exactly as entered."
    )
  );
  form.append(
    fulfilmentParagraph(
      "The posted invoice supplies the sender and customer shipping address. Review the parcel measurements before asking the carrier for a quote.",
      "field-help"
    ),
    parcelFields,
    fulfilmentFormActions("Create shipment draft")
  );
  return form;
}

function fulfilmentShipmentFacts(shipment) {
  const facts = document.createElement("dl");
  facts.className = "fulfilment-facts";
  const carrier = shipment.carrierAccount ?? {};
  const quote = shipment.quotedCostMinor
    ? formatMinor(shipment.quotedCostMinor, shipment.quotedCurrency)
    : "No quote yet";
  for (const [label, value] of [
    ["Shipment", shipment.id],
    ["Carrier", carrier.displayName ?? carrier.carrierKey ?? "Unknown"],
    ["Status", shipment.status ?? "Unknown"],
    ["Service", shipment.serviceName ?? shipment.serviceCode ?? "Not selected"],
    ["Quote", quote],
    ["Tracking", shipment.trackingNumber ?? "Not available"]
  ]) {
    const term = document.createElement("dt");
    term.textContent = label;
    const description = document.createElement("dd");
    description.textContent = String(value);
    facts.append(term, description);
  }
  return facts;
}

function fulfilmentShipmentError(shipment) {
  if (!shipment.lastErrorMessage && !shipment.lastProviderCode) return null;
  const error = fulfilmentParagraph(
    [shipment.lastErrorMessage, shipment.lastProviderCode].filter(Boolean).join(" | "),
    "fulfilment-provider-error"
  );
  error.setAttribute("role", "alert");
  return error;
}

function fulfilmentQuoteForm(shipment) {
  const form = document.createElement("form");
  form.className = "fulfilment-quote-form";
  form.addEventListener("submit", (event) => void quoteFulfilmentShipment(event, shipment));
  const service = fulfilmentInput("serviceCode", "text", shipment.serviceCode ?? "", {
    placeholder: "Optional carrier service code"
  });
  form.append(
    fulfilmentField(
      "Service code",
      service,
      "Leave blank to let the configured carrier choose its default service."
    ),
    fulfilmentFormActions("Get carrier quote")
  );
  return form;
}

function fulfilmentAccountLabel(accountId) {
  const account = accounts.find((candidate) => candidate.id === accountId);
  return account ? `${account.code} ${account.name}` : "Choose an account";
}

function fulfilmentPurchaseForm(shipment) {
  const expenseAccounts = accounts.filter(
    (account) => account.type === "EXPENSE" && !account.isControl && !account.isArchived
  );
  const payingAccounts = accounts.filter(
    (account) =>
      ["ASSET", "LIABILITY", "EQUITY"].includes(account.type) &&
      account.systemPurpose !== "accounts-receivable" &&
      !account.isArchived
  );
  const form = document.createElement("form");
  form.className = "fulfilment-purchase-form";
  form.addEventListener("submit", (event) => void purchaseFulfilmentShipment(event, shipment));
  if (!expenseAccounts.length || !payingAccounts.length) {
    const open = document.createElement("button");
    open.type = "button";
    open.className = "secondary-command";
    open.textContent = "Open chart of accounts";
    open.addEventListener("click", () => activateWorkspace("setup-workspace"));
    form.append(
      fulfilmentParagraph(
        "An active expense account and paying account are required before postage can be purchased.",
        "empty-state"
      ),
      open
    );
    return form;
  }
  const expense = fulfilmentSelect(
    "expenseAccountId",
    [
      ["", "Choose postage expense account"],
      ...expenseAccounts.map((account) => [account.id, `${account.code} ${account.name}`])
    ],
    true
  );
  const paying = fulfilmentSelect(
    "payingAccountId",
    [
      ["", "Choose paying account"],
      ...payingAccounts.map((account) => [account.id, `${account.code} ${account.name}`])
    ],
    true
  );
  const method = fulfilmentSelect(
    "expenseMethod",
    [
      ["", "Choose payment method"],
      ["CASH", "Cash"],
      ["CHEQUE", "Cheque"],
      ["ELECTRONIC_TRANSFER", "Electronic transfer"],
      ["CREDIT_CARD", "Credit card"],
      ["OWNER_PAID", "Owner paid"],
      ["OTHER", "Other"]
    ],
    true
  );
  const date = fulfilmentInput("expenseDate", "date", new Date().toISOString().slice(0, 10), {
    required: true
  });
  const fields = document.createElement("div");
  fields.className = "fulfilment-form-grid";
  fields.append(
    fulfilmentField("Postage expense account", expense),
    fulfilmentField("Paying account", paying),
    fulfilmentField("Payment method", method),
    fulfilmentField("Expense date", date)
  );
  form.append(
    fulfilmentParagraph(
      `Buying this label will call the carrier and create one immediate expense for ${formatMinor(shipment.quotedCostMinor, shipment.quotedCurrency)}. This is the only shipping action that posts an expense.`,
      "fulfilment-posting-callout"
    ),
    fields,
    fulfilmentFormActions("Review and purchase label")
  );
  return form;
}

function renderFulfilmentShipmentState(shipment) {
  const wrapper = document.createElement("div");
  wrapper.className = "fulfilment-shipment-state";
  const heading = document.createElement("h3");
  heading.textContent = "Shipment";
  wrapper.append(heading, fulfilmentShipmentFacts(shipment));
  const error = fulfilmentShipmentError(shipment);
  if (error) wrapper.append(error);
  if (["DRAFT", "FAILED"].includes(shipment.status)) wrapper.append(fulfilmentQuoteForm(shipment));
  if (["QUOTED", "PURCHASED_EXPENSE_PENDING"].includes(shipment.status)) {
    wrapper.append(
      fulfilmentParagraph(
        shipment.status === "PURCHASED_EXPENSE_PENDING"
          ? "The carrier purchase was recorded. Complete the linked expense below; the service will reconcile the existing purchase instead of buying a second label."
          : "Review the carrier quote, then choose the accounts and date for the one expense that label purchase will post.",
        "field-help"
      ),
      fulfilmentPurchaseForm(shipment)
    );
  }
  if (shipment.status === "VOID_REJECTED")
    wrapper.append(
      fulfilmentParagraph(
        "The carrier rejected the void. Review its response before trying again.",
        "field-help"
      )
    );
  if (["PURCHASED", "VOID_PENDING", "VOID_REJECTED"].includes(shipment.status)) {
    const actions = document.createElement("div");
    actions.className = "fulfilment-actions";
    for (const label of shipment.labels ?? []) {
      const open = document.createElement("button");
      open.type = "button";
      open.className = "secondary-command";
      open.textContent = label.format === "ZPL" ? "Download ZPL label" : "Open PDF label";
      open.addEventListener("click", () => void openFulfilmentLabel(label));
      actions.append(open);
    }
    if (shipment.status === "PURCHASED") {
      const track = document.createElement("button");
      track.type = "button";
      track.className = "secondary-command";
      track.textContent = "Refresh tracking";
      track.addEventListener("click", () => void trackFulfilmentShipment(shipment));
      actions.append(track);
    }
    if (["PURCHASED", "VOID_REJECTED"].includes(shipment.status)) {
      const voidButton = document.createElement("button");
      voidButton.type = "button";
      voidButton.className = "text-command";
      voidButton.textContent = "Void shipment";
      voidButton.addEventListener("click", () => void voidFulfilmentShipment(shipment));
      actions.append(voidButton);
    }
    wrapper.append(actions);
  }
  if (shipment.status === "VOIDED")
    wrapper.append(
      fulfilmentParagraph(
        "The carrier accepted the void. No active label remains for this shipment."
      )
    );
  return wrapper;
}

function updateFulfilmentShipment(shipment) {
  fulfilmentShipment = shipment;
  if (fulfilmentInvoice?.id && shipment?.id)
    rememberFulfilmentShipment(fulfilmentInvoice.id, shipment.id);
  if (fulfilmentInvoice?.id)
    fulfilmentProgressByInvoice.set(fulfilmentInvoice.id, {
      pickingSlip: fulfilmentPickingSlip,
      shipment
    });
  renderFulfilmentShipping();
  renderFulfilmentOrders();
}

async function createFulfilmentShipment(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const values = {};
  for (const name of ["weightGrams", "lengthMm", "widthMm", "heightMm"]) {
    const value = Number(form.elements[name].value);
    if (!Number.isSafeInteger(value) || value <= 0)
      return showNotice(`${name} must be a positive whole number.`, true);
    values[name] = value;
  }
  const packageType = form.elements.packageType.value.trim();
  const response = await api(
    `/v1/invoices/${fulfilmentInvoice.id}/shipment`,
    jsonRequest({
      carrierAccountId: form.elements.carrierAccountId.value,
      parcels: [{ parcelNumber: 1, ...values, ...(packageType ? { packageType } : {}) }]
    })
  );
  if (!response.ok) return showError(response);
  const body = await response.json();
  updateFulfilmentShipment(body.shipment);
  showNotice("Shipment draft created. No carrier call or expense was made.");
}

async function quoteFulfilmentShipment(event, shipment) {
  event.preventDefault();
  const serviceCode = event.currentTarget.elements.serviceCode.value.trim();
  const response = await api(
    `/v1/shipments/${shipment.id}/quote`,
    jsonRequest({ version: shipment.version, ...(serviceCode ? { serviceCode } : {}) })
  );
  if (!response.ok) return showError(response);
  const body = await response.json();
  updateFulfilmentShipment(body.shipment);
  showNotice("Carrier quote received. Review it before purchasing the label.");
}

async function purchaseFulfilmentShipment(event, shipment) {
  event.preventDefault();
  const form = event.currentTarget;
  if (!form.reportValidity()) return;
  const expenseAccountId = form.elements.expenseAccountId.value;
  const payingAccountId = form.elements.payingAccountId.value;
  const expenseMethod = form.elements.expenseMethod.value;
  const expenseDate = form.elements.expenseDate.value;
  const amount = formatMinor(shipment.quotedCostMinor, shipment.quotedCurrency);
  const expenseAccount = fulfilmentAccountLabel(expenseAccountId);
  const payingAccount = fulfilmentAccountLabel(payingAccountId);
  if (
    !window.confirm(
      `Purchase the ${shipment.serviceName ?? shipment.serviceCode} label for ${amount}?\n\n` +
        `This calls the carrier and posts one immediate expense: ${amount} to ${expenseAccount}, paid from ${payingAccount}, method ${formatRole(expenseMethod)}, dated ${expenseDate}. Confirm only if those exact accounting details are correct.`
    )
  )
    return;
  const response = await api(
    `/v1/shipments/${shipment.id}/purchase`,
    jsonRequest({
      version: shipment.version,
      confirmed: true,
      serviceCode: shipment.serviceCode,
      quotedCostMinor: shipment.quotedCostMinor,
      quotedCurrency: shipment.quotedCurrency,
      expenseAccountId,
      payingAccountId,
      expenseMethod,
      expenseDate
    })
  );
  if (!response.ok) return showError(response);
  const body = await response.json();
  updateFulfilmentShipment(body.shipment);
  showNotice("Label purchased. One shipping expense was posted to the selected accounts.");
}

async function openFulfilmentLabel(label) {
  const response = await api(`/v1/shipment-labels/${label.id}`, {}, true);
  if (!response.ok) return showError(response);
  const url = URL.createObjectURL(await response.blob());
  const link = document.createElement("a");
  link.href = url;
  link.target = "_blank";
  link.rel = "noopener";
  link.download = `${label.id}.${label.format === "ZPL" ? "zpl" : "pdf"}`;
  link.click();
  URL.revokeObjectURL(url);
  showNotice(
    `${label.format === "ZPL" ? "ZPL" : "PDF"} label opened. No accounting entry was created.`
  );
}

async function trackFulfilmentShipment(shipment) {
  const response = await api(`/v1/shipments/${shipment.id}/track`, jsonRequest({}));
  if (!response.ok) return showError(response);
  const body = await response.json();
  updateFulfilmentShipment(body.shipment);
  showNotice("Tracking refreshed. No accounting entry was created.");
}

async function voidFulfilmentShipment(shipment) {
  const reason = window.prompt(
    "Why is this shipment being voided? The reason is kept with the shipment."
  );
  if (!reason || !reason.trim()) return;
  if (
    !window.confirm(
      "Ask the carrier to void this shipment? The carrier's response will decide the final state."
    )
  )
    return;
  const response = await api(
    `/v1/shipments/${shipment.id}/void`,
    jsonRequest({ version: shipment.version, reason: reason.trim() })
  );
  if (!response.ok) return showError(response);
  const body = await response.json();
  updateFulfilmentShipment(body.shipment);
  showNotice(
    "Carrier void response recorded. No accounting entry was created by the void request."
  );
}

// ---------------------------------------------------------------------------
// Sales tax code configuration
//
// PennyWise's tax engine already supports what a Canadian seller needs: a code
// holds one component per authority, each component carries a jurisdiction and
// its own payable account, and the invoice journal credits each component to
// that account (invoice-service.ts) and refuses to post if one is missing. None
// of it was reachable — POST /v1/setup/tax-codes/versions had no screen, so
// "GST to the federal account, PST to the provincial one" could not be
// expressed, and every provincial remittance was blocked behind that.
//
// This screen collects rates from the operator. It ships no rate table on
// purpose: rates change, and a stale hardcoded rate posted to a customer invoice
// is a liability. The API requires a source and a retrieval date, and so does
// this form.
// ---------------------------------------------------------------------------

let taxCodeComponentSeq = 0;

function taxParagraph(text, className) {
  const paragraph = document.createElement("p");
  if (className) paragraph.className = className;
  paragraph.textContent = text;
  return paragraph;
}

// The API takes a rate as a decimal string in 0..1 with up to six places, while
// operators think in percent. Convert by shifting the decimal point two places
// on the string itself — never with a float, because 9.975 / 100 is not exactly
// 0.09975 in binary floating point and a tax rate must be exact.
function taxPercentToRate(input) {
  const text = String(input ?? "").trim();
  if (!/^\d{1,3}(\.\d{1,4})?$/.test(text)) return null;
  const [whole, fraction = ""] = text.split(".");
  const digits = `${whole}${fraction}`.replace(/^0+(?=\d)/, "");
  const pointFromRight = fraction.length + 2;
  const padded = digits.padStart(pointFromRight + 1, "0");
  const cut = padded.length - pointFromRight;
  const result = `${padded.slice(0, cut)}.${padded.slice(cut)}`
    .replace(/0+$/, "")
    .replace(/\.$/, "");
  const normalized = result.startsWith(".") ? `0${result}` : result;
  if (!/^(0(\.\d{1,6})?|1(\.0{1,6})?)$/.test(normalized)) return null;
  return normalized;
}

function taxRateToPercent(rate) {
  const text = String(rate ?? "0");
  const [whole, fraction = ""] = text.split(".");
  const digits = `${whole}${fraction}`;
  const pointFromRight = Math.max(fraction.length - 2, 0);
  const padded = digits.padStart(pointFromRight + 1, "0");
  const cut = padded.length - pointFromRight;
  const shifted = pointFromRight
    ? `${padded.slice(0, cut)}.${padded.slice(cut)}`
    : `${padded}${"0".repeat(2 - fraction.length)}`;
  return shifted.replace(/^0+(?=\d)/, "").replace(/\.?0+$/, "") || "0";
}

function taxCodeAccountOptions(select, selectedId, types) {
  const choices = accounts.filter((account) => !account.isArchived && types.includes(account.type));
  select.replaceChildren(
    ...[
      Object.assign(document.createElement("option"), {
        value: "",
        textContent: "Choose an account"
      })
    ],
    ...choices.map((account) => {
      const option = document.createElement("option");
      option.value = account.id;
      option.textContent = `${account.code} ${account.name}`;
      option.selected = account.id === selectedId;
      return option;
    })
  );
}

function addTaxCodeComponentRow(values = {}) {
  const container = elements["tax-code-components"];
  if (!container) return;
  const index = (taxCodeComponentSeq += 1);
  const row = document.createElement("fieldset");
  row.className = "tax-code-component";
  row.dataset.componentRow = String(index);

  const legend = document.createElement("legend");
  legend.textContent = `Component ${String(container.children.length + 1)}`;
  row.append(legend);

  const grid = document.createElement("div");
  grid.className = "form-grid";

  const field = (labelText, node, help) => {
    const label = document.createElement("label");
    label.append(document.createTextNode(labelText), node);
    if (help) {
      const hint = document.createElement("span");
      hint.className = "field-help";
      hint.textContent = help;
      label.append(hint);
    }
    grid.append(label);
    return node;
  };

  const name = Object.assign(document.createElement("input"), {
    name: "componentName",
    required: true,
    maxLength: 80,
    placeholder: "GST",
    value: values.name ?? ""
  });
  field("Name", name);

  const jurisdiction = Object.assign(document.createElement("input"), {
    name: "componentJurisdiction",
    required: true,
    maxLength: 40,
    placeholder: "CA",
    value: values.jurisdiction ?? ""
  });
  field("Authority", jurisdiction, "Who this component is remitted to, for example CA or CA-BC.");

  const rate = Object.assign(document.createElement("input"), {
    name: "componentRate",
    required: true,
    inputMode: "decimal",
    placeholder: "5",
    value: values.rate ? taxRateToPercent(values.rate) : ""
  });
  field("Rate %", rate, "A percentage, for example 5 or 9.975.");

  const recoverable = Object.assign(document.createElement("input"), {
    name: "componentRecoverable",
    required: true,
    inputMode: "decimal",
    placeholder: "100",
    value: values.recoverablePercent ? taxRateToPercent(values.recoverablePercent) : "100"
  });
  field("Recoverable %", recoverable, "How much of this component is recoverable on purchases.");

  const payable = document.createElement("select");
  payable.name = "componentPayableAccount";
  payable.required = true;
  taxCodeAccountOptions(payable, values.payableAccountId, ["LIABILITY"]);
  field(
    "Payable account",
    payable,
    "Where a sale credits this component. A posted tax component without an account is refused."
  );

  const recoverableAccount = document.createElement("select");
  recoverableAccount.name = "componentRecoverableAccount";
  taxCodeAccountOptions(recoverableAccount, values.recoverableAccountId, ["ASSET"]);
  field("Recoverable account", recoverableAccount, "Where a purchase debits the recoverable part.");

  row.append(grid);

  const remove = document.createElement("button");
  remove.type = "button";
  remove.className = "text-command";
  remove.textContent = "Remove component";
  remove.addEventListener("click", () => {
    row.remove();
    renumberTaxCodeComponents();
    renderTaxCodePreview();
  });
  row.append(remove);

  for (const control of row.querySelectorAll("input, select"))
    control.addEventListener("input", renderTaxCodePreview);

  container.append(row);
  renumberTaxCodeComponents();
  renderTaxCodePreview();
}

function renumberTaxCodeComponents() {
  const container = elements["tax-code-components"];
  if (!container) return;
  [...container.children].forEach((row, index) => {
    const legend = row.querySelector("legend");
    if (legend) legend.textContent = `Component ${String(index + 1)}`;
  });
  const add = elements["tax-code-add-component"];
  // The API caps a version at five components.
  if (add) add.disabled = container.children.length >= 5;
}

function readTaxCodeComponents() {
  const container = elements["tax-code-components"];
  if (!container) return [];
  return [...container.children].map((row) => {
    const value = (name) => row.querySelector(`[name="${name}"]`)?.value?.trim() ?? "";
    return {
      name: value("componentName"),
      jurisdiction: value("componentJurisdiction"),
      ratePercent: value("componentRate"),
      recoverablePercent: value("componentRecoverable"),
      payableAccountId: value("componentPayableAccount"),
      recoverableAccountId: value("componentRecoverableAccount")
    };
  });
}

// An operator is configuring double-entry consequences through a form about
// percentages. Show the consequence before they save it.
function renderTaxCodePreview() {
  const body = elements["tax-code-preview-body"];
  if (!body) return;
  const treatment = elements["tax-code-form"]?.elements.treatment?.value ?? "STANDARD";
  const components = readTaxCodeComponents();
  if (treatment !== "STANDARD") {
    body.replaceChildren(
      taxParagraph(
        treatment === "ZERO_RATED"
          ? "A sale using this code charges no tax and credits no tax account. The sale is still reported as a zero-rated supply, and input tax credits on related purchases are kept."
          : "A sale using this code charges no tax and credits no tax account. The sale is reported as exempt, and input tax credits on related purchases are lost.",
        null
      )
    );
    return;
  }
  if (components.length === 0) {
    body.replaceChildren(
      taxParagraph("Add a component to see the accounts a sale would use.", "empty-state")
    );
    return;
  }
  const list = document.createElement("ul");
  list.className = "tax-code-preview-list";
  for (const component of components) {
    const account = accounts.find((candidate) => candidate.id === component.payableAccountId);
    const item = document.createElement("li");
    const rate = component.ratePercent ? `${component.ratePercent}%` : "no rate";
    item.textContent = account
      ? `On a 100.00 sale, ${component.name || "this component"} at ${rate} credits ${account.code} ${account.name}.`
      : `${component.name || "This component"} at ${rate} has no payable account yet, so a sale using this code cannot post.`;
    if (!account) item.dataset.state = "blocked";
    list.append(item);
  }
  body.replaceChildren(list);
}

function renderTaxCodeList() {
  const container = elements["tax-code-list"];
  if (!container) return;
  const codes = setup?.taxCodes ?? [];
  if (codes.length === 0) {
    container.replaceChildren(
      taxParagraph("No tax codes yet. A sale cannot charge tax until one exists.", "empty-state")
    );
    return;
  }
  container.replaceChildren(
    ...codes.map((code) => {
      const version = code.versions?.[0];
      const card = document.createElement("article");
      card.className = "tax-code-card";

      const heading = document.createElement("h4");
      heading.textContent = `${code.code} — ${code.name}`;
      card.append(heading);

      const meta = document.createElement("p");
      meta.className = "tax-code-card-meta";
      meta.textContent = version
        ? `Version ${String(version.version)} · ${version.treatment} · ${version.calculationMode} · from ${String(version.effectiveFrom).slice(0, 10)}${version.effectiveTo ? ` to ${String(version.effectiveTo).slice(0, 10)}` : ""}`
        : "No effective version";
      card.append(meta);

      if (version?.components?.length) {
        const list = document.createElement("ul");
        list.className = "tax-code-card-components";
        for (const component of version.components) {
          const account = accounts.find((candidate) => candidate.id === component.payableAccountId);
          const item = document.createElement("li");
          item.textContent = `${component.name} · ${component.jurisdiction} · ${taxRateToPercent(component.rate)}% → ${account ? `${account.code} ${account.name}` : "no payable account"}`;
          if (!account) item.dataset.state = "blocked";
          list.append(item);
        }
        card.append(list);
      }

      if (version?.sourceName) {
        const source = document.createElement("p");
        source.className = "tax-code-card-source";
        source.textContent = `Source: ${version.sourceName}${version.sourceRetrievedAt ? `, checked ${String(version.sourceRetrievedAt).slice(0, 10)}` : ""}`;
        card.append(source);
      }

      const reversion = document.createElement("button");
      reversion.type = "button";
      reversion.className = "secondary-command";
      reversion.textContent = "New version of this code";
      reversion.addEventListener("click", () => prefillTaxCodeForm(code));
      card.append(reversion);
      return card;
    })
  );
}

function prefillTaxCodeForm(code) {
  const form = elements["tax-code-form"];
  if (!form) return;
  const version = code.versions?.[0];
  form.elements.code.value = code.code;
  form.elements.name.value = code.name;
  if (version) {
    form.elements.treatment.value = version.treatment;
    form.elements.calculationMode.value = version.calculationMode;
    form.elements.sourceName.value = version.sourceName ?? "";
    form.elements.sourceUrl.value = version.sourceUrl ?? "";
  }
  elements["tax-code-components"].replaceChildren();
  for (const component of version?.components ?? []) addTaxCodeComponentRow(component);
  if ((version?.components?.length ?? 0) === 0) addTaxCodeComponentRow();
  renderTaxCodePreview();
  form.scrollIntoView({ behavior: preferredScrollBehavior(), block: "start" });
  showNotice(`Editing a new version of ${code.code}. Set the effective dates before saving.`);
}

async function saveTaxCodeVersion(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const data = new FormData(form);
  const treatment = String(data.get("treatment"));
  const rawComponents = readTaxCodeComponents();

  if (treatment === "STANDARD" && rawComponents.length === 0) {
    showNotice("A standard tax code needs at least one component.", true);
    return;
  }

  const components = [];
  for (const component of rawComponents) {
    const rate = taxPercentToRate(component.ratePercent);
    const recoverable = taxPercentToRate(component.recoverablePercent);
    if (rate === null) {
      showNotice(`Enter a valid rate for ${component.name || "the component"}.`, true);
      return;
    }
    if (recoverable === null) {
      showNotice(
        `Enter a valid recoverable percentage for ${component.name || "the component"}.`,
        true
      );
      return;
    }
    // invoice-service refuses to post a tax component without a payable account.
    // Refuse it here so the operator learns now rather than at posting time.
    if (!component.payableAccountId) {
      showNotice(
        `Choose a payable account for ${component.name || "the component"}. A sale cannot post without it.`,
        true
      );
      return;
    }
    components.push({
      name: component.name,
      jurisdiction: component.jurisdiction,
      rate,
      recoverablePercent: recoverable,
      payableAccountId: component.payableAccountId,
      ...(component.recoverableAccountId
        ? { recoverableAccountId: component.recoverableAccountId }
        : {})
    });
  }

  const retrieved = String(data.get("sourceRetrievedAt"));
  const body = {
    code: String(data.get("code")).trim().toUpperCase(),
    name: String(data.get("name")).trim(),
    treatment,
    calculationMode: String(data.get("calculationMode")),
    effectiveFrom: String(data.get("effectiveFrom")),
    ...(data.get("effectiveTo") ? { effectiveTo: String(data.get("effectiveTo")) } : {}),
    sourceName: String(data.get("sourceName")).trim(),
    ...(data.get("sourceUrl") ? { sourceUrl: String(data.get("sourceUrl")).trim() } : {}),
    sourceRetrievedAt: new Date(`${retrieved}T00:00:00Z`).toISOString(),
    components
  };

  const existing = (setup?.taxCodes ?? []).find((candidate) => candidate.code === body.code);
  if (existing?.version) body.expectedTaxCodeVersion = existing.version;

  const response = await api("/v1/setup/tax-codes/versions", jsonRequest(body));
  if (!response.ok) return showError(response);
  const savedTaxCode = (await response.json()).taxCodeVersion;
  showNotice(`Tax code ${body.code} saved.`);
  form.reset();
  elements["tax-code-components"].replaceChildren();
  renumberTaxCodeComponents();
  renderTaxCodePreview();
  const returnToProduct = contextualCreationState?.kind === "tax-code";
  await refreshSetupState();
  if (returnToProduct) await loadSales();
  completeContextualCreation(savedTaxCode?.taxCodeId ?? savedTaxCode?.id);
}

function refreshTaxCodeComponentAccounts() {
  const container = elements["tax-code-components"];
  if (!container) return;
  for (const row of container.children) {
    const payable = row.querySelector('[name="componentPayableAccount"]');
    const recoverable = row.querySelector('[name="componentRecoverableAccount"]');
    if (payable) taxCodeAccountOptions(payable, payable.value, ["LIABILITY"]);
    if (recoverable) taxCodeAccountOptions(recoverable, recoverable.value, ["ASSET"]);
  }
  renderTaxCodePreview();
}

// A brand-new local browser has no identity yet. Avoid a guaranteed 401 while
// the local identity form is available; it also removes a race with a user
// selecting that identity during page boot. Controlled shares and signed-in
// browsers still initialize their session immediately.
if (controlledShareMode || localIdentityEmail || !localIdentityEnabled) await loadSession();
else showSignedOut();
await completeEtsyOAuthFromCallback();
const noticeAfterReload = sessionStorage.getItem("clearledger_notice_after_reload");
if (noticeAfterReload) {
  sessionStorage.removeItem("clearledger_notice_after_reload");
  showNotice(noticeAfterReload);
}
